{
  "name": "UAE Labour Market Intelligence",
  "description": "A ministerial-grade bilateral reporting tool for the UAE Ministry to generate labour market intelligence reports."
}

export type Language = 'en' | 'ar';
export type ReportStatus = 'draft' | 'completed';
export type UserRole = 'admin' | 'user';

export interface UserProfile {
  id: string;
  email: string;
  fullName: string;
  role: UserRole;
  avatarUrl?: string;
}

// Complex Report Structure
export interface ReportData {
  country: string;
  capital: string;
  population: string;
  currency: string;
  gdpGrowth: string;
  bilateralAgreements: Array<{
    title: string;
    date: string;
    status: 'Active' | 'Pending' | 'Expired';
    summary: string;
  }>;
  workforceStats: {
    totalWorkers: number;
    malePercentage: number;
    femalePercentage: number;
    topSectors: Array<{ name: string; value: number }>;
  };
  keyIssues: string[];
  recommendations: string[];
  delegation: Array<{
    name: string;
    title: string;
    imageUrl: string;
  }>;
}

export interface Report {
  id: string;
  userId: string;
  title: string;
  status: ReportStatus;
  updatedAt: string;
  data: ReportData;
}

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  timestamp: string;
  details: string;
}

export const EMPTY_REPORT_DATA: ReportData = {
  country: '',
  capital: '',
  population: '',
  currency: '',
  gdpGrowth: '',
  bilateralAgreements: [],
  workforceStats: {
    totalWorkers: 0,
    malePercentage: 0,
    femalePercentage: 0,
    topSectors: [],
  },
  keyIssues: [],
  recommendations: [],
  delegation: [],
};

import { Report, AuditLog } from '../types';
import { MOCK_REPORTS, MOCK_AUDIT_LOGS } from '../constants';

// Simulating API Latency
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const MockService = {
  getReports: async (): Promise<Report[]> => {
    await delay(600);
    return [...MOCK_REPORTS];
  },

  getReportById: async (id: string): Promise<Report | undefined> => {
    await delay(400);
    return MOCK_REPORTS.find(r => r.id === id);
  },

  saveReport: async (report: Report): Promise<void> => {
    await delay(800);
    const index = MOCK_REPORTS.findIndex(r => r.id === report.id);
    if (index >= 0) {
      MOCK_REPORTS[index] = report;
    } else {
      MOCK_REPORTS.push(report);
    }
  },

  getAuditLogs: async (): Promise<AuditLog[]> => {
    await delay(500);
    return [...MOCK_AUDIT_LOGS];
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Language } from '../types';
import { TRANSLATIONS } from '../constants';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: keyof typeof TRANSLATIONS.en) => string;
  dir: 'ltr' | 'rtl';
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [language, setLanguage] = useState<Language>('en');

  const dir = language === 'ar' ? 'rtl' : 'ltr';

  useEffect(() => {
    document.documentElement.dir = dir;
    document.documentElement.lang = language;

    // Change font family based on language
    if (language === 'ar') {
      document.body.style.fontFamily = "'Noto Naskh Arabic', serif";
    } else {
      document.body.style.fontFamily = "'Inter', sans-serif";
    }
  }, [language, dir]);

  const t = (key: keyof typeof TRANSLATIONS.en) => {
    return TRANSLATIONS[language][key] || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t, dir }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within a LanguageProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { UserProfile } from '../types';

interface AuthContextType {
  user: UserProfile | null;
  isLoading: boolean;
  signIn: () => Promise<void>;
  signOut: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const MOCK_USER: UserProfile = {
  id: 'u-1',
  email: 'official@mohre.gov.ae',
  fullName: 'Ahmed Al-Mansouri',
  role: 'admin',
  avatarUrl: 'https://ui-avatars.com/api/?name=Ahmed+Al-Mansouri&background=0D8ABC&color=fff'
};

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Check local storage for session
    const stored = localStorage.getItem('auth_session');
    if (stored) {
      setUser(JSON.parse(stored));
    }
    setIsLoading(false);
  }, []);

  const signIn = async () => {
    setIsLoading(true);
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1000));
    setUser(MOCK_USER);
    localStorage.setItem('auth_session', JSON.stringify(MOCK_USER));
    setIsLoading(false);
  };

  const signOut = () => {
    setUser(null);
    localStorage.removeItem('auth_session');
  };

  return (
    <AuthContext.Provider value={{ user, isLoading, signIn, signOut }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

import React from 'react';

export const Card: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-white rounded-xl shadow-card border border-secondary/50 p-6 ${className}`}>
    {children}
  </div>
);

export const Button: React.FC<React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'outline' | 'ghost' }> = 
  ({ children, className = '', variant = 'primary', ...props }) => {
    const base = "px-4 py-2 rounded-lg font-medium transition-all duration-200 flex items-center justify-center gap-2";
    const variants = {
      primary: "bg-primary text-white hover:bg-primary-light shadow-md hover:shadow-lg active:scale-95",
      outline: "border-2 border-primary text-primary hover:bg-primary/5 active:scale-95",
      ghost: "text-foreground hover:bg-secondary active:scale-95"
    };

    return (
      <button className={`${base} ${variants[variant]} ${className}`} {...props}>
        {children}
      </button>
    );
};

export const Input: React.FC<React.InputHTMLAttributes<HTMLInputElement> & { label?: string }> = ({ label, className = '', ...props }) => (
  <div className="flex flex-col gap-1.5">
    {label && <label className="text-sm font-semibold text-foreground/80">{label}</label>}
    <input 
      className={`w-full px-4 py-2 rounded-lg border border-gray-300 focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none transition-all ${className}`} 
      {...props} 
    />
  </div>
);

export const Badge: React.FC<{ children: React.ReactNode; color?: 'green' | 'blue' | 'yellow' }> = ({ children, color = 'blue' }) => {
  const colors = {
    green: 'bg-green-100 text-green-800 border-green-200',
    blue: 'bg-blue-100 text-blue-800 border-blue-200',
    yellow: 'bg-yellow-100 text-yellow-800 border-yellow-200'
  };
  return (
    <span className={`px-2.5 py-0.5 rounded-full text-xs font-semibold border ${colors[color]}`}>
      {children}
    </span>
  );
};

