import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { ReportData, EMPTY_REPORT_DATA, Report } from '../types';
import { MockService } from '../services/mockService';
import { Button, Card, Input } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'workforce', icon: Users, label: 'Workforce' },
  { id: 'agreements', icon: FileText, label: 'Agreements' },
  { id: 'preview', icon: CheckCircle, label: 'Preview' },
];

export default function Wizard() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(!!id);
  const [data, setData] = useState<ReportData>(EMPTY_REPORT_DATA);
  const [reportTitle, setReportTitle] = useState('');

  useEffect(() => {
    if (id) {
      MockService.getReportById(id).then(r => {
        if (r) {
          setData(r.data);
          setReportTitle(r.title);
        }
        setLoading(false);
      });
    }
  }, [id]);

  const handleSave = async (status: 'draft' | 'completed' = 'draft') => {
    const reportId = id || `r-${uuidv4().slice(0, 8)}`;
    const newReport: Report = {
      id: reportId,
      userId: 'u-1',
      title: reportTitle || `Report for ${data.country || 'Unknown'}`,
      status,
      updatedAt: new Date().toISOString(),
      data
    };
    await MockService.saveReport(newReport);
    if (status === 'completed') {
      navigate('/dashboard');
    } else {
      // Show toast or slight feedback
      console.log('Saved draft');
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-right-4 duration-300">
            <Input 
              label={t('country')} 
              value={data.country} 
              onChange={e => setData({...data, country: e.target.value})} 
              placeholder="e.g. India"
            />
            <Input 
              label={t('capital')} 
              value={data.capital} 
              onChange={e => setData({...data, capital: e.target.value})} 
            />
            <Input 
              label="Population" 
              value={data.population} 
              onChange={e => setData({...data, population: e.target.value})} 
            />
            <Input 
              label="Currency" 
              value={data.currency} 
              onChange={e => setData({...data, currency: e.target.value})} 
            />
            <Input 
              label="GDP Growth Rate" 
              value={data.gdpGrowth} 
              onChange={e => setData({...data, gdpGrowth: e.target.value})} 
            />
            <div className="md:col-span-2">
              <label className="text-sm font-semibold text-foreground/80 block mb-2">Key Issues</label>
              <textarea 
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-primary/20 outline-none"
                rows={4}
                value={data.keyIssues.join('\n')}
                onChange={e => setData({...data, keyIssues: e.target.value.split('\n')})}
                placeholder="One issue per line..."
              />
            </div>
          </div>
        );
      case 1:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <Input 
                type="number"
                label="Total Workers in UAE" 
                value={data.workforceStats.totalWorkers} 
                onChange={e => setData({
                  ...data, 
                  workforceStats: {...data.workforceStats, totalWorkers: parseInt(e.target.value) || 0}
                })} 
              />
              <Input 
                type="number"
                label="Male %" 
                value={data.workforceStats.malePercentage} 
                onChange={e => setData({
                  ...data, 
                  workforceStats: {...data.workforceStats, malePercentage: parseInt(e.target.value) || 0}
                })} 
              />
              <Input 
                type="number"
                label="Female %" 
                value={data.workforceStats.femalePercentage} 
                onChange={e => setData({
                  ...data, 
                  workforceStats: {...data.workforceStats, femalePercentage: parseInt(e.target.value) || 0}
                })} 
              />
            </div>
            <div>
               <h3 className="font-semibold mb-4">Top Sectors</h3>
               {data.workforceStats.topSectors.map((sector, idx) => (
                 <div key={idx} className="flex gap-4 mb-2">
                   <Input 
                    placeholder="Sector Name"
                    className="flex-1"
                    value={sector.name}
                    onChange={(e) => {
                      const newSectors = [...data.workforceStats.topSectors];
                      newSectors[idx].name = e.target.value;
                      setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   />
                   <Input 
                    placeholder="%"
                    type="number"
                    className="w-24"
                    value={sector.value}
                    onChange={(e) => {
                      const newSectors = [...data.workforceStats.topSectors];
                      newSectors[idx].value = parseInt(e.target.value);
                      setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   />
                 </div>
               ))}
               <Button 
                variant="outline" 
                size="sm"
                onClick={() => setData({
                  ...data, 
                  workforceStats: {
                    ...data.workforceStats, 
                    topSectors: [...data.workforceStats.topSectors, {name: '', value: 0}]
                  }
                })}
              >
                + Add Sector
              </Button>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
