import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { ReportData, EMPTY_REPORT_DATA, Report } from '../types';
import { MockService } from '../services/mockService';
import { Button, Card, Input, Badge } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle, Plane, Building, TrendingUp, Sparkles, Loader2 } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from "@google/genai";

const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'workforce', icon: Users, label: 'Workforce & Economy' },
  { id: 'agreements', icon: FileText, label: 'Agreements' },
  { id: 'preview', icon: CheckCircle, label: 'Preview' },
];

export default function Wizard() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(!!id);
  const [isFetchingAI, setIsFetchingAI] = useState(false);
  const [data, setData] = useState<ReportData>(EMPTY_REPORT_DATA);
  const [reportTitle, setReportTitle] = useState('');

  useEffect(() => {
    if (id) {
      MockService.getReportById(id).then(r => {
        if (r) {
          setData(r.data);
          setReportTitle(r.title);
        }
        setLoading(false);
      });
    }
  }, [id]);

  const handleFetchData = async () => {
    if (!data.country) return;
    setIsFetchingAI(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Generate a JSON object for a labour market intelligence report for ${data.country}.
        The response MUST be valid JSON matching this structure exactly, do not wrap in markdown code blocks:
        {
          "capital": "string",
          "officialLanguage": "string",
          "population": "string (e.g. 1.4B)",
          "currency": "string",
          "gdp": "string (e.g. 400 Billion USD)",
          "hdi": "string (e.g. 0.750)",
          "directFlight": boolean,
          "uaeEmbassyLocation": "string (City in target country)",
          "foreignEmbassyLocation": "string (City in UAE, usually Abu Dhabi or Dubai)",
          "averageWage": "string (e.g. $400/month)",
          "minimumWage": "string (e.g. $200/month)",
          "totalWorkforce": "string (e.g. 50 Million)",
          "participationMale": number (percentage 0-100),
          "participationFemale": number (percentage 0-100),
          "migrationDestinations": ["string", "string"],
          "topSectors": [{"name": "string", "value": number}, {"name": "string", "value": number}]
        }`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        // Basic cleanup if model adds markdown
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          ...aiData,
          workforceStats: {
            ...prev.workforceStats,
            totalWorkforce: aiData.totalWorkforce,
            participationMale: aiData.participationMale,
            participationFemale: aiData.participationFemale,
            migrationDestinations: aiData.migrationDestinations,
            topSectors: aiData.topSectors
          }
        }));
      } else {
         // Fallback simulation if no API key is present for demo purposes
         await new Promise(r => setTimeout(r, 2000));
         setData(prev => ({
           ...prev,
           capital: 'Simulated Capital',
           officialLanguage: 'Simulated Language',
           population: '50M',
           currency: 'Unit',
           gdp: '500 Billion USD',
           hdi: '0.750',
           directFlight: true,
           uaeEmbassyLocation: 'Capital City',
           foreignEmbassyLocation: 'Abu Dhabi',
           averageWage: '$450/month',
           minimumWage: '$200/month',
           workforceStats: {
             ...prev.workforceStats,
             totalWorkforce: '25 Million',
             participationMale: 65,
             participationFemale: 35,
             migrationDestinations: ['UAE', 'Saudi Arabia', 'UK'],
             topSectors: [{name: 'Services', value: 50}, {name: 'Agriculture', value: 30}, {name: 'Industry', value: 20}]
           }
         }));
      }
    } catch (error) {
      console.error("AI Fetch failed", error);
    } finally {
      setIsFetchingAI(false);
    }
  };

  const handleSave = async (status: 'draft' | 'completed' = 'draft') => {
    const reportId = id || `r-${uuidv4().slice(0, 8)}`;
    const newReport: Report = {
      id: reportId,
      userId: 'u-1',
      title: reportTitle || `Report for ${data.country || 'Unknown'}`,
      status,
      updatedAt: new Date().toISOString(),
      data
    };
    await MockService.saveReport(newReport);
    if (status === 'completed') {
      navigate('/dashboard');
    } else {
      console.log('Saved draft');
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
             {/* Country & AI Fetch Row */}
            <div className="flex flex-col md:flex-row gap-4 items-end bg-blue-50/50 p-6 rounded-xl border border-blue-100">
               <div className="flex-1 w-full">
                 <Input 
                    label={t('country')} 
                    value={data.country} 
                    onChange={e => setData({...data, country: e.target.value})} 
                    placeholder="e.g. Vietnam"
                    className="text-lg font-medium"
                  />
               </div>
               <Button 
                onClick={handleFetchData} 
                disabled={!data.country || isFetchingAI}
                className="w-full md:w-auto bg-accent hover:bg-accent-light text-white border-none shadow-lg"
              >
                {isFetchingAI ? <Loader2 className="animate-spin" /> : <Sparkles size={18} />}
                Fetch Data (ILO/WB)
               </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {/* Basic Info */}
              <Input 
                label={t('capital')} 
                value={data.capital} 
                onChange={e => setData({...data, capital: e.target.value})} 
              />
              <Input 
                label="Official Language" 
                value={data.officialLanguage} 
                onChange={e => setData({...data, officialLanguage: e.target.value})} 
              />
              <Input 
                label="Population" 
                value={data.population} 
                onChange={e => setData({...data, population: e.target.value})} 
              />
              <Input 
                label="Currency" 
                value={data.currency} 
                onChange={e => setData({...data, currency: e.target.value})} 
              />

              {/* Economic Indicators */}
              <Input 
                label="GDP (Gross Domestic Product)" 
                value={data.gdp} 
                onChange={e => setData({...data, gdp: e.target.value})} 
                placeholder="e.g. 400 Billion USD"
              />
              <Input 
                label="HDI (Human Development Index)" 
                value={data.hdi} 
                onChange={e => setData({...data, hdi: e.target.value})} 
                placeholder="e.g. 0.704"
              />

              {/* Diplomacy & Travel */}
              <div className="flex flex-col gap-1.5">
                 <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Plane size={14} /> Direct Flight to UAE
                 </label>
                 <div className="flex gap-4 mt-2">
                    <button 
                      onClick={() => setData({...data, directFlight: true})}
                      className={`flex-1 py-2 rounded-lg border transition-all ${data.directFlight ? 'bg-primary text-white border-primary' : 'bg-white text-gray-500'}`}
                    >Yes</button>
                    <button 
                      onClick={() => setData({...data, directFlight: false})}
                      className={`flex-1 py-2 rounded-lg border transition-all ${!data.directFlight ? 'bg-primary text-white border-primary' : 'bg-white text-gray-500'}`}
                    >No</button>
                 </div>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Building size={14} /> UAE Embassy Location
                </label>
                <Input 
                  value={data.uaeEmbassyLocation} 
                  onChange={e => setData({...data, uaeEmbassyLocation: e.target.value})} 
                  placeholder="City in target country"
                />
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Building size={14} /> {data.country || 'Foreign'} Embassy in UAE
                </label>
                <Input 
                  value={data.foreignEmbassyLocation} 
                  onChange={e => setData({...data, foreignEmbassyLocation: e.target.value})} 
                  placeholder="e.g. Abu Dhabi"
                />
              </div>
            </div>
          </div>
        );
      case 1:
        return (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
            {/* Wages Section */}
            <div>
               <h3 className="text-lg font-serif font-bold text-primary mb-4 flex items-center gap-2">
                 <TrendingUp size={20} /> Wages & Income
               </h3>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-gray-50 p-6 rounded-xl border">
                 <Input 
                    label="Average Monthly Wage" 
                    value={data.averageWage} 
                    onChange={e => setData({...data, averageWage: e.target.value})} 
                    placeholder="e.g. $350/month"
                 />
                 <Input 
                    label="Minimum Monthly Wage" 
                    value={data.minimumWage} 
                    onChange={e => setData({...data, minimumWage: e.target.value})} 
                    placeholder="e.g. $180/month"
                 />
               </div>
            </div>

            {/* Workforce Stats */}
            <div>
              <h3 className="text-lg font-serif font-bold text-primary mb-4 flex items-center gap-2">
                 <Users size={20} /> Workforce Composition
               </h3>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <Input 
                    label="Total Workforce Size" 
                    value={data.workforceStats.totalWorkforce} 
                    onChange={e => setData({...data, workforceStats: {...data.workforceStats, totalWorkforce: e.target.value}})} 
                    placeholder="e.g. 55 Million"
                  />
                  <Input 
                    type="number"
                    label="Male Participation (%)" 
                    value={data.workforceStats.participationMale} 
                    onChange={e => setData({...data, workforceStats: {...data.workforceStats, participationMale: Number(e.target.value)}})} 
                  />
                  <Input 
                    type="number"
                    label="Female Participation (%)" 
                    value={data.workforceStats.participationFemale} 
                    onChange={e => setData({...data, workforceStats: {...data.workforceStats, participationFemale: Number(e.target.value)}})} 
                  />
               </div>
            </div>

            {/* Migration */}
            <div>
               <label className="text-sm font-semibold text-foreground/80 block mb-2">Top Migration Destinations</label>
               <div className="bg-white border rounded-lg p-2 flex flex-wrap gap-2 min-h-[50px]">
                  {data.workforceStats.migrationDestinations.map((dest, i) => (
                    <span key={i} className="bg-primary/10 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2">
                      {dest}
                      <button 
                        onClick={() => {
                          const newDest = data.workforceStats.migrationDestinations.filter((_, idx) => idx !== i);
                          setData({...data, workforceStats: {...data.workforceStats, migrationDestinations: newDest}});
                        }}
                        className="hover:text-red-500"
                      >x</button>
                    </span>
                  ))}
                  <input 
                    placeholder={data.workforceStats.migrationDestinations.length === 0 ? "Type country and press Enter..." : "+ Add"}
                    className="flex-1 outline-none min-w-[120px] px-2"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        const val = e.currentTarget.value.trim();
                        if (val) {
                          setData({...data, workforceStats: {
                            ...data.workforceStats, 
                            migrationDestinations: [...data.workforceStats.migrationDestinations, val]
                          }});
                          e.currentTarget.value = '';
                        }
                      }
                    }}
                  />
               </div>
               <p className="text-xs text-gray-400 mt-1">Press Enter to add a country</p>
            </div>

            {/* Sector Distribution */}
            <div>
               <h3 className="font-semibold mb-4">Workforce Distribution by Sector</h3>
               {data.workforceStats.topSectors.map((sector, idx) => (
                 <div key={idx} className="flex gap-4 mb-2">
                   <Input 
                    placeholder="Sector Name"
                    className="flex-1"
                    value={sector.name}
                    onChange={(e) => {
                      const newSectors = [...data.workforceStats.topSectors];
                      newSectors[idx].name = e.target.value;
                      setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   />
                   <Input 
                    placeholder="%"
                    type="number"
                    className="w-24"
                    value={sector.value}
                    onChange={(e) => {
                      const newSectors = [...data.workforceStats.topSectors];
                      newSectors[idx].value = parseInt(e.target.value);
                      setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   />
                   <button 
                    className="text-red-400 hover:text-red-600 px-2"
                    onClick={() => {
                       const newSectors = data.workforceStats.topSectors.filter((_, i) => i !== idx);
                       setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   >x</button>
                 </div>
               ))}
               <Button 
                variant="outline" 
                size="sm"
                onClick={() => setData({
                  ...data, 
                  workforceStats: {
                    ...data.workforceStats, 
                    topSectors: [...data.workforceStats.topSectors, {name: '', value: 0}]
                  }
                })}
              >
                + Add Sector
              </Button>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            {data.bilateralAgreements.length === 0 && (
              <div className="text-center p-8 text-gray-400 bg-gray-50 rounded-lg border border-dashed">
                No agreements recorded. Add one below.
              </div>
            )}
            {data.bilateralAgreements.map((agreement, idx) => (
               <Card key={idx} className="relative">
                 <button 
                  className="absolute top-2 right-2 text-red-500 hover:bg-red-50 p-1 rounded"
                  onClick={() => {
                    const filtered = data.bilateralAgreements.filter((_, i) => i !== idx);
                    setData({...data, bilateralAgreements: filtered});
                  }}
                 >x</button>
                 <div className="grid gap-4">
                   <Input 
                      label="Title" 
                      value={agreement.title}
                      onChange={(e) => {
                        const ag = [...data.bilateralAgreements];
                        ag[idx].title = e.target.value;
                        setData({...data, bilateralAgreements: ag});
                      }}
                   />
                   <div className="grid grid-cols-2 gap-4">
                    <Input 
                        type="date"
                        label="Date" 
                        value={agreement.date}
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].date = e.target.value;
                          setData({...data, bilateralAgreements: ag});
                        }}
                    />
                     <div>
                       <label className="text-sm font-semibold text-foreground/80 block mb-1.5">Status</label>
                       <select 
                        className="w-full px-4 py-2 rounded-lg border border-gray-300 bg-white"
                        value={agreement.status}
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].status = e.target.value as any;
                          setData({...data, bilateralAgreements: ag});
                        }}
                       >
                         <option>Active</option>
                         <option>Pending</option>
                         <option>Expired</option>
                       </select>
                     </div>
                   </div>
                   <Input 
                      label="Summary" 
                      value={agreement.summary}
                      onChange={(e) => {
                        const ag = [...data.bilateralAgreements];
                        ag[idx].summary = e.target.value;
                        setData({...data, bilateralAgreements: ag});
                      }}
                   />
                 </div>
               </Card>
            ))}
            <Button 
              variant="outline"
              onClick={() => setData({
                ...data, 
                bilateralAgreements: [...data.bilateralAgreements, { title: '', date: '', status: 'Active', summary: '' }]
              })}
            >
              + Add Agreement
            </Button>
          </div>
        );
      case 3:
        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
            <div className="bg-gray-100 p-8 rounded-xl border border-gray-200">
              <h2 className="font-serif text-2xl mb-4 text-center">{reportTitle}</h2>
              <div className="bg-white p-8 shadow-diplomatic max-w-2xl mx-auto space-y-6">
                <div className="flex items-center gap-4 border-b pb-4">
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('country')}</p>
                    <p className="text-xl font-bold">{data.country}</p>
                  </div>
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('capital')}</p>
                    <p className="text-xl font-bold">{data.capital}</p>
                  </div>
                </div>
                <div>
                  <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">{t('agreements')}</h3>
                  <ul className="list-disc ml-5 space-y-1">
                    {data.bilateralAgreements.map((a, i) => (
                      <li key={i}><span className="font-medium">{a.title}</span> ({a.status})</li>
                    ))}
                  </ul>
                </div>
                <div className="p-4 bg-blue-50 text-blue-800 rounded text-center text-sm">
                  This is a preview. Click "Complete Report" to finalize.
                </div>
              </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  if (loading) return <div className="p-8 text-center">Loading...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-12">
      {/* Wizard Header */}
      <div className="mb-8">
        <Input 
          placeholder="Report Title (e.g. Bilateral Meeting India 2024)"
          className="text-2xl font-serif font-bold bg-transparent border-transparent px-0 focus:ring-0 focus:border-primary placeholder:text-gray-300"
          value={reportTitle}
          onChange={(e) => setReportTitle(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Steps Sidebar */}
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'}
                ${idx < currentStep ? 'text-primary font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        {/* Content Area */}
        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button 
              variant="ghost" 
              onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
              disabled={currentStep === 0}
            >
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} />
              {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}>
                <Save size={16} />
                {t('save')}
              </Button>

              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>
                  {t('next')}
                  <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} />
                </Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">
                  {t('finish')}
                  <CheckCircle size={16} />
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { LanguageProvider } from './context/LanguageContext';
import Layout from './components/Layout';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Wizard from './pages/Wizard';
import PrintView from './pages/PrintView';

// Route Guard Component
const ProtectedRoute = ({ children }: { children?: React.ReactNode }) => {
  const { user, isLoading } = useAuth();
  if (isLoading) return <div className="h-screen flex items-center justify-center">Loading...</div>;
  if (!user) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const AppRoutes = () => {
  return (
    <Routes>
      <Route path="/login" element={<Login />} />
      <Route path="/print/:id" element={<PrintView />} />

      <Route path="/" element={<ProtectedRoute><Layout /></ProtectedRoute>}>
        <Route index element={<Navigate to="/dashboard" replace />} />
        <Route path="dashboard" element={<Dashboard />} />
        <Route path="wizard" element={<Wizard />} />
        <Route path="wizard/:id" element={<Wizard />} />
        <Route path="account" element={<div className="p-8">Account Settings Placeholder</div>} />
      </Route>
    </Routes>
  );
};

export default function App() {
  return (
    <LanguageProvider>
      <AuthProvider>
        <HashRouter>
          <AppRoutes />
        </HashRouter>
      </AuthProvider>
    </LanguageProvider>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { ReportData, EMPTY_REPORT_DATA, Report } from '../types';
import { MockService } from '../services/mockService';
import { Button, Card, Input } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle, Plane, Building, TrendingUp, Sparkles, Loader2, RefreshCw } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from "@google/genai";

const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'workforce', icon: Users, label: 'Workforce & Economy' },
  { id: 'agreements', icon: FileText, label: 'Agreements' },
  { id: 'preview', icon: CheckCircle, label: 'Preview' },
];

export default function Wizard() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(!!id);
  const [isFetchingAI, setIsFetchingAI] = useState(false);
  const [data, setData] = useState<ReportData>(EMPTY_REPORT_DATA);
  const [reportTitle, setReportTitle] = useState('');

  useEffect(() => {
    if (id) {
      MockService.getReportById(id).then(r => {
        if (r) {
          setData(r.data);
          setReportTitle(r.title);
        }
        setLoading(false);
      });
    }
  }, [id]);

  const handleFetchData = async () => {
    if (!data.country) return;
    setIsFetchingAI(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as a labour market intelligence expert. Fetch the latest available data from ILO (International Labour Organization), World Bank, and official government sources for ${data.country}.

        Return a strictly valid JSON object (no markdown, no code blocks) matching this structure exactly:
        {
          "capital": "string",
          "officialLanguage": "string",
          "population": "string (e.g. 1.4B)",
          "currency": "string",
          "gdp": "string (e.g. 400 Billion USD)",
          "hdi": "string (e.g. 0.750)",
          "directFlight": boolean,
          "uaeEmbassyLocation": "string (City in target country)",
          "foreignEmbassyLocation": "string (City in UAE, usually Abu Dhabi or Dubai)",
          "averageWage": "string (Monthly average in USD approx)",
          "minimumWage": "string (Monthly minimum in USD approx)",
          "totalWorkforce": "string (e.g. 50 Million)",
          "participationMale": number (percentage 0-100),
          "participationFemale": number (percentage 0-100),
          "migrationDestinations": ["string", "string", "string"],
          "topSectors": [{"name": "string", "value": number}, {"name": "string", "value": number}]
        }`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        // Basic cleanup if model adds markdown
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          ...aiData,
          workforceStats: {
            ...prev.workforceStats,
            totalWorkforce: aiData.totalWorkforce,
            participationMale: aiData.participationMale,
            participationFemale: aiData.participationFemale,
            migrationDestinations: aiData.migrationDestinations,
            topSectors: aiData.topSectors
          }
        }));
      } else {
         // Fallback simulation if no API key is present for demo purposes
         await new Promise(r => setTimeout(r, 2000));
         setData(prev => ({
           ...prev,
           capital: 'Simulated Capital',
           officialLanguage: 'Simulated Language',
           population: '50M',
           currency: 'Unit',
           gdp: '500 Billion USD',
           hdi: '0.750',
           directFlight: true,
           uaeEmbassyLocation: 'Capital City',
           foreignEmbassyLocation: 'Abu Dhabi',
           averageWage: '$450/month',
           minimumWage: '$200/month',
           workforceStats: {
             ...prev.workforceStats,
             totalWorkforce: '25 Million',
             participationMale: 65,
             participationFemale: 35,
             migrationDestinations: ['UAE', 'Saudi Arabia', 'UK'],
             topSectors: [{name: 'Services', value: 50}, {name: 'Agriculture', value: 30}, {name: 'Industry', value: 20}]
           }
         }));
      }
    } catch (error) {
      console.error("AI Fetch failed", error);
    } finally {
      setIsFetchingAI(false);
    }
  };

  const handleSave = async (status: 'draft' | 'completed' = 'draft') => {
    const reportId = id || `r-${uuidv4().slice(0, 8)}`;
    const newReport: Report = {
      id: reportId,
      userId: 'u-1',
      title: reportTitle || `Report for ${data.country || 'Unknown'}`,
      status,
      updatedAt: new Date().toISOString(),
      data
    };
    await MockService.saveReport(newReport);
    if (status === 'completed') {
      navigate('/dashboard');
    } else {
      console.log('Saved draft');
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
             {/* Country & AI Fetch Row */}
            <div className="flex flex-col md:flex-row gap-4 items-end bg-blue-50/50 p-6 rounded-xl border border-blue-100">
               <div className="flex-1 w-full">
                 <Input 
                    label={t('country')} 
                    value={data.country} 
                    onChange={e => setData({...data, country: e.target.value})} 
                    placeholder="e.g. Vietnam"
                    className="text-lg font-medium"
                  />
               </div>
               <Button 
                onClick={handleFetchData} 
                disabled={!data.country || isFetchingAI}
                className="w-full md:w-auto bg-accent hover:bg-accent-light text-white border-none shadow-lg"
              >
                {isFetchingAI ? <Loader2 className="animate-spin" /> : <Sparkles size={18} />}
                Fetch Data (ILO/WB)
              </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
              {/* Row 2: Capital & Language */}
              <Input 
                label={t('capital')} 
                value={data.capital} 
                onChange={e => setData({...data, capital: e.target.value})} 
              />
              <Input 
                label="Official Language" 
                value={data.officialLanguage} 
                onChange={e => setData({...data, officialLanguage: e.target.value})} 
              />

              {/* Row 3: Direct Flight */}
               <div className="flex flex-col gap-1.5 md:col-span-2">
                 <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Plane size={14} /> Direct Flight to UAE
                 </label>
                 <div className="flex gap-4">
                    <button 
                      onClick={() => setData({...data, directFlight: true})}
                      className={`flex-1 py-3 rounded-lg border font-medium transition-all ${data.directFlight ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-gray-500 hover:bg-gray-50'}`}
                    >Yes, Direct Flights Available</button>
                    <button 
                      onClick={() => setData({...data, directFlight: false})}
                      className={`flex-1 py-3 rounded-lg border font-medium transition-all ${!data.directFlight ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-gray-500 hover:bg-gray-50'}`}
                    >No Direct Flights</button>
                 </div>
              </div>

              {/* Row 4: Embassies */}
              <div className="flex flex-col gap-1.5">
                <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Building size={14} /> UAE Embassy in {data.country || 'Country'}
                </label>
                <Input 
                  value={data.uaeEmbassyLocation} 
                  onChange={e => setData({...data, uaeEmbassyLocation: e.target.value})} 
                  placeholder="e.g. Hanoi"
                />
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Building size={14} /> {data.country || 'Foreign'} Embassy in UAE
                </label>
                <Input 
                  value={data.foreignEmbassyLocation} 
                  onChange={e => setData({...data, foreignEmbassyLocation: e.target.value})} 
                  placeholder="e.g. Abu Dhabi"
                />
              </div>

              {/* Row 5: Economic Indicators */}
              <Input 
                label="GDP (Gross Domestic Product)" 
                value={data.gdp} 
                onChange={e => setData({...data, gdp: e.target.value})} 
                placeholder="e.g. 409 Billion USD"
              />
              <Input 
                label="HDI (Human Development Index)" 
                value={data.hdi} 
                onChange={e => setData({...data, hdi: e.target.value})} 
                placeholder="e.g. 0.703"
              />

               {/* Extra Info */}
               <Input 
                label="Population" 
                value={data.population} 
                onChange={e => setData({...data, population: e.target.value})} 
              />
              <Input 
                label="Currency" 
                value={data.currency} 
                onChange={e => setData({...data, currency: e.target.value})} 
              />
            </div>
          </div>
        );
      case 1:
        return (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
             {/* Section Header with Fetch Button */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b pb-4">
               <div>
                  <h3 className="text-lg font-serif font-bold text-primary flex items-center gap-2">
                    <TrendingUp size={20} /> Wages & Workforce
                  </h3>
                  <p className="text-sm text-gray-500">Economic indicators provided by ILO & World Bank data</p>
               </div>
               <Button 
                onClick={handleFetchData} 
                disabled={!data.country || isFetchingAI}
                className="bg-accent hover:bg-accent-light text-white text-sm"
              >
                {isFetchingAI ? <Loader2 className="animate-spin" size={16} /> : <RefreshCw size={16} />}
                Fetch Economic Data
              </Button>
            </div>

            {/* Wages Section */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-gray-50 p-6 rounded-xl border">
                 <Input 
                    label="Average Monthly Wage (USD)" 
                    value={data.averageWage} 
                    onChange={e => setData({...data, averageWage: e.target.value})} 
                    placeholder="e.g. $350/month"
                 />
                 <Input 
                    label="Minimum Monthly Wage (USD)" 
                    value={data.minimumWage} 
                    onChange={e => setData({...data, minimumWage: e.target.value})} 
                    placeholder="e.g. $180/month"
                 />
            </div>

            {/* Workforce Stats */}
            <div>
              <h3 className="text-sm font-semibold mb-4 text-gray-600 uppercase tracking-wider">Demographics</h3>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <Input 
                    label="Total Workforce Size" 
                    value={data.workforceStats.totalWorkforce} 
                    onChange={e => setData({...data, workforceStats: {...data.workforceStats, totalWorkforce: e.target.value}})} 
                    placeholder="e.g. 55 Million"
                  />
                  <div className="relative">
                     <Input 
                        type="number"
                        label="Male Participation (%)" 
                        value={data.workforceStats.participationMale} 
                        onChange={e => setData({...data, workforceStats: {...data.workforceStats, participationMale: Number(e.target.value)}})} 
                      />
                      <div className="w-full bg-gray-200 h-1.5 mt-2 rounded-full overflow-hidden">
                        <div className="bg-blue-600 h-full" style={{ width: `${data.workforceStats.participationMale}%` }}></div>
                      </div>
                  </div>
                  <div className="relative">
                    <Input 
                      type="number"
                      label="Female Participation (%)" 
                      value={data.workforceStats.participationFemale} 
                      onChange={e => setData({...data, workforceStats: {...data.workforceStats, participationFemale: Number(e.target.value)}})} 
                    />
                    <div className="w-full bg-gray-200 h-1.5 mt-2 rounded-full overflow-hidden">
                        <div className="bg-pink-500 h-full" style={{ width: `${data.workforceStats.participationFemale}%` }}></div>
                    </div>
                  </div>
               </div>
            </div>

            {/* Migration */}
            <div>
               <label className="text-sm font-semibold text-foreground/80 block mb-2">Top Migration Destinations</label>
               <div className="bg-white border rounded-lg p-3 flex flex-wrap gap-2 min-h-[50px] items-center">
                  {data.workforceStats.migrationDestinations.map((dest, i) => (
                    <span key={i} className="bg-primary/10 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/20">
                      {dest}
                      <button 
                        onClick={() => {
                          const newDest = data.workforceStats.migrationDestinations.filter((_, idx) => idx !== i);
                          setData({...data, workforceStats: {...data.workforceStats, migrationDestinations: newDest}});
                        }}
                        className="hover:text-red-500 font-bold px-1"
                      >×</button>
                    </span>
                  ))}
                  <input 
                    placeholder={data.workforceStats.migrationDestinations.length === 0 ? "Type country and press Enter..." : "+ Add country"}
                    className="flex-1 outline-none min-w-[120px] px-2 text-sm"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        const val = e.currentTarget.value.trim();
                        if (val) {
                          setData({...data, workforceStats: {
                            ...data.workforceStats, 
                            migrationDestinations: [...data.workforceStats.migrationDestinations, val]
                          }});
                          e.currentTarget.value = '';
                        }
                      }
                    }}
                  />
               </div>
            </div>

            {/* Sector Distribution */}
            <div>
               <h3 className="text-sm font-semibold mb-4 text-gray-600 uppercase tracking-wider">Sector Distribution</h3>
               {data.workforceStats.topSectors.map((sector, idx) => (
                 <div key={idx} className="flex gap-4 mb-2 items-center">
                   <Input 
                    placeholder="Sector Name"
                    className="flex-1"
                    value={sector.name}
                    onChange={(e) => {
                      const newSectors = [...data.workforceStats.topSectors];
                      newSectors[idx].name = e.target.value;
                      setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   />
                   <div className="w-32 relative">
                     <Input 
                      placeholder="%"
                      type="number"
                      value={sector.value}
                      onChange={(e) => {
                        const newSectors = [...data.workforceStats.topSectors];
                        newSectors[idx].value = parseInt(e.target.value);
                        setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                      }}
                     />
                     <span className="absolute right-8 top-1/2 -translate-y-1/2 text-gray-400 text-sm">%</span>
                   </div>
                   <button 
                    className="text-gray-400 hover:text-red-600 p-2"
                    onClick={() => {
                       const newSectors = data.workforceStats.topSectors.filter((_, i) => i !== idx);
                       setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   >
                    <div className="sr-only">Remove</div>
                    <span className="text-xl">×</span>
                   </button>
                 </div>
               ))}
               <Button 
                variant="outline" 
                size="sm"
                className="mt-2"
                onClick={() => setData({
                  ...data, 
                  workforceStats: {
                    ...data.workforceStats, 
                    topSectors: [...data.workforceStats.topSectors, {name: '', value: 0}]
                  }
                })}
              >
                + Add Sector
              </Button>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            {data.bilateralAgreements.length === 0 && (
              <div className="text-center p-8 text-gray-400 bg-gray-50 rounded-lg border border-dashed">
                No agreements recorded. Add one below.
              </div>
            )}
            {data.bilateralAgreements.map((agreement, idx) => (
               <Card key={idx} className="relative">
                 <button 
                  className="absolute top-2 right-2 text-red-500 hover:bg-red-50 p-1 rounded"
                  onClick={() => {
                    const filtered = data.bilateralAgreements.filter((_, i) => i !== idx);
                    setData({...data, bilateralAgreements: filtered});
                  }}
                 >x</button>
                 <div className="grid gap-4">
                   <Input 
                      label="Title" 
                      value={agreement.title}
                      onChange={(e) => {
                        const ag = [...data.bilateralAgreements];
                        ag[idx].title = e.target.value;
                        setData({...data, bilateralAgreements: ag});
                      }}
                   />
                   <div className="grid grid-cols-2 gap-4">
                    <Input 
                        type="date"
                        label="Date" 
                        value={agreement.date}
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].date = e.target.value;
                          setData({...data, bilateralAgreements: ag});
                        }}
                    />
                     <div>
                       <label className="text-sm font-semibold text-foreground/80 block mb-1.5">Status</label>
                       <select 
                        className="w-full px-4 py-2 rounded-lg border border-gray-300 bg-white"
                        value={agreement.status}
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].status = e.target.value as any;
                          setData({...data, bilateralAgreements: ag});
                        }}
                       >
                         <option>Active</option>
                         <option>Pending</option>
                         <option>Expired</option>
                       </select>
                     </div>
                   </div>
                   <Input 
                      label="Summary" 
                      value={agreement.summary}
                      onChange={(e) => {
                        const ag = [...data.bilateralAgreements];
                        ag[idx].summary = e.target.value;
                        setData({...data, bilateralAgreements: ag});
                      }}
                   />
                 </div>
               </Card>
            ))}
            <Button 
              variant="outline"
              onClick={() => setData({
                ...data, 
                bilateralAgreements: [...data.bilateralAgreements, { title: '', date: '', status: 'Active', summary: '' }]
              })}
            >
              + Add Agreement
            </Button>
          </div>
        );
      case 3:
        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
            <div className="bg-gray-100 p-8 rounded-xl border border-gray-200">
              <h2 className="font-serif text-2xl mb-4 text-center">{reportTitle}</h2>
              <div className="bg-white p-8 shadow-diplomatic max-w-2xl mx-auto space-y-6">
                <div className="flex items-center gap-4 border-b pb-4">
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('country')}</p>
                    <p className="text-xl font-bold">{data.country}</p>
                  </div>
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('capital')}</p>
                    <p className="text-xl font-bold">{data.capital}</p>
                  </div>
                </div>
                <div>
                  <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">{t('agreements')}</h3>
                  <ul className="list-disc ml-5 space-y-1">
                    {data.bilateralAgreements.map((a, i) => (
                      <li key={i}><span className="font-medium">{a.title}</span> ({a.status})</li>
                    ))}
                  </ul>
                </div>
                <div className="p-4 bg-blue-50 text-blue-800 rounded text-center text-sm">
                  This is a preview. Click "Complete Report" to finalize.
                </div>
              </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  if (loading) return <div className="p-8 text-center">Loading...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-12">
      {/* Wizard Header */}
      <div className="mb-8">
        <Input 
          placeholder="Report Title (e.g. Bilateral Meeting India 2024)"
          className="text-2xl font-serif font-bold bg-transparent border-transparent px-0 focus:ring-0 focus:border-primary placeholder:text-gray-300"
          value={reportTitle}
          onChange={(e) => setReportTitle(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Steps Sidebar */}
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'}
                ${idx < currentStep ? 'text-primary font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        {/* Content Area */}
        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button 
              variant="ghost" 
              onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
              disabled={currentStep === 0}
            >
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} />
              {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}>
                <Save size={16} />
                {t('save')}
              </Button>

              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>
                  {t('next')}
                  <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} />
                </Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">
                  {t('finish')}
                  <CheckCircle size={16} />
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { ReportData, EMPTY_REPORT_DATA, Report } from '../types';
import { MockService } from '../services/mockService';
import { Button, Card, Input } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle, Plane, Building, TrendingUp, Sparkles, Loader2, RefreshCw, Link as LinkIcon, Search } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from "@google/genai";

const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'workforce', icon: Users, label: 'Workforce & Economy' },
  { id: 'agreements', icon: FileText, label: 'Agreements' },
  { id: 'preview', icon: CheckCircle, label: 'Preview' },
];

export default function Wizard() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(!!id);
  const [isFetchingAI, setIsFetchingAI] = useState(false);
  const [isFetchingAgreements, setIsFetchingAgreements] = useState(false);
  const [data, setData] = useState<ReportData>(EMPTY_REPORT_DATA);
  const [reportTitle, setReportTitle] = useState('');

  useEffect(() => {
    if (id) {
      MockService.getReportById(id).then(r => {
        if (r) {
          setData(r.data);
          setReportTitle(r.title);
        }
        setLoading(false);
      });
    }
  }, [id]);

  const handleFetchData = async () => {
    if (!data.country) return;
    setIsFetchingAI(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as a labour market intelligence expert. Fetch the latest available data from ILO (International Labour Organization), World Bank, and official government sources for ${data.country}.

        Return a strictly valid JSON object (no markdown, no code blocks) matching this structure exactly:
        {
          "capital": "string",
          "officialLanguage": "string",
          "population": "string (e.g. 1.4B)",
          "currency": "string",
          "gdp": "string (e.g. 400 Billion USD)",
          "hdi": "string (e.g. 0.750)",
          "directFlight": boolean,
          "uaeEmbassyLocation": "string (City in target country)",
          "foreignEmbassyLocation": "string (City in UAE, usually Abu Dhabi or Dubai)",
          "averageWage": "string (Monthly average in USD approx)",
          "minimumWage": "string (Monthly minimum in USD approx)",
          "totalWorkforce": "string (e.g. 50 Million)",
          "participationMale": number (percentage 0-100),
          "participationFemale": number (percentage 0-100),
          "migrationDestinations": ["string", "string", "string"],
          "topSectors": [{"name": "string", "value": number}, {"name": "string", "value": number}]
        }`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        // Basic cleanup if model adds markdown
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          ...aiData,
          workforceStats: {
            ...prev.workforceStats,
            totalWorkforce: aiData.totalWorkforce,
            participationMale: aiData.participationMale,
            participationFemale: aiData.participationFemale,
            migrationDestinations: aiData.migrationDestinations,
            topSectors: aiData.topSectors
          }
        }));
      } else {
         // Fallback simulation if no API key is present for demo purposes
         await new Promise(r => setTimeout(r, 2000));
         setData(prev => ({
           ...prev,
           capital: 'Simulated Capital',
           officialLanguage: 'Simulated Language',
           population: '50M',
           currency: 'Unit',
           gdp: '500 Billion USD',
           hdi: '0.750',
           directFlight: true,
           uaeEmbassyLocation: 'Capital City',
           foreignEmbassyLocation: 'Abu Dhabi',
           averageWage: '$450/month',
           minimumWage: '$200/month',
           workforceStats: {
             ...prev.workforceStats,
             totalWorkforce: '25 Million',
             participationMale: 65,
             participationFemale: 35,
             migrationDestinations: ['UAE', 'Saudi Arabia', 'UK'],
             topSectors: [{name: 'Services', value: 50}, {name: 'Agriculture', value: 30}, {name: 'Industry', value: 20}]
           }
         }));
      }
    } catch (error) {
      console.error("AI Fetch failed", error);
    } finally {
      setIsFetchingAI(false);
    }
  };

  const handleFetchAgreements = async (source: 'MOFA' | 'GENERAL') => {
    if (!data.country) return;
    setIsFetchingAgreements(true);

    try {
       if (process.env.API_KEY) {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

          let searchPrompt = "";
          if (source === 'MOFA') {
            searchPrompt = `Search specifically on site:mofa.gov.ae for bilateral agreements, diplomatic memorandums, and cooperation treaties between UAE and ${data.country}.`;
          } else {
            searchPrompt = `Search for official Memorandum of Understanding (MoU) and labour agreements signed between UAE and ${data.country} found in news or official archives.`;
          }

          const prompt = `${searchPrompt}

          Extract the details and return a strictly valid JSON array (no markdown, no code blocks).
          Each object in the array must have:
          - "title": The official title of the agreement/MoU.
          - "date": The year of signing (e.g. "2022") or full date if available.
          - "status": Assume "Active" unless explicitly stated as expired.
          - "summary": A very brief 1-sentence description.

          Return format: [{"title": "...", "date": "...", "status": "Active", "summary": "..."}]`;

          const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
              tools: [{ googleSearch: {} }],
            },
          });

          // Check if grounding metadata exists to verify search was used
          // console.log(response.candidates?.[0]?.groundingMetadata?.groundingChunks);

          const text = response.text;
          const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();

          try {
            const newAgreements = JSON.parse(cleanJson);
            if (Array.isArray(newAgreements)) {
              setData(prev => ({
                ...prev,
                bilateralAgreements: [...prev.bilateralAgreements, ...newAgreements]
              }));
            }
          } catch (e) {
            console.error("Failed to parse agreement JSON", text);
          }

       } else {
          // Simulation
          await new Promise(r => setTimeout(r, 1500));
          const mockDocs = source === 'MOFA' 
            ? [{ title: `Diplomatic Cooperation Protocol (${data.country})`, date: '2021', status: 'Active', summary: 'Fetched from MOFA UAE: General diplomatic framework.' }]
            : [{ title: `MoU on Manpower Recruitment`, date: '2019', status: 'Active', summary: 'Fetched Online: Regulates domestic worker recruitment.' }];

          setData(prev => ({
            ...prev,
            bilateralAgreements: [...prev.bilateralAgreements, ...mockDocs] as any
          }));
       }
    } catch (error) {
      console.error("Agreement Fetch failed", error);
    } finally {
      setIsFetchingAgreements(false);
    }
  };

  const handleSave = async (status: 'draft' | 'completed' = 'draft') => {
    const reportId = id || `r-${uuidv4().slice(0, 8)}`;
    const newReport: Report = {
      id: reportId,
      userId: 'u-1',
      title: reportTitle || `Report for ${data.country || 'Unknown'}`,
      status,
      updatedAt: new Date().toISOString(),
      data
    };
    await MockService.saveReport(newReport);
    if (status === 'completed') {
      navigate('/dashboard');
    } else {
      console.log('Saved draft');
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
             {/* Country & AI Fetch Row */}
            <div className="flex flex-col md:flex-row gap-4 items-end bg-blue-50/50 p-6 rounded-xl border border-blue-100">
               <div className="flex-1 w-full">
                 <Input 
                    label={t('country')} 
                    value={data.country} 
                    onChange={e => setData({...data, country: e.target.value})} 
                    placeholder="e.g. Vietnam"
                    className="text-lg font-medium"
                  />
               </div>
               <Button 
                onClick={handleFetchData} 
                disabled={!data.country || isFetchingAI}
                className="w-full md:w-auto bg-accent hover:bg-accent-light text-white border-none shadow-lg"
              >
                {isFetchingAI ? <Loader2 className="animate-spin" /> : <Sparkles size={18} />}
                Fetch Data (ILO/WB)
              </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
              {/* Row 2: Capital & Language */}
              <Input 
                label={t('capital')} 
                value={data.capital} 
                onChange={e => setData({...data, capital: e.target.value})} 
              />
              <Input 
                label="Official Language" 
                value={data.officialLanguage} 
                onChange={e => setData({...data, officialLanguage: e.target.value})} 
              />

              {/* Row 3: Direct Flight */}
               <div className="flex flex-col gap-1.5 md:col-span-2">
                 <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Plane size={14} /> Direct Flight to UAE
                 </label>
                 <div className="flex gap-4">
                    <button 
                      onClick={() => setData({...data, directFlight: true})}
                      className={`flex-1 py-3 rounded-lg border font-medium transition-all ${data.directFlight ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-gray-500 hover:bg-gray-50'}`}
                    >Yes, Direct Flights Available</button>
                    <button 
                      onClick={() => setData({...data, directFlight: false})}
                      className={`flex-1 py-3 rounded-lg border font-medium transition-all ${!data.directFlight ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-gray-500 hover:bg-gray-50'}`}
                    >No Direct Flights</button>
                 </div>
              </div>

              {/* Row 4: Embassies */}
              <div className="flex flex-col gap-1.5">
                <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Building size={14} /> UAE Embassy in {data.country || 'Country'}
                </label>
                <Input 
                  value={data.uaeEmbassyLocation} 
                  onChange={e => setData({...data, uaeEmbassyLocation: e.target.value})} 
                  placeholder="e.g. Hanoi"
                />
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Building size={14} /> {data.country || 'Foreign'} Embassy in UAE
                </label>
                <Input 
                  value={data.foreignEmbassyLocation} 
                  onChange={e => setData({...data, foreignEmbassyLocation: e.target.value})} 
                  placeholder="e.g. Abu Dhabi"
                />
              </div>

              {/* Row 5: Economic Indicators */}
              <Input 
                label="GDP (Gross Domestic Product)" 
                value={data.gdp} 
                onChange={e => setData({...data, gdp: e.target.value})} 
                placeholder="e.g. 409 Billion USD"
              />
              <Input 
                label="HDI (Human Development Index)" 
                value={data.hdi} 
                onChange={e => setData({...data, hdi: e.target.value})} 
                placeholder="e.g. 0.703"
              />

               {/* Extra Info */}
               <Input 
                label="Population" 
                value={data.population} 
                onChange={e => setData({...data, population: e.target.value})} 
              />
              <Input 
                label="Currency" 
                value={data.currency} 
                onChange={e => setData({...data, currency: e.target.value})} 
              />
            </div>
          </div>
        );
      case 1:
        return (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
             {/* Section Header with Fetch Button */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b pb-4">
               <div>
                  <h3 className="text-lg font-serif font-bold text-primary flex items-center gap-2">
                    <TrendingUp size={20} /> Wages & Workforce
                  </h3>
                  <p className="text-sm text-gray-500">Economic indicators provided by ILO & World Bank data</p>
               </div>
               <Button 
                onClick={handleFetchData} 
                disabled={!data.country || isFetchingAI}
                className="bg-accent hover:bg-accent-light text-white text-sm"
              >
                {isFetchingAI ? <Loader2 className="animate-spin" size={16} /> : <RefreshCw size={16} />}
                Fetch Economic Data
              </Button>
            </div>

            {/* Wages Section */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-gray-50 p-6 rounded-xl border">
                 <Input 
                    label="Average Monthly Wage (USD)" 
                    value={data.averageWage} 
                    onChange={e => setData({...data, averageWage: e.target.value})} 
                    placeholder="e.g. $350/month"
                 />
                 <Input 
                    label="Minimum Monthly Wage (USD)" 
                    value={data.minimumWage} 
                    onChange={e => setData({...data, minimumWage: e.target.value})} 
                    placeholder="e.g. $180/month"
                 />
            </div>

            {/* Workforce Stats */}
            <div>
              <h3 className="text-sm font-semibold mb-4 text-gray-600 uppercase tracking-wider">Demographics</h3>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <Input 
                    label="Total Workforce Size" 
                    value={data.workforceStats.totalWorkforce} 
                    onChange={e => setData({...data, workforceStats: {...data.workforceStats, totalWorkforce: e.target.value}})} 
                    placeholder="e.g. 55 Million"
                  />
                  <div className="relative">
                     <Input 
                        type="number"
                        label="Male Participation (%)" 
                        value={data.workforceStats.participationMale} 
                        onChange={e => setData({...data, workforceStats: {...data.workforceStats, participationMale: Number(e.target.value)}})} 
                      />
                      <div className="w-full bg-gray-200 h-1.5 mt-2 rounded-full overflow-hidden">
                        <div className="bg-blue-600 h-full" style={{ width: `${data.workforceStats.participationMale}%` }}></div>
                      </div>
                  </div>
                  <div className="relative">
                    <Input 
                      type="number"
                      label="Female Participation (%)" 
                      value={data.workforceStats.participationFemale} 
                      onChange={e => setData({...data, workforceStats: {...data.workforceStats, participationFemale: Number(e.target.value)}})} 
                    />
                    <div className="w-full bg-gray-200 h-1.5 mt-2 rounded-full overflow-hidden">
                        <div className="bg-pink-500 h-full" style={{ width: `${data.workforceStats.participationFemale}%` }}></div>
                    </div>
                  </div>
               </div>
            </div>

            {/* Migration */}
            <div>
               <label className="text-sm font-semibold text-foreground/80 block mb-2">Top Migration Destinations</label>
               <div className="bg-white border rounded-lg p-3 flex flex-wrap gap-2 min-h-[50px] items-center">
                  {data.workforceStats.migrationDestinations.map((dest, i) => (
                    <span key={i} className="bg-primary/10 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/20">
                      {dest}
                      <button 
                        onClick={() => {
                          const newDest = data.workforceStats.migrationDestinations.filter((_, idx) => idx !== i);
                          setData({...data, workforceStats: {...data.workforceStats, migrationDestinations: newDest}});
                        }}
                        className="hover:text-red-500 font-bold px-1"
                      >×</button>
                    </span>
                  ))}
                  <input 
                    placeholder={data.workforceStats.migrationDestinations.length === 0 ? "Type country and press Enter..." : "+ Add country"}
                    className="flex-1 outline-none min-w-[120px] px-2 text-sm"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        const val = e.currentTarget.value.trim();
                        if (val) {
                          setData({...data, workforceStats: {
                            ...data.workforceStats, 
                            migrationDestinations: [...data.workforceStats.migrationDestinations, val]
                          }});
                          e.currentTarget.value = '';
                        }
                      }
                    }}
                  />
               </div>
            </div>

            {/* Sector Distribution */}
            <div>
               <h3 className="text-sm font-semibold mb-4 text-gray-600 uppercase tracking-wider">Sector Distribution</h3>
               {data.workforceStats.topSectors.map((sector, idx) => (
                 <div key={idx} className="flex gap-4 mb-2 items-center">
                   <Input 
                    placeholder="Sector Name"
                    className="flex-1"
                    value={sector.name}
                    onChange={(e) => {
                      const newSectors = [...data.workforceStats.topSectors];
                      newSectors[idx].name = e.target.value;
                      setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   />
                   <div className="w-32 relative">
                     <Input 
                      placeholder="%"
                      type="number"
                      value={sector.value}
                      onChange={(e) => {
                        const newSectors = [...data.workforceStats.topSectors];
                        newSectors[idx].value = parseInt(e.target.value);
                        setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                      }}
                     />
                     <span className="absolute right-8 top-1/2 -translate-y-1/2 text-gray-400 text-sm">%</span>
                   </div>
                   <button 
                    className="text-gray-400 hover:text-red-600 p-2"
                    onClick={() => {
                       const newSectors = data.workforceStats.topSectors.filter((_, i) => i !== idx);
                       setData({...data, workforceStats: {...data.workforceStats, topSectors: newSectors}});
                    }}
                   >
                    <div className="sr-only">Remove</div>
                    <span className="text-xl">×</span>
                   </button>
                 </div>
               ))}
               <Button 
                variant="outline" 
                size="sm"
                className="mt-2"
                onClick={() => setData({
                  ...data, 
                  workforceStats: {
                    ...data.workforceStats, 
                    topSectors: [...data.workforceStats.topSectors, {name: '', value: 0}]
                  }
                })}
              >
                + Add Sector
              </Button>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            {/* Agreement Fetch Actions */}
            <div className="bg-primary/5 p-4 rounded-xl border border-primary/20 flex flex-col md:flex-row gap-4 items-center justify-between mb-6">
               <div className="flex items-center gap-3 text-primary-dark">
                  <div className="bg-primary/10 p-2 rounded-full"><Sparkles size={20} /></div>
                  <div>
                    <h3 className="font-bold text-sm">Automated Intelligence</h3>
                    <p className="text-xs text-primary/70">Fetch official records from MOFA or Online sources</p>
                  </div>
               </div>
               <div className="flex gap-3 w-full md:w-auto">
                 <Button 
                   onClick={() => handleFetchAgreements('MOFA')} 
                   disabled={isFetchingAgreements || !data.country}
                   variant="outline"
                   className="flex-1 md:flex-none border-primary text-primary hover:bg-primary hover:text-white"
                 >
                   {isFetchingAgreements ? <Loader2 className="animate-spin" size={16} /> : <LinkIcon size={16} />}
                   Fetch from MOFA (mofa.gov.ae)
                 </Button>
                 <Button 
                   onClick={() => handleFetchAgreements('GENERAL')} 
                   disabled={isFetchingAgreements || !data.country}
                   className="flex-1 md:flex-none bg-primary text-white"
                 >
                   {isFetchingAgreements ? <Loader2 className="animate-spin" size={16} /> : <Search size={16} />}
                   Search Online MoUs
                 </Button>
               </div>
            </div>

            {data.bilateralAgreements.length === 0 && (
              <div className="text-center p-8 text-gray-400 bg-gray-50 rounded-lg border border-dashed">
                No agreements recorded. Use the buttons above to fetch or add one manually below.
              </div>
            )}

            <div className="grid gap-4">
              {data.bilateralAgreements.map((agreement, idx) => (
                <Card key={idx} className="relative group transition-all hover:shadow-md border border-gray-100 hover:border-primary/30">
                  <button 
                    className="absolute top-4 right-4 text-gray-300 hover:text-red-500 p-1 rounded transition-colors"
                    onClick={() => {
                      const filtered = data.bilateralAgreements.filter((_, i) => i !== idx);
                      setData({...data, bilateralAgreements: filtered});
                    }}
                  >
                    <div className="sr-only">Delete</div>
                    <span>×</span>
                  </button>

                  <div className="grid gap-4">
                    <div className="pr-8">
                      <Input 
                        placeholder="Agreement Title (e.g. Protocol on Domestic Workers)" 
                        value={agreement.title}
                        className="font-bold text-lg border-transparent focus:border-gray-300 px-0 -ml-0"
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].title = e.target.value;
                          setData({...data, bilateralAgreements: ag});
                        }}
                      />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Year / Date</label>
                        <Input 
                          placeholder="YYYY"
                          value={agreement.date}
                          onChange={(e) => {
                            const ag = [...data.bilateralAgreements];
                            ag[idx].date = e.target.value;
                            setData({...data, bilateralAgreements: ag});
                          }}
                        />
                      </div>
                      <div>
                        <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Status</label>
                        <select 
                          className="w-full px-4 py-2 rounded-lg border border-gray-300 bg-white"
                          value={agreement.status}
                          onChange={(e) => {
                            const ag = [...data.bilateralAgreements];
                            ag[idx].status = e.target.value as any;
                            setData({...data, bilateralAgreements: ag});
                          }}
                        >
                          <option>Active</option>
                          <option>Pending</option>
                          <option>Expired</option>
                        </select>
                      </div>
                    </div>

                    <div>
                      <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Summary</label>
                      <Input 
                        placeholder="Brief description of the agreement..." 
                        value={agreement.summary}
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].summary = e.target.value;
                          setData({...data, bilateralAgreements: ag});
                        }}
                      />
                    </div>
                  </div>
                </Card>
              ))}
            </div>

            <Button 
              variant="outline"
              className="w-full border-dashed border-2 py-4 text-gray-500 hover:text-primary hover:border-primary hover:bg-primary/5"
              onClick={() => setData({
                ...data, 
                bilateralAgreements: [...data.bilateralAgreements, { title: '', date: '', status: 'Active', summary: '' }]
              })}
            >
              + Add Manual Agreement
            </Button>
          </div>
        );
      case 3:
        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
            <div className="bg-gray-100 p-8 rounded-xl border border-gray-200">
              <h2 className="font-serif text-2xl mb-4 text-center">{reportTitle}</h2>
              <div className="bg-white p-8 shadow-diplomatic max-w-2xl mx-auto space-y-6">
                <div className="flex items-center gap-4 border-b pb-4">
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('country')}</p>
                    <p className="text-xl font-bold">{data.country}</p>
                  </div>
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('capital')}</p>
                    <p className="text-xl font-bold">{data.capital}</p>
                  </div>
                </div>
                <div>
                  <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">{t('agreements')}</h3>
                  <ul className="list-disc ml-5 space-y-1">
                    {data.bilateralAgreements.map((a, i) => (
                      <li key={i}><span className="font-medium">{a.title}</span> ({a.status})</li>
                    ))}
                  </ul>
                </div>
                <div className="p-4 bg-blue-50 text-blue-800 rounded text-center text-sm">
                  This is a preview. Click "Complete Report" to finalize.
                </div>
              </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  if (loading) return <div className="p-8 text-center">Loading...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-12">
      {/* Wizard Header */}
      <div className="mb-8">
        <Input 
          placeholder="Report Title (e.g. Bilateral Meeting India 2024)"
          className="text-2xl font-serif font-bold bg-transparent border-transparent px-0 focus:ring-0 focus:border-primary placeholder:text-gray-300"
          value={reportTitle}
          onChange={(e) => setReportTitle(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Steps Sidebar */}
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'}
                ${idx < currentStep ? 'text-primary font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        {/* Content Area */}
        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button 
              variant="ghost" 
              onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
              disabled={currentStep === 0}
            >
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} />
              {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}>
                <Save size={16} />
                {t('save')}
              </Button>

              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>
                  {t('next')}
                  <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} />
                </Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">
                  {t('finish')}
                  <CheckCircle size={16} />
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export type Language = 'en' | 'ar';
export type ReportStatus = 'draft' | 'completed';
export type UserRole = 'admin' | 'user';

export interface UserProfile {
  id: string;
  email: string;
  fullName: string;
  role: UserRole;
  avatarUrl?: string;
}

// Complex Report Structure
export interface ReportData {
  // Section 1: Country Profile & Diplomacy
  country: string;
  capital: string;
  officialLanguage: string;
  population: string;
  currency: string;
  gdp: string; // Changed from gdpGrowth to generic GDP field
  hdi: string; // Human Development Index
  directFlight: boolean; // Yes/No
  uaeEmbassyLocation: string; // Location in that country
  foreignEmbassyLocation: string; // City in UAE

  // Section 2: Workforce & Economic Indicators
  averageWage: string; // e.g. "$250/month"
  minimumWage: string; // e.g. "$180/month"
  workforceStats: {
    totalWorkforce: string; // Size of workforce
    participationMale: number; // %
    participationFemale: number; // %
    // Updated structure for migration destinations
    migrationDestinations: Array<{ country: string; count: string }>; 
    topSectors: Array<{ name: string; value: number }>; // Distribution
    // New field for skills
    availableSkills: string[]; 
  };

  // Section 3: Relations
  bilateralAgreements: Array<{
    title: string;
    date: string;
    status: 'Active' | 'Pending' | 'Expired';
    summary: string;
  }>;

  keyIssues: string[];
  recommendations: string[];
  delegation: Array<{
    name: string;
    title: string;
    imageUrl: string;
  }>;
}

export interface Report {
  id: string;
  userId: string;
  title: string;
  status: ReportStatus;
  updatedAt: string;
  data: ReportData;
}

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  timestamp: string;
  details: string;
}

export const EMPTY_REPORT_DATA: ReportData = {
  country: '',
  capital: '',
  officialLanguage: '',
  population: '',
  currency: '',
  gdp: '',
  hdi: '',
  directFlight: false,
  uaeEmbassyLocation: '',
  foreignEmbassyLocation: '',
  averageWage: '',
  minimumWage: '',
  workforceStats: {
    totalWorkforce: '',
    participationMale: 0,
    participationFemale: 0,
    migrationDestinations: [],
    topSectors: [],
    availableSkills: [],
  },
  bilateralAgreements: [],
  keyIssues: [],
  recommendations: [],
  delegation: [],
};

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { ReportData, EMPTY_REPORT_DATA, Report } from '../types';
import { MockService } from '../services/mockService';
import { Button, Card, Input } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle, Plane, Building, TrendingUp, Sparkles, Loader2, RefreshCw, Link as LinkIcon, Search, Hammer } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from "@google/genai";

const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'workforce', icon: Users, label: 'Workforce & Economy' },
  { id: 'agreements', icon: FileText, label: 'Agreements' },
  { id: 'preview', icon: CheckCircle, label: 'Preview' },
];

export default function Wizard() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(!!id);
  const [isFetchingAI, setIsFetchingAI] = useState(false);
  const [isFetchingAgreements, setIsFetchingAgreements] = useState(false);
  const [data, setData] = useState<ReportData>(EMPTY_REPORT_DATA);
  const [reportTitle, setReportTitle] = useState('');

  useEffect(() => {
    if (id) {
      MockService.getReportById(id).then(r => {
        if (r) {
          setData(r.data);
          setReportTitle(r.title);
        }
        setLoading(false);
      });
    }
  }, [id]);

  const handleFetchData = async () => {
    if (!data.country) return;
    setIsFetchingAI(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as a labour market intelligence expert. Fetch the latest available data from ILO (International Labour Organization), World Bank, and official government sources for ${data.country}.

        Return a strictly valid JSON object (no markdown, no code blocks) matching this structure exactly:
        {
          "capital": "string",
          "officialLanguage": "string",
          "population": "string (e.g. 1.4B)",
          "currency": "string",
          "gdp": "string (e.g. 400 Billion USD)",
          "hdi": "string (e.g. 0.750)",
          "directFlight": boolean,
          "uaeEmbassyLocation": "string (City in target country)",
          "foreignEmbassyLocation": "string (City in UAE, usually Abu Dhabi or Dubai)",
          "averageWage": "string (Monthly average in USD approx)",
          "minimumWage": "string (Monthly minimum in USD approx)",
          "totalWorkforce": "string (e.g. 50 Million)",
          "participationMale": number (percentage 0-100),
          "participationFemale": number (percentage 0-100),
          "migrationDestinations": [{"country": "string", "count": "string (e.g. 2.5 Million)"}],
          "topSectors": [{"name": "string", "value": number}, {"name": "string", "value": number}],
          "availableSkills": ["string", "string", "string", "string"]
        }

        For "migrationDestinations", provide the top 3-5 countries workers migrate to, and the estimated total number of workers in that country.
        For "availableSkills", list the top 4-6 specific job skills or industries that are abundant and available for migration (e.g. "Construction", "Nursing", "IT", "Domestic Work").`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        // Basic cleanup if model adds markdown
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          ...aiData,
          workforceStats: {
            ...prev.workforceStats,
            totalWorkforce: aiData.totalWorkforce,
            participationMale: aiData.participationMale,
            participationFemale: aiData.participationFemale,
            migrationDestinations: aiData.migrationDestinations || [],
            topSectors: aiData.topSectors,
            availableSkills: aiData.availableSkills || []
          }
        }));
      } else {
         // Fallback simulation if no API key is present for demo purposes
         await new Promise(r => setTimeout(r, 2000));
         setData(prev => ({
           ...prev,
           capital: 'Simulated Capital',
           officialLanguage: 'Simulated Language',
