  const handleFetchAgreements = async (source: 'MOFA' | 'GENERAL') => {
    if (!data.country) return;
    setIsFetchingAgreements(true);

    try {
       if (process.env.API_KEY) {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

          let searchPrompt = "";
          if (source === 'MOFA') {
            searchPrompt = `Search specifically on site:mofa.gov.ae for bilateral agreements, diplomatic memorandums, and cooperation treaties between UAE and ${data.country}.`;
          } else {
            searchPrompt = `Search for official Memorandum of Understanding (MoU) and labour agreements signed between UAE and ${data.country} found in news or official archives.`;
          }

          const prompt = `${searchPrompt}

          Extract the details and return a strictly valid JSON array (no markdown, no code blocks).
          Each object in the array must have:
          - "title": The official title of the agreement/MoU.
          - "date": The year of signing (e.g. "2022") or full date if available.
          - "status": Assume "Active" unless explicitly stated as expired.
          - "summary": A very brief 1-sentence description.

          Return format: [{"title": "...", "date": "...", "status": "Active", "summary": "..."}]`;

          const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
              tools: [{ googleSearch: {} }],
            },
          });

          // Check if grounding metadata exists to verify search was used
          // console.log(response.candidates?.[0]?.groundingMetadata?.groundingChunks);

          const text = response.text;
          const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();

          try {
            const newAgreements = JSON.parse(cleanJson);
            if (Array.isArray(newAgreements)) {
              setData(prev => ({
                ...prev,
                bilateralAgreements: [...prev.bilateralAgreements, ...newAgreements]
              }));
            }
          } catch (e) {
            console.error("Failed to parse agreement JSON", text);
          }

       } else {
          // Simulation
          await new Promise(r => setTimeout(r, 1500));
          const mockDocs = source === 'MOFA' 
            ? [{ title: `Diplomatic Cooperation Protocol (${data.country})`, date: '2021', status: 'Active', summary: 'Fetched from MOFA UAE: General diplomatic framework.' }]
            : [{ title: `MoU on Manpower Recruitment`, date: '2019', status: 'Active', summary: 'Fetched Online: Regulates domestic worker recruitment.' }];

          setData(prev => ({
            ...prev,
            bilateralAgreements: [...prev.bilateralAgreements, ...mockDocs] as any
          }));
       }
    } catch (error) {
      console.error("Agreement Fetch failed", error);
    } finally {
      setIsFetchingAgreements(false);
    }
  };

