                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('capital')}</p>
                    <p className="text-xl font-bold">{data.capital}</p>
                  </div>
                </div>
                <div>
                  <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">{t('agreements')}</h3>
                  <ul className="list-disc ml-5 space-y-1">
                    {data.bilateralAgreements.map((a, i) => (
                      <li key={i}><span className="font-medium">{a.title}</span> ({a.status})</li>
                    ))}
                  </ul>
                </div>
                <div className="p-4 bg-blue-50 text-blue-800 rounded text-center text-sm">
                  This is a preview. Click "Complete Report" to finalize.
                </div>
              </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  if (loading) return <div className="p-8 text-center">Loading...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-12">
      {/* Wizard Header */}
      <div className="mb-8">
        <Input 
          placeholder="Report Title (e.g. Bilateral Meeting India 2024)"
          className="text-2xl font-serif font-bold bg-transparent border-transparent px-0 focus:ring-0 focus:border-primary placeholder:text-gray-300"
          value={reportTitle}
          onChange={(e) => setReportTitle(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Steps Sidebar */}
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'}
                ${idx < currentStep ? 'text-primary font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        {/* Content Area */}
        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button 
              variant="ghost" 
              onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
              disabled={currentStep === 0}
            >
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} />
              {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}>
                <Save size={16} />
                {t('save')}
              </Button>

              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>
                  {t('next')}
                  <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} />
                </Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">
                  {t('finish')}
                  <CheckCircle size={16} />
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export type Language = 'en' | 'ar';
export type ReportStatus = 'draft' | 'completed';
export type UserRole = 'admin' | 'user';

export interface UserProfile {
  id: string;
  email: string;
  fullName: string;
  role: UserRole;
  avatarUrl?: string;
}

// Complex Report Structure
export interface ReportData {
  // Section 1: Country Profile & Diplomacy
  country: string;
  capital: string;
  officialLanguage: string;
  population: string;
  currency: string;
  gdp: string; // Generic GDP field
  hdi: string; // Human Development Index
  directFlight: boolean; // Yes/No
  uaeEmbassyLocation: string; // Location in that country
  foreignEmbassyLocation: string; // City in UAE

  // Section 2: Workforce & Economic Indicators
  averageWage: string;
  minimumWage: string;
  workforceStats: {
    totalWorkforce: string;
    participationMale: number;
    participationFemale: number;
    migrationDestinations: Array<{ country: string; count: string }>; 
    topSectors: Array<{ name: string; value: number }>; 
    availableSkills: string[]; 
  };

  // Section 3: Economy & Education (NEW)
  economicStats: {
    inflation: string;
    gdp: string; // Specific GDP value for this section if different/updated
    totalExportsToUAE: string;
    totalImportsFromUAE: string;
    topExportProducts: string[];
    topImportProducts: string[];
    mainEconomicPartners: string[];
    tipRank: string; // Trafficking in Persons Rank
  };

  educationStats: {
    topUniversities: string[];
    primaryEnrollment: string;
    higherEducationEnrollment: string;
  };

  // Flexible Content
  customSections: Array<{
    id: string;
    title: string;
    content: string;
  }>;

  // Section 4: Relations
  bilateralAgreements: Array<{
    title: string;
    date: string;
    status: 'Active' | 'Pending' | 'Expired';
    summary: string;
  }>;

  keyIssues: string[];
  recommendations: string[];
  delegation: Array<{
    name: string;
    title: string;
    imageUrl: string;
  }>;
}

export interface Report {
  id: string;
  userId: string;
  title: string;
  status: ReportStatus;
  updatedAt: string;
  data: ReportData;
}

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  timestamp: string;
  details: string;
}

