import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { ReportData, EMPTY_REPORT_DATA, Report, Delegate } from '../types';
import { MockService } from '../services/mockService';
import { Button, Card, Input } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle, Plane, Building, TrendingUp, Sparkles, Loader2, RefreshCw, Link as LinkIcon, Search, Hammer, GraduationCap, Briefcase, Plus, X, Banknote, UserPlus, Image as ImageIcon } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from "@google/genai";

const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'workforce', icon: Users, label: 'Workforce & Economy' },
  { id: 'economy', icon: Briefcase, label: 'Economy & Education' },
  { id: 'agreements', icon: FileText, label: 'Agreements' },
  { id: 'delegation', icon: Users, label: 'Delegations' },
  { id: 'preview', icon: CheckCircle, label: 'Preview' },
];

export default function Wizard() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(!!id);
  const [isFetchingAI, setIsFetchingAI] = useState(false);
  const [isFetchingAgreements, setIsFetchingAgreements] = useState(false);
  const [isFetchingEconomy, setIsFetchingEconomy] = useState(false);
  const [enrichingDelegateId, setEnrichingDelegateId] = useState<string | null>(null);
  const [data, setData] = useState<ReportData>(EMPTY_REPORT_DATA);
  const [reportTitle, setReportTitle] = useState('');

  useEffect(() => {
    if (id) {
      MockService.getReportById(id).then(r => {
        if (r) {
          setData(r.data);
          setReportTitle(r.title);
        }
        setLoading(false);
      });
    }
  }, [id]);

  const handleFetchData = async () => {
    if (!data.country) return;
    setIsFetchingAI(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as a labour market intelligence expert. Fetch the latest available data from ILO (International Labour Organization), World Bank, and official government sources for ${data.country}.

        Return a strictly valid JSON object (no markdown, no code blocks) matching this structure exactly:
        {
          "capital": "string",
          "officialLanguage": "string",
          "population": "string (e.g. 1.4B)",
          "currency": "string",
          "gdp": "string (e.g. 400 Billion USD)",
          "hdi": "string (e.g. 0.750)",
          "directFlight": boolean,
          "uaeEmbassyLocation": "string (City in target country)",
          "foreignEmbassyLocation": "string (City in UAE, usually Abu Dhabi or Dubai)",
          "averageWage": "string (Monthly average in USD approx)",
          "minimumWage": "string (Monthly minimum in USD approx)",
          "totalWorkforce": "string (e.g. 50 Million)",
          "participationMale": number (percentage 0-100),
          "participationFemale": number (percentage 0-100),
          "migrationDestinations": [{"country": "string", "count": "string (e.g. 2.5 Million)"}],
          "topSectors": [{"name": "string", "value": number}, {"name": "string", "value": number}],
          "availableSkills": ["string", "string", "string", "string"]
        }

        For "migrationDestinations", provide the top 3-5 countries workers migrate to, and the estimated total number of workers in that country.
        For "availableSkills", list the top 4-6 specific job skills or industries that are abundant and available for migration (e.g. "Construction", "Nursing", "IT", "Domestic Work").`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          ...aiData,
          workforceStats: {
            ...prev.workforceStats,
            totalWorkforce: aiData.totalWorkforce,
            participationMale: aiData.participationMale,
            participationFemale: aiData.participationFemale,
            migrationDestinations: aiData.migrationDestinations || [],
            topSectors: aiData.topSectors,
            availableSkills: aiData.availableSkills || []
          }
        }));
      } else {
         // Fallback simulation
         await new Promise(r => setTimeout(r, 2000));
         setData(prev => ({
           ...prev,
           capital: 'Simulated Capital',
           officialLanguage: 'Simulated Language',
           population: '50M',
           currency: 'Unit',
           gdp: '500 Billion USD',
           hdi: '0.750',
           directFlight: true,
           uaeEmbassyLocation: 'Capital City',
           foreignEmbassyLocation: 'Abu Dhabi',
           averageWage: '$450/month',
           minimumWage: '$200/month',
           workforceStats: {
             ...prev.workforceStats,
             totalWorkforce: '25 Million',
             participationMale: 65,
             participationFemale: 35,
             migrationDestinations: [
               { country: 'UAE', count: '500,000' },
               { country: 'Saudi Arabia', count: '1.2 Million' },
               { country: 'UK', count: '100,000' }
             ],
             topSectors: [{name: 'Services', value: 50}, {name: 'Agriculture', value: 30}, {name: 'Industry', value: 20}],
             availableSkills: ['Construction', 'Hospitality', 'Nursing']
           }
         }));
      }
    } catch (error) {
      console.error("AI Fetch failed", error);
    } finally {
      setIsFetchingAI(false);
    }
  };

  const handleFetchEconomyEdu = async () => {
    if (!data.country) return;
    setIsFetchingEconomy(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as an economic analyst. Fetch the latest official economic and education data for ${data.country}, focusing on its relationship with the UAE (United Arab Emirates).

        Return a strictly valid JSON object (no markdown) with this structure:
        {
          "economicStats": {
            "inflation": "string (e.g. 5.1% in 2024)",
            "gdp": "string (e.g. 450 Billion USD)",
            "totalExportsToUAE": "string (e.g. 2 Billion USD)",
            "totalImportsFromUAE": "string (e.g. 5 Billion USD)",
            "topExportProducts": ["string", "string", "string"],
            "topImportProducts": ["string", "string", "string"],
            "mainEconomicPartners": ["string", "string", "string"],
            "tipRank": "string (e.g. Tier 2 Watch List)",
            "remittancesGlobal": "string (e.g. 40 Billion USD total global remittances received in 2023)"
          },
          "educationStats": {
             "topUniversities": ["string", "string", "string", "string", "string"],
             "primaryEnrollment": "string (e.g. 98%)",
             "higherEducationEnrollment": "string (e.g. 35%)"
          }
        }

        Note: 
        - topExportProducts: Products exported TO the UAE (from ${data.country}).
        - topImportProducts: Products imported FROM the UAE (to ${data.country}).
        - remittancesGlobal: Total remittances received by ${data.country} from ALL countries (World Bank data).
        - Do NOT populate "remittancesFromUAE", I will handle that manually.
        - tipRank: Refer to the US State Department Trafficking in Persons Report.
        `;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          economicStats: {
            ...prev.economicStats,
            ...aiData.economicStats
          },
          educationStats: {
            ...prev.educationStats,
            ...aiData.educationStats
          }
        }));

      } else {
        // Fallback
        await new Promise(r => setTimeout(r, 2000));
        setData(prev => ({
          ...prev,
          economicStats: {
            inflation: '4.2%',
            gdp: '300 Billion USD',
            totalExportsToUAE: '1.5 Billion USD',
            totalImportsFromUAE: '2.3 Billion USD',
            topExportProducts: ['Textiles', 'Food', 'Electronics'],
            topImportProducts: ['Oil', 'Machinery', 'Gold'],
            mainEconomicPartners: ['China', 'USA', 'UAE', 'India'],
            tipRank: 'Tier 2',
            remittancesFromUAE: '', // Left blank
            remittancesGlobal: '30 Billion USD (World Bank Est.)',
            customStats: []
          },
          educationStats: {
            topUniversities: ['National University', 'Technical Institute', 'City University'],
            primaryEnrollment: '95%',
            higherEducationEnrollment: '30%',
          }
        }));
      }
    } catch (error) {
      console.error("Economy Fetch Failed", error);
    } finally {
      setIsFetchingEconomy(false);
    }
  };

  const handleFetchAgreements = async (source: 'MOFA' | 'GENERAL') => {
    if (!data.country) return;
    setIsFetchingAgreements(true);

    try {
       if (process.env.API_KEY) {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

          let searchPrompt = "";
          if (source === 'MOFA') {
            searchPrompt = `Search specifically on site:mofa.gov.ae for bilateral agreements, diplomatic memorandums, and cooperation treaties between UAE and ${data.country}.`;
          } else {
            searchPrompt = `Search for official Memorandum of Understanding (MoU) and labour agreements signed between UAE and ${data.country} found in news or official archives.`;
          }

          const prompt = `${searchPrompt}

          Extract the details and return a strictly valid JSON array (no markdown, no code blocks).
          Each object in the array must have:
          - "title": The official title of the agreement/MoU.
          - "date": The year of signing (e.g. "2022") or full date if available.
          - "status": Assume "Active" unless explicitly stated as expired.
          - "summary": A very brief 1-sentence description.

          Return format: [{"title": "...", "date": "...", "status": "Active", "summary": "..."}]`;

          const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
              tools: [{ googleSearch: {} }],
            },
          });

          const text = response.text;
          const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();

          try {
            const newAgreements = JSON.parse(cleanJson);
            if (Array.isArray(newAgreements)) {
              setData(prev => ({
                ...prev,
                bilateralAgreements: [...prev.bilateralAgreements, ...newAgreements]
              }));
            }
          } catch (e) {
            console.error("Failed to parse agreement JSON", text);
          }

       } else {
          // Simulation
          await new Promise(r => setTimeout(r, 1500));
          const mockDocs = source === 'MOFA' 
            ? [{ title: `Diplomatic Cooperation Protocol (${data.country})`, date: '2021', status: 'Active', summary: 'Fetched from MOFA UAE: General diplomatic framework.' }]
            : [{ title: `MoU on Manpower Recruitment`, date: '2019', status: 'Active', summary: 'Fetched Online: Regulates domestic worker recruitment.' }];

          setData(prev => ({
            ...prev,
            bilateralAgreements: [...prev.bilateralAgreements, ...mockDocs] as any
          }));
       }
    } catch (error) {
      console.error("Agreement Fetch failed", error);
    } finally {
      setIsFetchingAgreements(false);
    }
  };

  const handleEnrichDelegate = async (type: 'uae' | 'partner', delegateIndex: number) => {
    const list = type === 'uae' ? data.delegations.uae : data.delegations.partner;
    const delegate = list[delegateIndex];
    if (!delegate.name) return;

    setEnrichingDelegateId(delegate.id);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Search for public information about ${delegate.name}, who is ${delegate.title || 'an official'} from ${type === 'uae' ? 'UAE' : data.country}.

        Return a strictly valid JSON object (no markdown) with:
        {
           "bio": "A short 2-3 sentence professional biography including age if public.",
           "imageUrl": "URL to a public official photo if found, otherwise empty string"
        }

        If you cannot find specific info, generate a generic professional bio placeholder.`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
          config: {
            tools: [{ googleSearch: {} }],
          },
        });

        const text = response.text;
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const info = JSON.parse(cleanJson);

        const newList = [...list];
        newList[delegateIndex] = {
          ...delegate,
          bio: info.bio || delegate.bio,
          imageUrl: info.imageUrl || delegate.imageUrl
        };

        setData(prev => ({
          ...prev,
          delegations: {
            ...prev.delegations,
            [type]: newList
          }
        }));
      } else {
        await new Promise(r => setTimeout(r, 1500));
        const newList = [...list];
        newList[delegateIndex] = {
          ...delegate,
          bio: `Simulated bio for ${delegate.name}. Senior official with extensive experience in international relations.`,
          imageUrl: `https://ui-avatars.com/api/?name=${delegate.name.replace(' ', '+')}&background=random`
        };
        setData(prev => ({
          ...prev,
          delegations: {
            ...prev.delegations,
            [type]: newList
          }
        }));
      }
    } catch (error) {
       console.error("Delegate enrich failed", error);
    } finally {
      setEnrichingDelegateId(null);
    }
  };

  const addDelegate = (type: 'uae' | 'partner') => {
    const newDelegate: Delegate = {
      id: uuidv4(),
      name: '',
      title: '',
      imageUrl: '',
      bio: ''
    };
    setData(prev => ({
      ...prev,
      delegations: {
        ...prev.delegations,
        [type]: [...prev.delegations[type], newDelegate]
      }
    }));
  };

  const removeDelegate = (type: 'uae' | 'partner', index: number) => {
    const list = type === 'uae' ? data.delegations.uae : data.delegations.partner;
    const newList = list.filter((_, i) => i !== index);
    setData(prev => ({
      ...prev,
      delegations: {
        ...prev.delegations,
        [type]: newList
      }
    }));
  };

  const handleSave = async (status: 'draft' | 'completed' = 'draft') => {
    const reportId = id || `r-${uuidv4().slice(0, 8)}`;
    const newReport: Report = {
      id: reportId,
      userId: 'u-1',
      title: reportTitle || `Report for ${data.country || 'Unknown'}`,
      status,
      updatedAt: new Date().toISOString(),
      data
    };
    await MockService.saveReport(newReport);
    if (status === 'completed') {
      navigate('/dashboard');
    } else {
      console.log('Saved draft');
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
             {/* Country & AI Fetch Row */}
            <div className="flex flex-col md:flex-row gap-4 items-end bg-blue-50/50 p-6 rounded-xl border border-blue-100">
               <div className="flex-1 w-full">
                 <Input 
                    label={t('country')} 
                    value={data.country} 
                    onChange={e => setData({...data, country: e.target.value})} 
                    placeholder="e.g. Vietnam"
                    className="text-lg font-medium"
                  />
               </div>
               <Button 
                onClick={handleFetchData} 
                disabled={!data.country || isFetchingAI}
                className="w-full md:w-auto bg-accent hover:bg-accent-light text-white border-none shadow-lg"
              >
                {isFetchingAI ? <Loader2 className="animate-spin" /> : <Sparkles size={18} />}
                Fetch Data (ILO/WB)
              </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
              {/* Row 2: Capital & Language */}
              <Input 
                label={t('capital')} 
                value={data.capital} 
                onChange={e => setData({...data, capital: e.target.value})} 
              />
              <Input 
                label="Official Language" 
                value={data.officialLanguage} 
                onChange={e => setData({...data, officialLanguage: e.target.value})} 
              />

              {/* Row 3: Direct Flight */}
               <div className="flex flex-col gap-1.5 md:col-span-2">
                 <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Plane size={14} /> Direct Flight to UAE
                 </label>
                 <div className="flex gap-4">
                    <button 
                      onClick={() => setData({...data, directFlight: true})}
