            {data.bilateralAgreements.length === 0 && (
              <div className="text-center p-8 text-gray-400 bg-gray-50 rounded-lg border border-dashed">
                No agreements recorded. Use the buttons above to fetch or add one manually below.
              </div>
            )}

            <div className="grid gap-4">
              {data.bilateralAgreements.map((agreement, idx) => (
                <Card key={idx} className="relative group transition-all hover:shadow-md border border-gray-100 hover:border-primary/30">
                  <button 
                    className="absolute top-4 right-4 text-gray-300 hover:text-red-500 p-1 rounded transition-colors"
                    onClick={() => {
                      const filtered = data.bilateralAgreements.filter((_, i) => i !== idx);
                      setData({...data, bilateralAgreements: filtered});
                    }}
                  >
                    <div className="sr-only">Delete</div>
                    <span>×</span>
                  </button>

                  <div className="grid gap-4">
                    <div className="pr-8">
                      <Input 
                        placeholder="Agreement Title (e.g. Protocol on Domestic Workers)" 
                        value={agreement.title}
                        className="font-bold text-lg border-transparent focus:border-gray-300 px-0 -ml-0"
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].title = e.target.value;
                          setData({...data, bilateralAgreements: ag});
                        }}
                      />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Year / Date</label>
                        <Input 
                          placeholder="YYYY"
                          value={agreement.date}
                          onChange={(e) => {
                            const ag = [...data.bilateralAgreements];
                            ag[idx].date = e.target.value;
                            setData({...data, bilateralAgreements: ag});
                          }}
                        />
                      </div>
                      <div>
                        <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Status</label>
                        <select 
                          className="w-full px-4 py-2 rounded-lg border border-gray-300 bg-white"
                          value={agreement.status}
                          onChange={(e) => {
                            const ag = [...data.bilateralAgreements];
                            ag[idx].status = e.target.value as any;
                            setData({...data, bilateralAgreements: ag});
                          }}
                        >
                          <option>Active</option>
                          <option>Pending</option>
                          <option>Expired</option>
                        </select>
                      </div>
                    </div>

                    <div>
                      <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Summary</label>
                      <Input 
                        placeholder="Brief description of the agreement..." 
                        value={agreement.summary}
                        onChange={(e) => {
                          const ag = [...data.bilateralAgreements];
                          ag[idx].summary = e.target.value;
                          setData({...data, bilateralAgreements: ag});
                        }}
                      />
                    </div>
                  </div>
                </Card>
              ))}
            </div>

            <Button 
              variant="outline"
              className="w-full border-dashed border-2 py-4 text-gray-500 hover:text-primary hover:border-primary hover:bg-primary/5"
              onClick={() => setData({
                ...data, 
                bilateralAgreements: [...data.bilateralAgreements, { title: '', date: '', status: 'Active', summary: '' }]
              })}
            >
              + Add Manual Agreement
            </Button>
          </div>
        );
      case 4: // NEW: Delegation Step
        const renderDelegationList = (type: 'uae' | 'partner', list: Delegate[]) => (
           <div className="space-y-4">
              <div className="flex justify-between items-center">
                 <h3 className="font-serif font-bold text-lg flex items-center gap-2">
                    {type === 'uae' ? <img src="https://flagcdn.com/w40/ae.png" className="h-4 w-auto" alt="UAE" /> : <Globe size={18} className="text-gray-500" />}
                    {type === 'uae' ? 'UAE Delegation' : `${data.country || 'Partner'} Delegation`}
                 </h3>
                 <Button size="sm" variant="outline" onClick={() => addDelegate(type)}>
                    <UserPlus size={16} /> Add Member
                 </Button>
              </div>
              <div className="space-y-4">
                 {list.length === 0 && <p className="text-sm text-gray-400 italic text-center py-4 border border-dashed rounded-lg">No delegates added yet.</p>}
                 {list.map((delegate, idx) => (
                    <Card key={delegate.id} className="relative group p-4 bg-gray-50/50">
                       <button 
                         className="absolute top-2 right-2 text-gray-300 hover:text-red-500 p-1"
                         onClick={() => removeDelegate(type, idx)}
                       >
                         <X size={16} />
                       </button>
                       <div className="flex gap-4 items-start">
                          <div className="w-20 h-20 bg-gray-200 rounded-lg flex-shrink-0 overflow-hidden relative group/img">
