                          <div className="flex-1 space-y-2">
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                <Input 
                                   placeholder="Full Name"
                                   className="font-bold"
                                   value={delegate.name}
                                   onChange={e => {
                                      const newList = [...list];
                                      newList[idx].name = e.target.value;
                                      setData({...data, delegations: {...data.delegations, [type]: newList}});
                                   }}
