                                <div className="flex gap-2">
                                  <Input 
                                     placeholder="Job Title"
                                     className="flex-1"
                                     value={delegate.title}
                                     onChange={e => {
                                        const newList = [...list];
                                        newList[idx].title = e.target.value;
                                        setData({...data, delegations: {...data.delegations, [type]: newList}});
                                     }}
                                  />
                                  <Button 
                                    size="sm" 
                                    className="bg-accent text-white h-[42px] px-3 mt-[21px]"
                                    title="Auto-fill bio & image using AI"
                                    onClick={() => handleEnrichDelegate(type, idx)}
                                    disabled={!delegate.name || enrichingDelegateId === delegate.id}
                                  >
                                    {enrichingDelegateId === delegate.id ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />}
