          <p className="text-xs text-gray-500 uppercase">Capital</p>
          <p className="font-bold text-lg">{data.capital}</p>
        </div>
        <div className="text-center border-r border-gray-200">
          <p className="text-xs text-gray-500 uppercase">Population</p>
          <p className="font-bold text-lg">{data.population}</p>
        </div>
        <div className="text-center border-r border-gray-200">
          <p className="text-xs text-gray-500 uppercase">Currency</p>
          <p className="font-bold text-lg">{data.currency}</p>
        </div>
        <div className="text-center">
          <p className="text-xs text-gray-500 uppercase">GDP</p>
