                                     setData({...data, delegations: {...data.delegations, [type]: newList}});
                                  }}
                               />
                               <div className="absolute bottom-2 right-2 pointer-events-none">
                                 <FileText size={12} className="text-gray-300" />
                               </div>
                             </div>
                          </div>
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        );

        return (
          <div className="animate-in slide-in-from-right-4 duration-300 h-full">
             <div className="grid grid-cols-1 lg:grid-cols-[1fr_1px_1fr] gap-8 lg:gap-12 h-full">
                {renderDelegationList('uae', data.delegations?.uae || [])}
                <div className="hidden lg:block w-px bg-gray-200 my-4"></div>
                {renderDelegationList('partner', data.delegations?.partner || [])}
             </div>
          </div>
        );
      case 5: // Preview (formerly step 3/4)
        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
            <div className="bg-gray-100 p-8 rounded-xl border border-gray-200">
              <h2 className="font-serif text-2xl mb-4 text-center">{reportTitle}</h2>
              <div className="bg-white p-8 shadow-diplomatic max-w-2xl mx-auto space-y-6">
                <div className="flex items-center gap-4 border-b pb-4">
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('country')}</p>
                    <p className="text-xl font-bold">{data.country}</p>
                  </div>
                  <div className="flex-1">
                    <p className="text-sm text-gray-500 uppercase tracking-wide">{t('capital')}</p>
                    <p className="text-xl font-bold">{data.capital}</p>
                  </div>
                </div>

                {/* Economy Preview */}
                <div>
                   <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Economy</h3>
                   <div className="grid grid-cols-2 gap-4 text-sm">
                      <div><span className="text-gray-500">Inflation:</span> {data.economicStats?.inflation}</div>
                      <div><span className="text-gray-500">GDP:</span> {data.economicStats?.gdp}</div>
                      <div className="col-span-2"><span className="text-gray-500">Exports to UAE:</span> {data.economicStats?.totalExportsToUAE}</div>
                      <div className="col-span-2"><span className="text-gray-500">Remittances (UAE):</span> {data.economicStats?.remittancesFromUAE || 'N/A'}</div>
                      <div className="col-span-2"><span className="text-gray-500">Remittances (Global):</span> {data.economicStats?.remittancesGlobal}</div>
                   </div>
                   {data.economicStats.customStats?.length > 0 && (
                     <div className="mt-2 grid grid-cols-2 gap-4 text-sm border-t pt-2">
                        {data.economicStats.customStats.map(stat => (
                           <div key={stat.id}>
                              <span className="text-gray-500">{stat.label}:</span> {stat.value}
                           </div>
                        ))}
                     </div>
                   )}
                </div>

                <div>
                  <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">{t('agreements')}</h3>
                  <ul className="list-disc ml-5 space-y-1">
                    {data.bilateralAgreements.map((a, i) => (
                      <li key={i}><span className="font-medium">{a.title}</span> ({a.status})</li>
                    ))}
                  </ul>
                </div>

                {/* Delegation Preview */}
                <div>
                  <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Delegations</h3>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                     <div>
                        <p className="font-bold text-gray-700 mb-1">UAE Side</p>
                        <ul className="list-disc ml-4">
                           {data.delegations?.uae.map(d => (
                              <li key={d.id}>{d.name} <span className="text-xs text-gray-400">({d.title})</span></li>
                           ))}
                        </ul>
                     </div>
                     <div>
                        <p className="font-bold text-gray-700 mb-1">{data.country} Side</p>
                        <ul className="list-disc ml-4">
                           {data.delegations?.partner.map(d => (
                              <li key={d.id}>{d.name} <span className="text-xs text-gray-400">({d.title})</span></li>
                           ))}
                        </ul>
                     </div>
                  </div>
                </div>

                {data.customSections?.map(s => (
                  <div key={s.id}>
                    <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">{s.title}</h3>
                    <p className="text-sm text-gray-700 whitespace-pre-wrap">{s.content}</p>
                  </div>
                ))}

                <div className="p-4 bg-blue-50 text-blue-800 rounded text-center text-sm">
                  This is a preview. Click "Complete Report" to finalize.
                </div>
              </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  if (loading) return <div className="p-8 text-center">Loading...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-12">
      {/* Wizard Header */}
      <div className="mb-8">
        <Input 
          placeholder="Report Title (e.g. Bilateral Meeting India 2024)"
          className="text-2xl font-serif font-bold bg-transparent border-transparent px-0 focus:ring-0 focus:border-primary placeholder:text-gray-300"
          value={reportTitle}
          onChange={(e) => setReportTitle(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Steps Sidebar */}
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'}
                ${idx < currentStep ? 'text-primary font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        {/* Content Area */}
        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button 
              variant="ghost" 
              onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
              disabled={currentStep === 0}
            >
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} />
              {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}>
                <Save size={16} />
                {t('save')}
              </Button>

              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>
                  {t('next')}
                  <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} />
                </Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">
                  {t('finish')}
                  <CheckCircle size={16} />
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export type Language = 'en' | 'ar';
export type ReportStatus = 'draft' | 'completed';
export type UserRole = 'admin' | 'user';

export interface UserProfile {
  id: string;
