import { Button, Card, Input } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle, Plane, Building, TrendingUp, Sparkles, Loader2, RefreshCw, Link as LinkIcon, Search, Hammer, GraduationCap, Briefcase, Plus, X, Banknote, UserPlus, Image as ImageIcon, BarChart2 } from 'lucide-react';
