const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'uae-workforce', icon: BarChart2, label: 'Workforce in UAE' },
  { id: 'workforce', icon: Users, label: 'Partner Workforce' },
