              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button 
              variant="ghost" 
              onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
              disabled={currentStep === 0}
            >
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} />
              {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}>
                <Save size={16} />
                {t('save')}
              </Button>

              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>
                  {t('next')}
                  <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} />
                </Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">
                  {t('finish')}
                  <CheckCircle size={16} />
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

