        await new Promise(r => setTimeout(r, 1000)); 
        // Logic same as previous
      }
      // Fallback
      await new Promise(r => setTimeout(r, 1000));
       setData(prev => ({
          ...prev,
          economicStats: {
            ...prev.economicStats,
            remittancesGlobal: '50B USD',
          }
        }));
    } finally {
      setIsFetchingEconomy(false);
    }
  };

   const handleFetchAgreements = async (source: 'MOFA' | 'GENERAL') => {
      setIsFetchingAgreements(false);
   };

