  const addSector = (section: 'mohre' | 'icp') => {
    const sectionData = data.uaeWorkforceStats[section];
    setData({
      ...data,
      uaeWorkforceStats: {
        ...data.uaeWorkforceStats,
        [section]: {
          ...sectionData,
          bySector: [...sectionData.bySector, { name: '', value: 0 }]
