                          <p className="font-bold text-lg">{d.name}</p>
                          <p className="text-sm font-medium text-gray-600 mb-2">{d.title}</p>
                          <ul className="text-xs text-gray-500 list-disc ml-4 space-y-1">
                             {d.bio.split('\n').map((line, i) => line && <li key={i}>{line}</li>)}
                          </ul>
                       </div>
                    </div>
                 ))}
              </div>
           </div>
           <div>
              <h4 className="font-bold text-lg mb-4 flex items-center gap-2">
                 Partner Delegation
              </h4>
              <div className="space-y-6">
                 {data.delegations.partner.map(d => (
                    <div key={d.id} className="flex gap-4 items-start">
                       <div className="w-20 h-24 bg-gray-100 rounded flex-shrink-0 overflow-hidden">
                          {d.imageUrl && <img src={d.imageUrl} className="w-full h-full object-cover" />}
                       </div>
                       <div>
                          <p className="font-bold text-lg">{d.name}</p>
                          <p className="text-sm font-medium text-gray-600 mb-2">{d.title}</p>
                           <ul className="text-xs text-gray-500 list-disc ml-4 space-y-1">
                             {d.bio.split('\n').map((line, i) => line && <li key={i}>{line}</li>)}
                          </ul>
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        </div>
      </section>

      {/* Footer */}
      <div className="fixed bottom-0 left-0 right-0 p-8 border-t bg-white text-center">
        <p className="text-xs font-bold text-red-600 tracking-widest">CONFIDENTIAL / INTERNAL USE ONLY</p>
        <p className="text-[10px] text-gray-400 mt-1">Generated by UAE Labour Market Intelligence System • {report.id}</p>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { ReportData, EMPTY_REPORT_DATA, Report, Delegate, LabelValue, NewsItem, RecentInteraction, PointOfDiscussion } from '../types';
import { MockService } from '../services/mockService';
import { Button, Card, Input } from '../components/ui/LayoutComponents';
import { ArrowLeft, ArrowRight, Save, Globe, Users, FileText, CheckCircle, Plane, Building, TrendingUp, Sparkles, Loader2, RefreshCw, Link as LinkIcon, Search, Hammer, GraduationCap, Briefcase, Plus, X, Banknote, UserPlus, Image as ImageIcon, BarChart2, MessageSquare, Newspaper, Calendar } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from "@google/genai";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

const STEPS = [
  { id: 'profile', icon: Globe, label: 'Country Profile' },
  { id: 'uae-workforce', icon: BarChart2, label: 'Workforce in UAE' },
  { id: 'workforce', icon: Users, label: 'Partner Workforce' },
  { id: 'economy', icon: Briefcase, label: 'Economy & Education' },
  { id: 'interactions', icon: MessageSquare, label: 'Interactions & News' },
  { id: 'agreements', icon: FileText, label: 'Agreements' },
  { id: 'delegation', icon: Users, label: 'Delegations' },
  { id: 'preview', icon: CheckCircle, label: 'Preview' },
];

export default function Wizard() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(!!id);
  const [isFetchingAI, setIsFetchingAI] = useState(false);
  const [isFetchingAgreements, setIsFetchingAgreements] = useState(false);
  const [isFetchingEconomy, setIsFetchingEconomy] = useState(false);
  const [isFetchingNews, setIsFetchingNews] = useState(false);
  const [enrichingDelegateId, setEnrichingDelegateId] = useState<string | null>(null);
  const [data, setData] = useState<ReportData>(EMPTY_REPORT_DATA);
  const [reportTitle, setReportTitle] = useState('');

  useEffect(() => {
    if (id) {
      MockService.getReportById(id).then(r => {
        if (r) {
          setData(r.data);
          setReportTitle(r.title);
        }
        setLoading(false);
      });
    }
  }, [id]);

  const handleFetchData = async () => {
    if (!data.country) return;
    setIsFetchingAI(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as a labour market intelligence expert. Fetch the latest available data from ILO (International Labour Organization), World Bank, and official government sources for ${data.country}.

        Return a strictly valid JSON object (no markdown, no code blocks) matching this structure exactly:
        {
          "capital": "string",
          "officialLanguage": "string",
          "population": "string (e.g. 1.4B)",
          "currency": "string",
          "gdp": "string (e.g. 400 Billion USD)",
          "hdi": "string (e.g. 0.750)",
          "directFlight": boolean,
          "uaeEmbassyLocation": "string (City in target country)",
          "foreignEmbassyLocation": "string (City in UAE, usually Abu Dhabi or Dubai)",
          "averageWage": "string (Monthly average in USD approx)",
          "minimumWage": "string (Monthly minimum in USD approx)",
          "totalWorkforce": "string (e.g. 50 Million)",
          "participationMale": number (percentage 0-100),
          "participationFemale": number (percentage 0-100),
          "migrationDestinations": [{"country": "string", "count": "string (e.g. 2.5 Million)"}],
          "topSectors": [{"name": "string", "value": number}, {"name": "string", "value": number}],
          "availableSkills": ["string", "string", "string", "string"]
        }

        For "migrationDestinations", provide the top 3-5 countries workers migrate to, and the estimated total number of workers in that country.
        For "availableSkills", list the top 4-6 specific job skills or industries that are abundant and available for migration (e.g. "Construction", "Nursing", "IT", "Domestic Work").`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          ...aiData,
          workforceStats: {
            ...prev.workforceStats,
            totalWorkforce: aiData.totalWorkforce,
            participationMale: aiData.participationMale,
            participationFemale: aiData.participationFemale,
            migrationDestinations: aiData.migrationDestinations || [],
            topSectors: aiData.topSectors,
            availableSkills: aiData.availableSkills || []
          }
        }));
      } else {
         // Fallback simulation
         await new Promise(r => setTimeout(r, 2000));
         setData(prev => ({
           ...prev,
           capital: 'Simulated Capital',
           officialLanguage: 'Simulated Language',
           population: '50M',
           currency: 'Unit',
           gdp: '500 Billion USD',
           hdi: '0.750',
           directFlight: true,
           uaeEmbassyLocation: 'Capital City',
           foreignEmbassyLocation: 'Abu Dhabi',
           averageWage: '$450/month',
           minimumWage: '$200/month',
           workforceStats: {
             ...prev.workforceStats,
             totalWorkforce: '25 Million',
             participationMale: 65,
             participationFemale: 35,
             migrationDestinations: [
               { country: 'UAE', count: '500,000' },
               { country: 'Saudi Arabia', count: '1.2 Million' },
               { country: 'UK', count: '100,000' }
             ],
             topSectors: [{name: 'Services', value: 50}, {name: 'Agriculture', value: 30}, {name: 'Industry', value: 20}],
             availableSkills: ['Construction', 'Hospitality', 'Nursing']
           }
         }));
      }
    } catch (error) {
      console.error("AI Fetch failed", error);
    } finally {
      setIsFetchingAI(false);
    }
  };

  const handleFetchNews = async () => {
     if (!data.country) return;
     setIsFetchingNews(true);

     try {
       if (process.env.API_KEY) {
         const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
         const prompt = `Search for the top 3 most recent and relevant news articles regarding "Labour", "Workforce", "Migrant Workers", or "Economic Relations" between UAE and ${data.country}.

         Return a strictly valid JSON array of objects with this structure:
         [
           {
             "title": "string (Headline)",
             "source": "string (News Source)",
             "date": "string (Date string)",
             "summary": "string (1 sentence summary)",
             "url": "string (Link if available)"
           }
         ]`;

         const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
              tools: [{ googleSearch: {} }],
            },
         });

         const text = response.text;
         const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
         const newsItems = JSON.parse(cleanJson);

         // Add IDs
         const newsWithIds = newsItems.map((n: any) => ({ ...n, id: uuidv4() }));

         setData(prev => ({
            ...prev,
            relatedNews: [...(prev.relatedNews || []), ...newsWithIds]
         }));
       } else {
         await new Promise(r => setTimeout(r, 1500));
         setData(prev => ({
            ...prev,
            relatedNews: [
               ...prev.relatedNews,
               { id: uuidv4(), title: 'Bilateral Labour Agreement Renewed', source: 'Simulated News', date: '2023-11-01', summary: 'Both countries agreed to enhance worker protection.', url: '#' },
               { id: uuidv4(), title: 'New Skill Verification Center Opened', source: 'Simulated News', date: '2023-10-15', summary: 'A center to test workers before migration.', url: '#' }
            ]
         }));
       }
     } catch (error) {
        console.error("News Fetch Failed", error);
     } finally {
        setIsFetchingNews(false);
     }
  };

  const handleFetchEconomyEdu = async () => {
    if (!data.country) return;
    setIsFetchingEconomy(true);

    try {
      if (process.env.API_KEY) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as an economic analyst. Fetch the latest official economic and education data for ${data.country}, focusing on its relationship with the UAE. 

        Return a strictly valid JSON object (no markdown) with this structure:
        {
          "economicStats": {
            "inflation": "string (e.g. 5.1% in 2024)",
            "gdp": "string (e.g. 450 Billion USD)",
            "totalExportsToUAE": "string (e.g. 2 Billion USD)",
            "totalImportsFromUAE": "string (e.g. 5 Billion USD)",
            "topExportProducts": ["string", "string", "string"],
            "topImportProducts": ["string", "string", "string"],
            "mainEconomicPartners": ["string", "string", "string"],
            "tipRank": "string (e.g. Tier 2 Watch List)",
            "remittancesGlobal": "string (e.g. 40 Billion USD total global remittances received in 2023)"
          },
          "educationStats": {
             "topUniversities": ["string", "string", "string", "string", "string"],
             "primaryEnrollment": "string (e.g. 98%)",
             "higherEducationEnrollment": "string (e.g. 35%)"
          }
        }`;

        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
        });

        const text = response.text;
        const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const aiData = JSON.parse(cleanJson);

        setData(prev => ({
          ...prev,
          economicStats: {
            ...prev.economicStats,
            ...aiData.economicStats
          },
          educationStats: {
            ...prev.educationStats,
            ...aiData.educationStats
          }
        }));
      } else {
        await new Promise(r => setTimeout(r, 1000));
        setData(prev => ({
          ...prev,
          economicStats: {
            ...prev.economicStats,
            remittancesGlobal: '50B USD',
            inflation: '4.2%',
            gdp: '300 Billion USD',
          }
        }));
      }
    } catch (error) {
      console.error("Economy Fetch Failed", error);
    } finally {
      setIsFetchingEconomy(false);
    }
  };

   const handleFetchAgreements = async (source: 'MOFA' | 'GENERAL') => {
      setIsFetchingAgreements(false);
   };

   const handleEnrichDelegate = async (type: 'uae' | 'partner', delegateIndex: number) => {
      setEnrichingDelegateId(null);
   };

  const addDelegate = (type: 'uae' | 'partner') => {
    const newDelegate: Delegate = {
      id: uuidv4(),
      name: '',
      title: '',
      imageUrl: '',
      bio: ''
    };
    setData(prev => ({
      ...prev,
      delegations: {
        ...prev.delegations,
        [type]: [...prev.delegations[type], newDelegate]
      }
    }));
  };

  const removeDelegate = (type: 'uae' | 'partner', index: number) => {
    const list = type === 'uae' ? data.delegations.uae : data.delegations.partner;
    const newList = list.filter((_, i) => i !== index);
    setData(prev => ({
      ...prev,
      delegations: {
        ...prev.delegations,
        [type]: newList
      }
    }));
  };

  const handleSave = async (status: 'draft' | 'completed' = 'draft') => {
    const reportId = id || `r-${uuidv4().slice(0, 8)}`;
    const newReport: Report = {
      id: reportId,
      userId: 'u-1',
      title: reportTitle || `Report for ${data.country || 'Unknown'}`,
      status,
      updatedAt: new Date().toISOString(),
      data
    };
    await MockService.saveReport(newReport);
    if (status === 'completed') {
      navigate('/dashboard');
    } else {
      console.log('Saved draft');
    }
  };

  const updateUaeWorkforce = (
     section: 'mohre' | 'icp', 
     type: 'byEmirate' | 'bySector', 
     index: number, 
     field: 'name' | 'value', 
     val: string | number
  ) => {
    const sectionData = data.uaeWorkforceStats[section];
    const array = [...sectionData[type]];

    if (field === 'value') {
       array[index].value = Number(val);
    } else {
       array[index].name = String(val);
    }

    setData({
      ...data,
      uaeWorkforceStats: {
        ...data.uaeWorkforceStats,
        [section]: {
          ...sectionData,
          [type]: array
        }
      }
    });
  };

  const addSector = (section: 'mohre' | 'icp') => {
    const sectionData = data.uaeWorkforceStats[section];
    setData({
      ...data,
      uaeWorkforceStats: {
        ...data.uaeWorkforceStats,
        [section]: {
          ...sectionData,
          bySector: [...sectionData.bySector, { name: '', value: 0 }]
        }
      }
    });
  };

  const removeSector = (section: 'mohre' | 'icp', index: number) => {
     const sectionData = data.uaeWorkforceStats[section];
     const newSectors = sectionData.bySector.filter((_, i) => i !== index);
     setData({
      ...data,
      uaeWorkforceStats: {
        ...data.uaeWorkforceStats,
        [section]: {
          ...sectionData,
          bySector: newSectors
        }
      }
    });
  };

  const renderStep = () => {
    switch (currentStep) {
      case 0: // Profile
        return (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
             <div className="flex flex-col md:flex-row gap-4 items-end bg-blue-50/50 p-6 rounded-xl border border-blue-100">
               <div className="flex-1 w-full">
                 <Input label={t('country')} value={data.country} onChange={e => setData({...data, country: e.target.value})} placeholder="e.g. Vietnam" className="text-lg font-medium" />
               </div>
               <Button onClick={handleFetchData} disabled={!data.country || isFetchingAI} className="w-full md:w-auto bg-accent hover:bg-accent-light text-white border-none shadow-lg">
                {isFetchingAI ? <Loader2 className="animate-spin" /> : <Sparkles size={18} />} Fetch Data (ILO/WB)
              </Button>
            </div>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
              <Input label={t('capital')} value={data.capital} onChange={e => setData({...data, capital: e.target.value})} />
              <Input label="Official Language" value={data.officialLanguage} onChange={e => setData({...data, officialLanguage: e.target.value})} />

              <div className="flex flex-col gap-1.5 md:col-span-2">
                 <label className="text-sm font-semibold text-foreground/80 flex items-center gap-2">
                   <Plane size={14} /> Direct Flight to UAE
                 </label>
                 <div className="flex gap-4">
                    <button 
                      onClick={() => setData({...data, directFlight: true})}
                      className={`flex-1 py-3 rounded-lg border font-medium transition-all ${data.directFlight ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-gray-500 hover:bg-gray-50'}`}
                    >Yes, Direct Flights Available</button>
                    <button 
                      onClick={() => setData({...data, directFlight: false})}
                      className={`flex-1 py-3 rounded-lg border font-medium transition-all ${!data.directFlight ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-gray-500 hover:bg-gray-50'}`}
                    >No Direct Flights</button>
                 </div>
              </div>

              <Input label="UAE Embassy" value={data.uaeEmbassyLocation} onChange={e => setData({...data, uaeEmbassyLocation: e.target.value})} />
              <Input label="Foreign Embassy" value={data.foreignEmbassyLocation} onChange={e => setData({...data, foreignEmbassyLocation: e.target.value})} />
              <Input label="GDP" value={data.gdp} onChange={e => setData({...data, gdp: e.target.value})} />
              <Input label="HDI" value={data.hdi} onChange={e => setData({...data, hdi: e.target.value})} />
              <Input label="Population" value={data.population} onChange={e => setData({...data, population: e.target.value})} />
              <Input label="Currency" value={data.currency} onChange={e => setData({...data, currency: e.target.value})} />
            </div>
          </div>
        );
      case 1: // UAE Workforce
        return (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
             <div className="border-b pb-4">
               <h3 className="text-lg font-serif font-bold text-primary flex items-center gap-2">
                  <BarChart2 size={20} /> Workforce in UAE
               </h3>
               <p className="text-sm text-gray-500">Breakdown of workers by MOHRE and ICP data sources.</p>
             </div>

             <div className="bg-primary/5 p-4 rounded-xl border border-primary/20">
                 <h4 className="font-bold text-primary-dark mb-3 text-sm uppercase">Key Workforce Metrics</h4>
                 {data.uaeWorkforceStats.custom.map((item, i) => (
                    <div key={item.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-3">
                       <Input value={item.label} disabled={item.isTotal} onChange={(e) => { const newCustom = [...data.uaeWorkforceStats.custom]; newCustom[i].label = e.target.value; setData({...data, uaeWorkforceStats: {...data.uaeWorkforceStats, custom: newCustom}}); }} placeholder="Title" />
                       <Input value={item.value} onChange={(e) => { const newCustom = [...data.uaeWorkforceStats.custom]; newCustom[i].value = e.target.value; setData({...data, uaeWorkforceStats: {...data.uaeWorkforceStats, custom: newCustom}}); }} placeholder="Value" />
                       <Input value={item.date} onChange={(e) => { const newCustom = [...data.uaeWorkforceStats.custom]; newCustom[i].date = e.target.value; setData({...data, uaeWorkforceStats: {...data.uaeWorkforceStats, custom: newCustom}}); }} placeholder="Date" />
                       {!item.isTotal && (
                          <button className="text-red-500" onClick={() => { const newCustom = data.uaeWorkforceStats.custom.filter(c => c.id !== item.id); setData({...data, uaeWorkforceStats: {...data.uaeWorkforceStats, custom: newCustom}}); }}>X</button>
                       )}
                    </div>
                 ))}
                 <Button size="sm" variant="ghost" onClick={() => { setData({...data, uaeWorkforceStats: { ...data.uaeWorkforceStats, custom: [...data.uaeWorkforceStats.custom, { id: uuidv4(), label: '', value: '', date: '', isTotal: false }] }}) }}>+ Add Indicator</Button>
             </div>

             {/* MOHRE Data */}
             <div className="space-y-6">
                <h4 className="font-serif font-bold text-xl text-gray-800 border-b pb-2">MOHRE Data</h4>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <Card className="p-4 bg-gray-50">
                      <h5 className="font-bold text-sm mb-2 text-gray-600">Total Private Sector Workers</h5>
                      <div className="flex gap-2">
                         <Input placeholder="Number" value={data.uaeWorkforceStats.mohre.totalPrivate.value} onChange={e => setData({ ...data, uaeWorkforceStats: { ...data.uaeWorkforceStats, mohre: { ...data.uaeWorkforceStats.mohre, totalPrivate: { ...data.uaeWorkforceStats.mohre.totalPrivate, value: e.target.value } } } })} />
                         <Input placeholder="As of (Date)" value={data.uaeWorkforceStats.mohre.totalPrivate.date} onChange={e => setData({ ...data, uaeWorkforceStats: { ...data.uaeWorkforceStats, mohre: { ...data.uaeWorkforceStats.mohre, totalPrivate: { ...data.uaeWorkforceStats.mohre.totalPrivate, date: e.target.value } } } })} />
                      </div>
                   </Card>
                   <Card className="p-4 bg-gray-50">
                      <h5 className="font-bold text-sm mb-2 text-gray-600">Total Domestic Workers</h5>
                      <div className="flex gap-2">
                         <Input placeholder="Number" value={data.uaeWorkforceStats.mohre.totalDomestic.value} onChange={e => setData({ ...data, uaeWorkforceStats: { ...data.uaeWorkforceStats, mohre: { ...data.uaeWorkforceStats.mohre, totalDomestic: { ...data.uaeWorkforceStats.mohre.totalDomestic, value: e.target.value } } } })} />
                         <Input placeholder="As of (Date)" value={data.uaeWorkforceStats.mohre.totalDomestic.date} onChange={e => setData({ ...data, uaeWorkforceStats: { ...data.uaeWorkforceStats, mohre: { ...data.uaeWorkforceStats.mohre, totalDomestic: { ...data.uaeWorkforceStats.mohre.totalDomestic, date: e.target.value } } } })} />
                      </div>
                   </Card>
                </div>

                <div>
                   <h5 className="font-bold text-sm mb-3 text-gray-600">Workers by Emirate</h5>
                   <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      {data.uaeWorkforceStats.mohre.byEmirate.map((em, idx) => (
                         <div key={idx} className="bg-white border rounded p-3">
                            <label className="text-xs font-bold text-gray-500 block mb-1">{em.name}</label>
                            <input type="number" className="w-full text-sm font-mono border-b focus:border-primary outline-none" value={em.value} onChange={e => updateUaeWorkforce('mohre', 'byEmirate', idx, 'value', e.target.value)} />
                         </div>
                      ))}
                   </div>
                </div>

                <div>
                   <h5 className="font-bold text-sm mb-3 text-gray-600">Workers by Sector</h5>
                   {data.uaeWorkforceStats.mohre.bySector.map((sec, idx) => (
                      <div key={idx} className="flex gap-4 mb-2 items-center">
                         <Input placeholder="Sector Name" className="flex-1" value={sec.name} onChange={e => updateUaeWorkforce('mohre', 'bySector', idx, 'name', e.target.value)} />
                         <Input type="number" placeholder="Count" className="w-32" value={sec.value} onChange={e => updateUaeWorkforce('mohre', 'bySector', idx, 'value', e.target.value)} />
                         <button onClick={() => removeSector('mohre', idx)} className="text-gray-400 hover:text-red-500">X</button>
                      </div>
                   ))}
                   <Button size="sm" variant="outline" onClick={() => addSector('mohre')}>+ Add Sector</Button>
                </div>
             </div>

             {/* ICP Data */}
             <div className="space-y-6 pt-6 border-t">
                <h4 className="font-serif font-bold text-xl text-gray-800 border-b pb-2">ICP Data</h4>

                <div>
                   <h5 className="font-bold text-sm mb-3 text-gray-600">Distribution by Emirate</h5>
                   <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      {data.uaeWorkforceStats.icp.byEmirate.map((em, idx) => (
                         <div key={idx} className="bg-white border rounded p-3">
                            <label className="text-xs font-bold text-gray-500 block mb-1">{em.name}</label>
                            <input type="number" className="w-full text-sm font-mono border-b focus:border-primary outline-none" value={em.value} onChange={e => updateUaeWorkforce('icp', 'byEmirate', idx, 'value', e.target.value)} />
                         </div>
                      ))}
