                   {isFetchingAgreements ? <Loader2 className="animate-spin" size={16} /> : <Search size={16} />} Search Online
                 </Button>
               </div>
            </div>

             {data.bilateralAgreements.map((agreement, idx) => (
                <Card key={idx} className="relative p-4">
                   <button onClick={() => {const f = data.bilateralAgreements.filter((_, i) => i !== idx); setData({...data, bilateralAgreements: f})}} className="absolute top-2 right-2">X</button>
                   <Input value={agreement.title} onChange={e => {const a = [...data.bilateralAgreements]; a[idx].title = e.target.value; setData({...data, bilateralAgreements: a})}} placeholder="Title" className="font-bold mb-2" />
                   <Input value={agreement.date} onChange={e => {const a = [...data.bilateralAgreements]; a[idx].date = e.target.value; setData({...data, bilateralAgreements: a})}} placeholder="Date" className="text-sm mb-2" />
                   <Input value={agreement.summary} onChange={e => {const a = [...data.bilateralAgreements]; a[idx].summary = e.target.value; setData({...data, bilateralAgreements: a})}} placeholder="Summary" className="text-sm" />
                </Card>
             ))}
             <Button variant="outline" onClick={() => setData({...data, bilateralAgreements: [...data.bilateralAgreements, { title: '', date: '', status: 'Active', summary: '' }]})}>+ Add Agreement</Button>
          </div>
        );
      case 6: // Delegations (Redesigned Layout)
        const renderDelegationList = (type: 'uae' | 'partner', list: Delegate[]) => (
           <div className="bg-gray-50 rounded-xl p-8 border border-gray-200 shadow-sm">
              <div className="flex items-center justify-between mb-8 pb-6 border-b border-gray-200">
                 <div className="flex items-center gap-4">
                    {type === 'uae' ? (
                       <div className="w-12 h-12 rounded-full bg-white flex items-center justify-center shadow-sm border border-gray-200">
                         <img src="https://flagcdn.com/w40/ae.png" className="h-6 w-auto" alt="UAE" />
                       </div>
                    ) : (
                       <div className="w-12 h-12 rounded-full bg-blue-50 flex items-center justify-center shadow-sm border border-blue-100 text-blue-600">
                         <Globe size={24} />
                       </div>
                    )}
                    <div>
                      <h3 className="font-serif font-bold text-2xl text-gray-900 leading-tight">
                        {type === 'uae' ? 'UAE Delegation' : `${data.country || 'Partner'} Delegation`}
                      </h3>
                      <Input 
                         className="text-sm text-gray-500 font-medium uppercase tracking-wider mt-1 border-transparent bg-transparent px-0 py-0 h-auto focus:ring-0 focus:border-b border-gray-300 w-64"
                         placeholder={type === 'uae' ? "Ministry Officials" : "Counterpart Officials"}
                         defaultValue={type === 'uae' ? "Ministry Officials" : "Counterpart Officials"}
                      />
                    </div>
                 </div>

                 <Button 
                    size="default" 
                    variant="outline" 
                    onClick={() => addDelegate(type)}
                    className="hover:bg-primary hover:text-white hover:border-primary transition-all shadow-sm bg-white"
                 >
                    <UserPlus size={18} /> Add Member
                 </Button>
              </div>

              <div className="grid grid-cols-1 gap-6">
                 {list.length === 0 && (
                    <div className="py-12 flex flex-col items-center justify-center border-2 border-dashed border-gray-300 rounded-xl bg-white/50 text-gray-400 gap-3">
                       <Users size={40} className="opacity-20" />
                       <p className="text-base font-medium">No delegates added yet</p>
                    </div>
                 )}

                 {list.map((delegate, idx) => (
                    <div key={delegate.id} className="group relative bg-white border border-gray-200 rounded-xl p-6 shadow-sm hover:shadow-md transition-all duration-200 hover:border-primary/40">
                       <button className="absolute top-4 right-4 text-gray-300 hover:text-red-500 p-2 rounded-lg hover:bg-red-50 transition-all opacity-0 group-hover:opacity-100" onClick={() => removeDelegate(type, idx)}>
                         <X size={20} />
                       </button>

                       <div className="flex flex-col md:flex-row gap-6">
                          <div className="w-32 shrink-0">
                            <div className="aspect-[3/4] bg-gray-100 rounded-lg overflow-hidden relative border border-gray-200 shadow-inner group-focus-within:ring-2 ring-primary/20">
                               {delegate.imageUrl ? (
                                  <img src={delegate.imageUrl} alt={delegate.name} className="w-full h-full object-cover" />
                               ) : (
                                  <div className="w-full h-full flex flex-col items-center justify-center text-gray-300 gap-2 bg-gray-50">
                                    <ImageIcon size={32} />
                                    <span className="text-xs uppercase font-bold tracking-wider">No Photo</span>
                                  </div>
                               )}
                            </div>
                            <Input placeholder="Image URL..." value={delegate.imageUrl} className="mt-2 text-xs h-8 px-2 font-mono text-gray-500 bg-gray-50 border-gray-200 focus:bg-white w-full" onChange={e => { const l = type === 'uae' ? [...data.delegations.uae] : [...data.delegations.partner]; l[idx].imageUrl = e.target.value; setData({...data, delegations: {...data.delegations, [type]: l}}); }} />
                          </div>

                          <div className="flex-1 space-y-4 pt-1">
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <Input placeholder="Full Name" className="font-bold text-xl border-gray-200 focus:border-primary px-4 py-3 bg-gray-50/50 focus:bg-white transition-colors" value={delegate.name} onChange={e => { const l = type === 'uae' ? [...data.delegations.uae] : [...data.delegations.partner]; l[idx].name = e.target.value; setData({...data, delegations: {...data.delegations, [type]: l}}); }} />
                                <div className="flex gap-2">
                                  <Input placeholder="Official Title" className="text-base border-gray-200 px-4 py-3" value={delegate.title} onChange={e => { const l = type === 'uae' ? [...data.delegations.uae] : [...data.delegations.partner]; l[idx].title = e.target.value; setData({...data, delegations: {...data.delegations, [type]: l}}); }} />
                                </div>
                             </div>

                             <div className="relative">
                               <textarea className="w-full p-4 text-sm text-gray-600 bg-gray-50 border border-gray-200 rounded-lg focus:border-primary focus:ring-2 focus:ring-primary/10 outline-none transition-all resize-y min-h-[100px] leading-relaxed" placeholder="Professional biography..." value={delegate.bio} onChange={e => { const l = type === 'uae' ? [...data.delegations.uae] : [...data.delegations.partner]; l[idx].bio = e.target.value; setData({...data, delegations: {...data.delegations, [type]: l}}); }} />
                               <div className="absolute top-2 right-2">
                                 <Button size="sm" className="h-7 px-2 text-[10px] bg-accent/90 hover:bg-accent text-white shadow-none" onClick={() => handleEnrichDelegate(type, idx)} disabled={!delegate.name || enrichingDelegateId === delegate.id}>
                                   {enrichingDelegateId === delegate.id ? <Loader2 className="animate-spin" size={12} /> : "Auto-Fill Bio"}
                                 </Button>
                               </div>
                             </div>
                          </div>
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        );

        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
             <div className="flex flex-col gap-12">
                {renderDelegationList('uae', data.delegations.uae)}

                {/* Visual Separator */}
                <div className="flex items-center gap-4 py-4">
                  <div className="h-px bg-gray-300 flex-1"></div>
                  <div className="text-gray-400 font-serif italic text-sm">Counterpart Details</div>
                  <div className="h-px bg-gray-300 flex-1"></div>
                </div>

                {renderDelegationList('partner', data.delegations.partner)}
             </div>
          </div>
        );
      case 7: // Preview (Old Step 5, now 7)
        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
            <div className="bg-gray-100 p-8 rounded-xl border border-gray-200">
               <h2 className="font-serif text-2xl mb-4 text-center">{reportTitle}</h2>
               <div className="bg-white p-8 shadow-diplomatic max-w-2xl mx-auto space-y-6">
                  <div>
                    <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Workforce in UAE</h3>
                    <div className="grid grid-cols-2 gap-4 text-sm mb-4">
                       <div className="bg-gray-50 p-2 rounded">
                          <p className="text-xs text-gray-500">MOHRE: Total Private</p>
                          <p className="font-bold">{data.uaeWorkforceStats.mohre.totalPrivate.value}</p>
                       </div>
                        <div className="bg-gray-50 p-2 rounded">
                          <p className="text-xs text-gray-500">MOHRE: Total Domestic</p>
                          <p className="font-bold">{data.uaeWorkforceStats.mohre.totalDomestic.value}</p>
                       </div>
                    </div>
                  </div>
                  <div><h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Interactions & News</h3> <p className="text-sm">{data.recentInteractions.length} Interactions, {data.relatedNews.length} News items.</p></div>
                  <div>
                    <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Delegations</h3>
                    <div className="text-sm">
                      <p className="font-bold">UAE:</p> <ul className="list-disc ml-5 mb-2">{data.delegations.uae.map(d => <li key={d.id}>{d.name}</li>)}</ul>
                      <p className="font-bold">Partner:</p> <ul className="list-disc ml-5">{data.delegations.partner.map(d => <li key={d.id}>{d.name}</li>)}</ul>
                    </div>
                  </div>
               </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div className="max-w-5xl mx-auto pb-12">
      <div className="mb-8">
        <Input 
          placeholder="Report Title (e.g. Bilateral Meeting India 2024)"
          className="text-2xl font-serif font-bold bg-transparent border-transparent px-0 focus:ring-0 focus:border-primary placeholder:text-gray-300"
          value={reportTitle}
          onChange={(e) => setReportTitle(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'}
                ${idx < currentStep ? 'text-primary font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button variant="ghost" onClick={() => setCurrentStep(Math.max(0, currentStep - 1))} disabled={currentStep === 0}>
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} /> {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}><Save size={16} /> {t('save')}</Button>
              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>{t('next')} <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} /></Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">{t('finish')} <CheckCircle size={16} /></Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export type Language = 'en' | 'ar';
export type ReportStatus = 'draft' | 'completed';
export type UserRole = 'admin' | 'user';

export interface UserProfile {
  id: string;
