             <div className="flex flex-col gap-12">
                {renderDelegationList('uae', data.delegations.uae)}

                {/* Visual Separator */}
                <div className="flex items-center gap-4 py-4">
                  <div className="h-px bg-gray-300 flex-1"></div>
                  <div className="text-gray-400 font-serif italic text-sm">Counterpart Details</div>
                  <div className="h-px bg-gray-300 flex-1"></div>
                </div>

                {renderDelegationList('partner', data.delegations.partner)}
             </div>
          </div>
        );
      case 7: // Preview (Old Step 5, now 7)
        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
            <div className="bg-gray-100 p-8 rounded-xl border border-gray-200">
               <h2 className="font-serif text-2xl mb-4 text-center">{reportTitle}</h2>
               <div className="bg-white p-8 shadow-diplomatic max-w-2xl mx-auto space-y-6">
                  <div>
                    <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Workforce in UAE</h3>
                    <div className="grid grid-cols-2 gap-4 text-sm mb-4">
                       <div className="bg-gray-50 p-2 rounded">
                          <p className="text-xs text-gray-500">MOHRE: Total Private</p>
                          <p className="font-bold">{data.uaeWorkforceStats.mohre.totalPrivate.value}</p>
                       </div>
                        <div className="bg-gray-50 p-2 rounded">
                          <p className="text-xs text-gray-500">MOHRE: Total Domestic</p>
                          <p className="font-bold">{data.uaeWorkforceStats.mohre.totalDomestic.value}</p>
                       </div>
                    </div>
                  </div>
                  <div><h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Interactions & News</h3> <p className="text-sm">{data.recentInteractions.length} Interactions, {data.relatedNews.length} News items.</p></div>
                  <div>
                    <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Delegations</h3>
                    <div className="text-sm">
                      <p className="font-bold">UAE:</p> <ul className="list-disc ml-5 mb-2">{data.delegations.uae.map(d => <li key={d.id}>{d.name}</li>)}</ul>
                      <p className="font-bold">Partner:</p> <ul className="list-disc ml-5">{data.delegations.partner.map(d => <li key={d.id}>{d.name}</li>)}</ul>
                    </div>
                  </div>
               </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div className="max-w-5xl mx-auto pb-12">
      <div className="mb-8">
        <Input 
          placeholder="Report Title (e.g. Bilateral Meeting India 2024)"
          className="text-2xl font-serif font-bold bg-transparent border-transparent px-0 focus:ring-0 focus:border-primary placeholder:text-gray-300"
          value={reportTitle}
          onChange={(e) => setReportTitle(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 hover:bg-gray-100'}
                ${idx < currentStep ? 'text-primary font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button variant="ghost" onClick={() => setCurrentStep(Math.max(0, currentStep - 1))} disabled={currentStep === 0}>
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} /> {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}><Save size={16} /> {t('save')}</Button>
              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>{t('next')} <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} /></Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">{t('finish')} <CheckCircle size={16} /></Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export type Language = 'en' | 'ar';
export type ReportStatus = 'draft' | 'completed';
export type UserRole = 'admin' | 'user';

export interface UserProfile {
  id: string;
  email: string;
  fullName: string;
  role: UserRole;
  avatarUrl?: string;
}

export interface Delegate {
  id: string;
  name: string;
  title: string;
  imageUrl: string;
  bio: string;
}

export interface DateValue {
  value: string;
  date: string; // "As of..."
}

export interface LabelValue {
  name: string;
  value: number;
}

export interface RecentInteraction {
  id: string;
  title: string;
  date: string;
  type: string; // e.g., "Visit", "Phone Call", "Meeting"
  details: string; // Summary of the interaction
}

export interface PointOfDiscussion {
  id: string;
  title: string;
  content: string;
}

export interface NewsItem {
  id: string;
  title: string;
  source: string;
  date: string;
  summary: string;
}

export interface UaeWorkforceData {
  mohre: {
    totalPrivate: DateValue;
    totalDomestic: DateValue;
    byEmirate: LabelValue[]; // Abu Dhabi, Dubai, etc.
    bySector: LabelValue[];
  };
  icp: {
    byEmirate: LabelValue[];
    bySector: LabelValue[];
  };
  custom: Array<{
    id: string;
    label: string;
    value: string;
    date: string;
    isTotal: boolean; // For the mandatory "Total Workers in UAE"
  }>;
}

// Complex Report Structure
export interface ReportData {
  reportDate?: string; // Date of the report/meeting

  // Section 1: Country Profile & Diplomacy
  country: string;
  capital: string;
  officialLanguage: string;
  population: string;
  currency: string;
  gdp: string; // Generic GDP field
  hdi: string; // Human Development Index
  directFlight: boolean; // Yes/No
  uaeEmbassyLocation: string; // Location in that country
  foreignEmbassyLocation: string; // City in UAE

  // Section 2: Workforce in UAE (NEW)
  uaeWorkforceStats: UaeWorkforceData;

  // Section 3: Partner Country Workforce & Economic Indicators
  averageWage: string;
  minimumWage: string;
  workforceStats: {
    totalWorkforce: string;
    participationMale: number;
    participationFemale: number;
    migrationDestinations: Array<{ country: string; count: string }>; 
    topSectors: Array<{ name: string; value: number }>; 
    availableSkills: string[]; 
  };

  // Section 4: Economy & Education
  economicStats: {
    inflation: string;
    gdp: string;
    totalExportsToUAE: string;
    totalImportsFromUAE: string;
    topExportProducts: string[];
    topImportProducts: string[];
    mainEconomicPartners: string[];
    tipRank: string; // Trafficking in Persons Rank
    remittancesFromUAE: string; // Specific to UAE
    remittancesGlobal: string; // NEW: Total global remittances
    customStats: Array<{ id: string; label: string; value: string }>;
  };

  educationStats: {
    topUniversities: string[];
    primaryEnrollment: string;
    higherEducationEnrollment: string;
  };

  // Section 5: Interactions & News (NEW)
  recentInteractions: RecentInteraction[];
  pointsOfDiscussion: PointOfDiscussion[];
  relatedNews: NewsItem[];

  // Flexible Content
  customSections: Array<{
    id: string;
    title: string;
    content: string;
  }>;

  // Section 6: Relations
  bilateralAgreements: Array<{
    title: string;
    date: string;
    status: 'Active' | 'Pending' | 'Expired';
    summary: string;
  }>;

  keyIssues: string[];
  recommendations: string[];

  // Section 7: Delegations
  delegations: {
    uae: Delegate[];
    partner: Delegate[];
  };
}

export interface Report {
  id: string;
  userId: string;
  title: string;
  status: ReportStatus;
  updatedAt: string;
  data: ReportData;
}

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  timestamp: string;
  details: string;
}

