                 <Input label="Higher Education Enrollment" value={data.educationStats?.higherEducationEnrollment} onChange={e => setData({...data, educationStats: {...data.educationStats, higherEducationEnrollment: e.target.value}})} placeholder="e.g. 35%" />
               </div>
               <div>
                  <label className="text-sm font-semibold text-foreground/80 block mb-2">Top 5 Universities</label>
                  <div className="space-y-2">
                    {(data.educationStats?.topUniversities || []).map((uni, i) => (
                      <div key={i} className="flex gap-2">
                         <span className="bg-gray-100 px-3 py-2 rounded-md font-mono text-sm text-gray-500 w-8 text-center">{i+1}</span>
                         <Input value={uni} onChange={e => { const newUnis = [...(data.educationStats.topUniversities || [])]; newUnis[i] = e.target.value; setData({...data, educationStats: {...data.educationStats, topUniversities: newUnis}}); }} className="flex-1" />
                         <button onClick={() => { const newUnis = data.educationStats.topUniversities.filter((_, idx) => idx !== i); setData({...data, educationStats: {...data.educationStats, topUniversities: newUnis}}); }} className="text-gray-400 hover:text-red-500 p-2"><X size={18} /></button>
                      </div>
                    ))}
                    {(data.educationStats?.topUniversities?.length || 0) < 5 && (
                      <Button variant="ghost" onClick={() => { setData({...data, educationStats: { ...data.educationStats, topUniversities: [...(data.educationStats.topUniversities || []), ''] }}); }} className="w-full border-dashed border-2 border-gray-200">+ Add University</Button>
                    )}
                  </div>
               </div>
            </Card>

            <div>
               <div className="flex justify-between items-center mb-4">
                 <h4 className="font-bold text-lg text-primary-dark">Additional Information</h4>
                 <Button variant="outline" size="sm" onClick={() => { setData({ ...data, customSections: [...(data.customSections || []), { id: uuidv4(), title: '', content: '' }] }) }}><Plus size={16} /> Add Custom Section</Button>
               </div>
               <div className="space-y-6">
                 {(data.customSections || []).map((section, i) => (
                   <Card key={section.id} className="relative group">
                     <button className="absolute top-4 right-4 text-gray-400 hover:text-red-500 p-1" onClick={() => { const newSections = data.customSections.filter(s => s.id !== section.id); setData({...data, customSections: newSections}); }}><X size={20} /></button>
                     <div className="space-y-4 pr-8">
                       <Input placeholder="Section Title" value={section.title} className="font-bold text-lg border-transparent focus:border-gray-300 px-0" onChange={e => { const newSections = [...data.customSections]; newSections[i].title = e.target.value; setData({...data, customSections: newSections}); }} />
                       <textarea className="w-full p-3 rounded-lg border border-gray-300 focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none min-h-[100px]" placeholder="Content..." value={section.content} onChange={e => { const newSections = [...data.customSections]; newSections[i].content = e.target.value; setData({...data, customSections: newSections}); }} />
                     </div>
                   </Card>
                 ))}
               </div>
            </div>
          </div>
         );
      case 4: // NEW: Recent Interactions & News
        return (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
