             <Button variant="outline" onClick={() => setData({...data, bilateralAgreements: [...data.bilateralAgreements, { title: '', date: '', status: 'Active', summary: '' }]})}>+ Add Agreement</Button>
          </div>
        );
      case 6: // Delegations (Redesigned Layout)
        const renderDelegationList = (type: 'uae' | 'partner', list: Delegate[]) => (
           <div className="bg-gray-50 rounded-xl p-8 border border-gray-200 shadow-sm">
              <div className="flex items-center justify-between mb-8 pb-6 border-b border-gray-200">
                 <div className="flex items-center gap-4">
                    {type === 'uae' ? (
                       <div className="w-12 h-12 rounded-full bg-white flex items-center justify-center shadow-sm border border-gray-200">
                         <img src="https://flagcdn.com/w40/ae.png" className="h-6 w-auto" alt="UAE" />
                       </div>
                    ) : (
                       <div className="w-12 h-12 rounded-full bg-blue-50 flex items-center justify-center shadow-sm border border-blue-100 text-blue-600">
                         <Globe size={24} />
                       </div>
                    )}
                    <div>
                      <h3 className="font-serif font-bold text-2xl text-gray-900 leading-tight">
                        {type === 'uae' ? 'UAE Delegation' : `${data.country || 'Partner'} Delegation`}
                      </h3>
                      <Input 
                         className="text-sm text-gray-500 font-medium uppercase tracking-wider mt-1 border-transparent bg-transparent px-0 py-0 h-auto focus:ring-0 focus:border-b border-gray-300 w-64"
                         placeholder={type === 'uae' ? "Ministry Officials" : "Counterpart Officials"}
                         defaultValue={type === 'uae' ? "Ministry Officials" : "Counterpart Officials"}
                      />
                    </div>
                 </div>

                 <Button 
                    size="default" 
                    variant="outline" 
                    onClick={() => addDelegate(type)}
                    className="hover:bg-primary hover:text-white hover:border-primary transition-all shadow-sm bg-white"
