                        onError={(e) => e.currentTarget.style.display = 'none'}
                       />
                       {report.data.country}
                    </td>
                    <td className="p-4 text-sm font-medium">{report.title}</td>
                    <td className="p-4 text-sm text-gray-500">
                      {report.userId === 'u-1' ? 'Ahmed Al-Mansouri' : 'Sarah Khan'}
