                            className="p-2 hover:bg-gray-100 rounded-lg text-gray-600 transition-colors"
                            title="Export PDF"
                          >
                            <Printer size={16} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

