import { Report, AuditLog, UserProfile } from '../types';
import { MOCK_REPORTS, MOCK_AUDIT_LOGS } from '../constants';

// Simulating API Latency
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

let reportsStore = [...MOCK_REPORTS];
let logsStore = [...MOCK_AUDIT_LOGS];
// Mock Users List
let usersStore: UserProfile[] = [
  { id: 'u-1', fullName: 'Ahmed Al-Mansouri', email: 'official@mohre.gov.ae', role: 'admin', avatarUrl: 'https://ui-avatars.com/api/?name=Ahmed+Al-Mansouri&background=0D8ABC&color=fff' },
  { id: 'u-2', fullName: 'Sarah Khan', email: 'sarah.k@mohre.gov.ae', role: 'user', avatarUrl: 'https://ui-avatars.com/api/?name=Sarah+Khan&background=eb4034&color=fff' },
  { id: 'u-3', fullName: 'John Doe', email: 'john.d@mohre.gov.ae', role: 'user', avatarUrl: 'https://ui-avatars.com/api/?name=John+Doe&background=333&color=fff' },
];

export const MockService = {
  getReports: async (): Promise<Report[]> => {
    await delay(600);
    // Return sorted by date descending
    return [...reportsStore].sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
  },

  getReportById: async (id: string): Promise<Report | undefined> => {
    await delay(400);
    return reportsStore.find(r => r.id === id);
  },

  saveReport: async (report: Report): Promise<void> => {
    await delay(800);
    const index = reportsStore.findIndex(r => r.id === report.id);
    if (index >= 0) {
      reportsStore[index] = report;
    } else {
      reportsStore.push(report);
    }
  },

  deleteReport: async (id: string): Promise<void> => {
    await delay(500);
    reportsStore = reportsStore.filter(r => r.id !== id);
  },

  getAuditLogs: async (): Promise<AuditLog[]> => {
    await delay(500);
    return [...logsStore];
  },

  getUsers: async (): Promise<UserProfile[]> => {
    await delay(500);
    return [...usersStore];
  },

  addUser: async (user: UserProfile): Promise<void> => {
    await delay(500);
    usersStore.push(user);
  },

  deleteUser: async (id: string): Promise<void> => {
    await delay(500);
    usersStore = usersStore.filter(u => u.id !== id);
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';

type Theme = 'light' | 'dark';

interface ThemeContextType {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [theme, setTheme] = useState<Theme>(() => {
    const stored = localStorage.getItem('theme');
    return (stored as Theme) || 'light';
  });

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'light' ? 'dark' : 'light'));
  };

  return (
    <ThemeContext.Provider value={{ theme, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) throw new Error('useTheme must be used within a ThemeProvider');
  return context;
};

