import React, { useEffect, useState } from 'react';
import { MockService } from '../services/mockService';
import { UserProfile, UserRole } from '../types';
import { Button, Card, Badge, Input } from '../components/ui/LayoutComponents';
import { Trash2, UserPlus, ShieldAlert, User, Mail, X, CheckCircle, Key } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

export default function AdminUsers() {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // New User Form State
  const [newUser, setNewUser] = useState({
    fullName: '',
    email: '',
    role: 'user' as UserRole,
    password: ''
  });

  const fetchUsers = async () => {
    setLoading(true);
    const data = await MockService.getUsers();
    setUsers(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleRemoveUser = async (id: string) => {
    if (window.confirm('Are you sure you want to remove this user access?')) {
      // Optimistic update
      setUsers(prev => prev.filter(u => u.id !== id));
      try {
        await MockService.deleteUser(id);
      } catch (e) {
        alert("Failed to remove user");
        fetchUsers(); // Revert on failure
      }
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.fullName || !newUser.email || !newUser.password) return;

    const user: UserProfile = {
      id: `u-${uuidv4().slice(0, 8)}`,
      fullName: newUser.fullName,
      email: newUser.email,
      role: newUser.role,
      avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(newUser.fullName)}&background=random&color=fff`,
      password: newUser.password
    };

    // Optimistic update
    setUsers(prev => [...prev, user]);
    setIsModalOpen(false);
    setNewUser({ fullName: '', email: '', role: 'user', password: '' });

    await MockService.addUser(user);
    // Silent fetch to ensure consistency
    const data = await MockService.getUsers();
    setUsers(data);
