}

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useLanguage } from '../context/LanguageContext';
import { MockService } from '../services/mockService';
import { Report } from '../types';
import { Card, Button, Badge } from '../components/ui/LayoutComponents';
import { Search, Plus, Edit3, Trash2, Printer, FileText, Lock, RefreshCw } from 'lucide-react';
import { format } from 'date-fns';

export default function ReportsList() {
  const { user } = useAuth();
  const { t } = useLanguage();
  const navigate = useNavigate();
  const [reports, setReports] = useState<Report[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const fetchReports = async () => {
    setLoading(true);
    const data = await MockService.getReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchReports();
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this report? This action cannot be undone.')) {
      setDeletingId(id);
      try {
        await MockService.deleteReport(id);
        // Force refresh from service to ensure sync
        await fetchReports();
      } catch (error) {
        console.error("Delete failed", error);
        alert("Failed to delete report.");
      } finally {
        setDeletingId(null);
      }
    }
  };

  const handlePrint = (id: string) => {
    // 1. Get the current full URL (e.g. http://localhost:8080/#/reports)
    // 2. We want to construct http://localhost:8080/#/print/123
    // 3. Since we use HashRouter, we just replace the part after #

    const baseUrl = window.location.href.split('#')[0];
    const printUrl = `${baseUrl}#/print/${id}`;

    console.log("Navigating to Print URL:", printUrl);
    window.open(printUrl, '_blank');
  };

  const filteredReports = reports.filter(r => 
    r.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.data.country.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-serif font-bold text-primary-dark dark:text-white">
            {t('reports')}
          </h1>
          <p className="text-muted-foreground mt-1 dark:text-gray-400">
            Manage and generate bilateral intelligence reports.
          </p>
        </div>
        <Button onClick={() => navigate('/wizard')}>
          <Plus size={20} />
          {t('createNew')}
        </Button>
      </div>

      <div className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <Search className="text-gray-400" size={20} />
        <input 
          placeholder="Search reports by title or country..." 
          className="flex-1 outline-none text-sm bg-transparent dark:text-white"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <button onClick={fetchReports} className="text-gray-400 hover:text-primary transition-colors" title="Refresh">
          <RefreshCw size={18} />
        </button>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-card overflow-hidden border border-gray-100 dark:border-gray-700">
        {loading ? (
          <div className="p-12 text-center text-gray-500 flex flex-col items-center">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mb-2"></div>
             Loading reports...
          </div>
        ) : filteredReports.length === 0 ? (
          <div className="p-12 text-center text-gray-500 dark:text-gray-400">
            <FileText size={48} className="mx-auto text-gray-300 dark:text-gray-600 mb-4" />
            <p>No reports found.</p>
          </div>
        ) : (
          <table className="w-full text-left">
            <thead className="bg-secondary/50 dark:bg-gray-700/50 border-b dark:border-gray-700">
              <tr>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">{t('country')}</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Report Title</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Created By</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Last Modified</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Status</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-gray-700">
              {filteredReports.map((report) => {
                // Permission Logic
                // Admin sees all, Owner sees own
                const isOwner = user?.id === report.userId;
                const isAdmin = user?.role === 'admin';
                const canEdit = isAdmin || isOwner;
                const isDeleting = deletingId === report.id;

                return (
                  <tr key={report.id} className={`hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors group ${isDeleting ? 'opacity-50 pointer-events-none' : ''}`}>
                    <td className="p-4 font-medium text-primary dark:text-primary-light flex items-center gap-3">
                       <img 
                        src={`https://flagcdn.com/w40/${report.data.country === 'Philippines' ? 'ph' : report.data.country === 'India' ? 'in' : 'ae'}.png`} 
                        className="w-6 h-auto shadow-sm rounded-sm"
                        alt="flag"
                        onError={(e) => e.currentTarget.style.display = 'none'}
                       />
                       {report.data.country}
                    </td>
                    <td className="p-4 text-sm font-medium dark:text-gray-200">{report.title}</td>
                    <td className="p-4 text-sm text-gray-500 dark:text-gray-400">
                      {report.userId === 'u-admin' ? 'Administrator' : 'User'}
                    </td>
                    <td className="p-4 text-sm text-gray-500 dark:text-gray-400">
                      {format(new Date(report.updatedAt), 'MMM dd, yyyy')}
                    </td>
                    <td className="p-4">
                      <Badge color={report.status === 'completed' ? 'green' : 'yellow'}>
                        {t(report.status)}
                      </Badge>
                    </td>
                    <td className="p-4 text-right">
                      <div className="flex items-center justify-end gap-2">
                         {canEdit ? (
                           <>
                            <button 
                              onClick={() => navigate(`/wizard/${report.id}`)}
                              className="p-2 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400 transition-colors"
                              title="Edit Report"
                            >
                              <Edit3 size={16} />
                            </button>
                            <button 
                              onClick={() => handleDelete(report.id)}
                              className="p-2 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg text-red-500 transition-colors"
                              title="Delete Report"
                            >
                              {isDeleting ? <div className="w-4 h-4 border-2 border-red-500 border-t-transparent rounded-full animate-spin"></div> : <Trash2 size={16} />}
                            </button>
                           </>
                         ) : (
                           <span className="text-gray-300 dark:text-gray-600 p-2 cursor-not-allowed" title="View Only">
                             <Lock size={16} />
                           </span>
                         )}

                        {(canEdit || isAdmin) && (
                          <button 
                            onClick={() => handlePrint(report.id)}
                            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-600 dark:text-gray-300 transition-colors"
                            title="Export PDF"
                          >
                            <Printer size={16} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';
import { MockService } from '../services/mockService';
import { Card, Button, Input } from '../components/ui/LayoutComponents';
import { Moon, Sun, User, Bell, Lock, Check, AlertCircle } from 'lucide-react';

export default function Settings() {
  const { user } = useAuth();
  const { theme, toggleTheme } = useTheme();

  // Password State
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [passMsg, setPassMsg] = useState<{type: 'success' | 'error', text: string} | null>(null);

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setPassMsg(null);

    if (newPass.length < 4) {
      setPassMsg({ type: 'error', text: 'Password must be at least 4 characters.' });
      return;
    }
    if (newPass !== confirmPass) {
      setPassMsg({ type: 'error', text: 'Passwords do not match.' });
      return;
    }

    if (user) {
      await MockService.updatePassword(user.id, newPass);
      setPassMsg({ type: 'success', text: 'Password updated successfully.' });
      setNewPass('');
      setConfirmPass('');
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 max-w-4xl mx-auto">
      <div>
        <h1 className="text-3xl font-serif font-bold text-primary-dark dark:text-primary-foreground">
          Settings
        </h1>
        <p className="text-muted-foreground mt-1">
          Manage your account preferences and application appearance.
        </p>
      </div>

      {/* Profile Section */}
      <Card className="dark:bg-secondary dark:border-gray-800">
        <h2 className="text-xl font-bold mb-4 flex items-center gap-2 dark:text-white">
          <User size={20} className="text-primary dark:text-accent" /> Profile Information
        </h2>
        <div className="flex items-start gap-6">
           <img 
            src={user?.avatarUrl} 
            className="w-20 h-20 rounded-full border-4 border-gray-100 dark:border-gray-700 shadow-md" 
            alt="Profile" 
           />
           <div className="space-y-1">
             <h3 className="text-lg font-bold dark:text-white">{user?.fullName}</h3>
             <p className="text-muted-foreground">{user?.email}</p>
             <span className="inline-block mt-2 px-3 py-1 bg-primary/10 text-primary dark:text-accent rounded-full text-xs font-bold uppercase tracking-wide">
               {user?.role}
             </span>
           </div>
        </div>
      </Card>

      {/* Security Section (Change Password) */}
      <Card className="dark:bg-secondary dark:border-gray-800">
         <h2 className="text-xl font-bold mb-4 flex items-center gap-2 dark:text-white">
          <Lock size={20} className="text-primary dark:text-accent" /> Security
        </h2>
        <form onSubmit={handlePasswordChange} className="max-w-md space-y-4">
           {passMsg && (
             <div className={`p-3 rounded-lg text-sm flex items-center gap-2 ${passMsg.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                {passMsg.type === 'success' ? <Check size={16} /> : <AlertCircle size={16} />}
                {passMsg.text}
             </div>
           )}
           <Input 
             type="password" 
             label="New Password" 
             value={newPass}
             onChange={e => setNewPass(e.target.value)}
             placeholder="Enter new password"
           />
           <Input 
             type="password" 
             label="Confirm Password" 
             value={confirmPass}
             onChange={e => setConfirmPass(e.target.value)}
             placeholder="Confirm new password"
           />
           <Button type="submit" disabled={!newPass}>Update Password</Button>
        </form>
      </Card>

      {/* Appearance Section */}
      <Card className="dark:bg-secondary dark:border-gray-800">
        <h2 className="text-xl font-bold mb-6 flex items-center gap-2 dark:text-white">
          <Sun size={20} className="text-primary dark:text-accent" /> Appearance
        </h2>

        <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-gray-100 dark:border-gray-700">
          <div>
            <h3 className="font-medium text-gray-900 dark:text-white">Application Theme</h3>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Customize how the application looks.
            </p>
          </div>

          <div className="flex bg-gray-200 dark:bg-gray-700 p-1 rounded-lg">
             <button 
               onClick={() => theme === 'dark' && toggleTheme()}
               className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${theme === 'light' ? 'bg-white shadow text-gray-900' : 'text-gray-500 dark:text-gray-400 hover:text-gray-900'}`}
             >
               <Sun size={16} /> Light
             </button>
             <button 
               onClick={() => theme === 'light' && toggleTheme()}
               className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${theme === 'dark' ? 'bg-gray-600 shadow text-white' : 'text-gray-500 dark:text-gray-400 hover:text-gray-900'}`}
             >
               <Moon size={16} /> Dark
             </button>
          </div>
        </div>
      </Card>
    </div>
  );
}

