                        <div className="bg-gray-50 p-2 rounded">
                          <p className="text-xs text-gray-500">MOHRE: Total Domestic</p>
                          <p className="font-bold">{data.uaeWorkforceStats.mohre.totalDomestic.value}</p>
                       </div>
                    </div>
                  </div>
                  <div><h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Interactions & News</h3> <p className="text-sm">{data.recentInteractions.length} Interactions, {data.relatedNews.length} News items.</p></div>
                  <div>
                    <h3 className="font-serif text-lg text-primary mb-2 border-b-2 border-accent w-fit">Delegations</h3>
                    <div className="text-sm">
                      <p className="font-bold">UAE:</p> <ul className="list-disc ml-5 mb-2">{data.delegations.uae.map(d => <li key={d.id}>{d.name}</li>)}</ul>
                      <p className="font-bold">Partner:</p> <ul className="list-disc ml-5">{data.delegations.partner.map(d => <li key={d.id}>{d.name}</li>)}</ul>
                    </div>
                  </div>
               </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div className="max-w-5xl mx-auto pb-12">
      <div className="mb-8">
        {/* Title input moved inside Profile Step, keeping header minimal */}
        <h1 className="text-2xl font-serif font-bold text-gray-800 dark:text-white">
           {currentStep === 0 ? "Create New Report" : (reportTitle || "Untitled Report")}
        </h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="space-y-2">
          {STEPS.map((step, idx) => (
            <button
              key={step.id}
              disabled={idx > currentStep}
              onClick={() => setCurrentStep(idx)}
              className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all text-left
                ${idx === currentStep ? 'bg-primary text-white shadow-md' : 'text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'}
                ${idx < currentStep ? 'text-primary dark:text-primary-light font-medium' : ''}
              `}
            >
              <step.icon size={18} />
              <span className="text-sm font-medium">{step.label}</span>
              {idx < currentStep && <CheckCircle size={14} className="ml-auto opacity-50" />}
            </button>
          ))}
        </div>

        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[400px]">
            {renderStep()}
          </Card>

          <div className="flex justify-between">
            <Button variant="ghost" onClick={() => setCurrentStep(Math.max(0, currentStep - 1))} disabled={currentStep === 0}>
              <ArrowLeft size={16} className={language === 'ar' ? 'rotate-180' : ''} /> {t('back')}
            </Button>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => handleSave('draft')}><Save size={16} /> {t('save')}</Button>
              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)}>{t('next')} <ArrowRight size={16} className={language === 'ar' ? 'rotate-180' : ''} /></Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700">{t('finish')} <CheckCircle size={16} /></Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useLanguage } from '../context/LanguageContext';
import { MockService } from '../services/mockService';
import { Report } from '../types';
import { Card, Button, Badge } from '../components/ui/LayoutComponents';
import { Search, Plus, Edit3, Trash2, Printer, FileText, Lock, RefreshCw } from 'lucide-react';
import { format } from 'date-fns';

export default function ReportsList() {
  const { user } = useAuth();
  const { t } = useLanguage();
  const navigate = useNavigate();
  const [reports, setReports] = useState<Report[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const fetchReports = async () => {
    setLoading(true);
    const data = await MockService.getReports();
    setReports(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchReports();
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this report? This action cannot be undone.')) {
      setDeletingId(id);
      try {
        await MockService.deleteReport(id);
        // Force refresh from service to ensure sync
        await fetchReports();
      } catch (error) {
        console.error("Delete failed", error);
        alert("Failed to delete report.");
      } finally {
        setDeletingId(null);
      }
    }
  };

  const handlePrint = (id: string) => {
    // Robust URL construction for any hosting environment (Root, Subfolder, Docker, etc.)
    // We utilize the current location to preserve protocol, domain, port, and sub-paths.
    const href = window.location.href;
    const hashIndex = href.indexOf('#');

    // Extract base URL (everything before the hash)
    let baseUrl = hashIndex !== -1 ? href.substring(0, hashIndex) : href;

    // Ensure we don't end up with double slashes if the base ends with one
    if (baseUrl.endsWith('/')) {
      baseUrl = baseUrl.slice(0, -1);
    }

    // Construct the print view URL
    const printUrl = `${baseUrl}/#/print/${id}`;

    window.open(printUrl, '_blank');
  };

  const filteredReports = reports.filter(r => 
    r.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.data.country.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-serif font-bold text-primary-dark dark:text-white">
            {t('reports')}
          </h1>
          <p className="text-muted-foreground mt-1 dark:text-gray-400">
            Manage and generate bilateral intelligence reports.
          </p>
        </div>
        <Button onClick={() => navigate('/wizard')}>
          <Plus size={20} />
          {t('createNew')}
        </Button>
      </div>

      <div className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <Search className="text-gray-400" size={20} />
        <input 
          placeholder="Search reports by title or country..." 
          className="flex-1 outline-none text-sm bg-transparent dark:text-white"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <button onClick={fetchReports} className="text-gray-400 hover:text-primary transition-colors" title="Refresh">
          <RefreshCw size={18} />
        </button>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-card overflow-hidden border border-gray-100 dark:border-gray-700">
        {loading ? (
          <div className="p-12 text-center text-gray-500 flex flex-col items-center">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mb-2"></div>
             Loading reports...
          </div>
        ) : filteredReports.length === 0 ? (
          <div className="p-12 text-center text-gray-500 dark:text-gray-400">
            <FileText size={48} className="mx-auto text-gray-300 dark:text-gray-600 mb-4" />
            <p>No reports found.</p>
          </div>
        ) : (
          <table className="w-full text-left">
            <thead className="bg-secondary/50 dark:bg-gray-700/50 border-b dark:border-gray-700">
              <tr>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">{t('country')}</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Report Title</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Created By</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Last Modified</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Status</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-gray-700">
              {filteredReports.map((report) => {
                // Permission Logic
                const isOwner = user?.id === report.userId;
                const isAdmin = user?.role === 'admin';
                const canEdit = isAdmin || isOwner;
                const isDeleting = deletingId === report.id;

                return (
                  <tr key={report.id} className={`hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors group ${isDeleting ? 'opacity-50 pointer-events-none' : ''}`}>
                    <td className="p-4 font-medium text-primary dark:text-primary-light flex items-center gap-3">
                       <img 
                        src={`https://flagcdn.com/w40/${report.data.country === 'Philippines' ? 'ph' : report.data.country === 'India' ? 'in' : 'ae'}.png`} 
                        className="w-6 h-auto shadow-sm rounded-sm"
                        alt="flag"
                        onError={(e) => e.currentTarget.style.display = 'none'}
                       />
                       {report.data.country}
                    </td>
                    <td className="p-4 text-sm font-medium dark:text-gray-200">{report.title}</td>
                    <td className="p-4 text-sm text-gray-500 dark:text-gray-400">
                      {report.userId === 'u-1' ? 'Ahmed Al-Mansouri' : 'Sarah Khan'}
                      {isOwner && <span className="ml-2 text-xs bg-blue-100 dark:bg-blue-900 text-blue-700 dark:text-blue-200 px-1.5 py-0.5 rounded">You</span>}
                    </td>
                    <td className="p-4 text-sm text-gray-500 dark:text-gray-400">
                      {format(new Date(report.updatedAt), 'MMM dd, yyyy')}
                    </td>
                    <td className="p-4">
                      <Badge color={report.status === 'completed' ? 'green' : 'yellow'}>
                        {t(report.status)}
                      </Badge>
                    </td>
                    <td className="p-4 text-right">
                      <div className="flex items-center justify-end gap-2">
                         {canEdit ? (
                           <>
                            <button 
                              onClick={() => navigate(`/wizard/${report.id}`)}
                              className="p-2 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400 transition-colors"
                              title="Edit Report"
                            >
                              <Edit3 size={16} />
                            </button>
                            <button 
                              onClick={() => handleDelete(report.id)}
                              className="p-2 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg text-red-500 transition-colors"
                              title="Delete Report"
                            >
                              {isDeleting ? <div className="w-4 h-4 border-2 border-red-500 border-t-transparent rounded-full animate-spin"></div> : <Trash2 size={16} />}
                            </button>
                           </>
                         ) : (
                           <span className="text-gray-300 dark:text-gray-600 p-2 cursor-not-allowed" title="View Only">
                             <Lock size={16} />
                           </span>
                         )}

                        {(canEdit || isAdmin) && (
                          <button 
                            onClick={() => handlePrint(report.id)}
                            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-600 dark:text-gray-300 transition-colors"
                            title="Export PDF"
                          >
                            <Printer size={16} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

