        <h2 className={`font-serif font-bold text-primary-dark leading-none ${compact ? 'text-xl' : 'text-2xl'}`}>
          {title}
        </h2>
        {subtitle && (
          <p className="text-[10px] font-extrabold uppercase tracking-widest text-accent mt-1">
            {subtitle}
          </p>
        )}
      </div>
    </div>
  </div>
);

/* ===============================
   KPI COMPONENT
================================ */
export const KPI = ({
  icon: Icon,
  label,
  value,
  sub,
  chip,
  tone = "info",
}: {
  icon: any;
  label: string;
  value: string | number;
  sub?: string;
  chip?: string;
  tone?: "ok" | "warn" | "info" | "restrict";
}) => (
  <div className="kpi-card avoid-break h-full flex flex-col justify-center">
    <div className="kpi-row">
      <div className="kpi-icon shrink-0 mt-0.5">
        <Icon size={16} className="text-primary" />
      </div>

      <div className="flex-1 min-w-0">
        <div className="flex justify-between items-start mb-0.5">
          <p className="kpi-label pr-1 leading-tight">{label}</p>
          {chip && (
            <span
              className={`kpi-chip shrink-0 ml-1 ${
                tone === "ok"
                  ? "chip-ok"
                  : tone === "warn"
                  ? "chip-warn"
                  : tone === "restrict"
                  ? "chip-restrict"
                  : "chip-info"
              }`}
            >
              {chip}
            </span>
          )}
        </div>

        <p className="kpi-value break-words leading-tight text-base" title={String(value)}>{value || 'N/A'}</p>
        {sub && <p className="kpi-sub mt-0.5 leading-tight">{sub}</p>}
      </div>
    </div>
  </div>
);

