      case 7: // Preview (Old Step 5, now 7)
        return (
          <div className="animate-in slide-in-from-right-4 duration-300">
            <div className="bg-gray-100 dark:bg-gray-800 p-8 rounded-xl border border-gray-200 dark:border-gray-700">
