    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const list = type === 'uae' ? [...data.delegations.uae] : [...data.delegations.partner];
        list[index].imageUrl = reader.result as string;
        setData({
          ...data,
          delegations: {
            ...data.delegations,
            [type]: list
          }
        });
      };
      reader.readAsDataURL(file);
    }
   };

