        'Abu Dhabi': 'أبوظبي',
        'Dubai': 'دبي',
        'Sharjah': 'الشارقة',
        'Ajman': 'عجمان',
        'Umm Al Quwain': 'أم القيوين',
        'Ras Al Khaimah': 'رأس الخيمة',
        'Fujairah': 'الفجيرة'
     };
     return map[name] || name;
  };

