      {/* --- PAGE 5: DELEGATIONS (Standalone) --- */}
      <PageContainer footer={<DefaultFooter />} className="shadow-xl print:shadow-none mb-8 print:mb-0">
        <HeaderBand country={data.country} reportId={report.id} title={t('loginTitle')} />

