import { Report, AuditLog, UserProfile } from '../types';
import { MOCK_REPORTS, MOCK_AUDIT_LOGS } from '../constants';

const STORAGE_KEYS = {
  REPORTS: 'uae_lmi_reports',
  LOGS: 'uae_lmi_logs',
  USERS: 'uae_lmi_users'
};

// --- STATIC DEFAULT USERS (Accessible on ALL devices) ---
const DEFAULT_ADMIN: UserProfile = {
  id: 'u-admin',
  fullName: 'System Administrator',
  email: 'admin', 
  role: 'admin',
  password: 'admin', 
  avatarUrl: 'https://ui-avatars.com/api/?name=Admin&background=0D8ABC&color=fff'
};

// --- Low Level Helpers ---
const getStorage = <T>(key: string): T | null => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : null;
  } catch (e) {
    console.error('LocalStorage Read Error', e);
    return null;
  }
};

const setStorage = (key: string, value: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    console.error('LocalStorage Write Error', e);
  }
};

// --- Initialization Logic ---
const initializeStorage = () => {
  // 1. Reports - Seed only if missing
  const reports = getStorage<Report[]>(STORAGE_KEYS.REPORTS);
  if (!reports) {
    setStorage(STORAGE_KEYS.REPORTS, MOCK_REPORTS);
  }

  // 2. Logs - Seed only if missing
  const logs = getStorage<AuditLog[]>(STORAGE_KEYS.LOGS);
  if (!logs) {
    setStorage(STORAGE_KEYS.LOGS, MOCK_AUDIT_LOGS);
  }

  // 3. Ensure Admin exists in storage for consistency, but we also check memory
  const users = getStorage<UserProfile[]>(STORAGE_KEYS.USERS) || [];
  if (!users.find(u => u.id === 'u-admin')) {
    users.unshift(DEFAULT_ADMIN);
    setStorage(STORAGE_KEYS.USERS, users);
  }
};

// Run immediately
initializeStorage();

export const MockService = {
  // --- Auth ---
  validateUser: async (emailOrId: string, password: string): Promise<UserProfile | null> => {
    // 1. Check Hardcoded Admin FIRST (Guarantees access across devices)
    if ((emailOrId === DEFAULT_ADMIN.email || emailOrId === 'admin') && password === DEFAULT_ADMIN.password) {
      return DEFAULT_ADMIN;
    }

    // 2. Check LocalStorage for other users created on this specific device
    const users = getStorage<UserProfile[]>(STORAGE_KEYS.USERS) || [];
    const user = users.find(u => (u.email === emailOrId || u.email.split('@')[0] === emailOrId) && u.password === password);
    return user || null;
  },

  // --- Reports ---
  getReports: async (): Promise<Report[]> => {
    const reports = getStorage<Report[]>(STORAGE_KEYS.REPORTS) || [];
    return reports.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
  },

  getReportById: async (id: string): Promise<Report | undefined> => {
    const reports = getStorage<Report[]>(STORAGE_KEYS.REPORTS) || [];
    return reports.find(r => r.id === id);
  },

  saveReport: async (report: Report): Promise<void> => {
    const reports = getStorage<Report[]>(STORAGE_KEYS.REPORTS) || [];
    const index = reports.findIndex(r => r.id === report.id);

    if (index >= 0) {
      reports[index] = report;
    } else {
      reports.push(report);
    }

    setStorage(STORAGE_KEYS.REPORTS, reports);
  },

  deleteReport: async (id: string): Promise<void> => {
    const reports = getStorage<Report[]>(STORAGE_KEYS.REPORTS) || [];
    const filtered = reports.filter(r => r.id !== id);
    setStorage(STORAGE_KEYS.REPORTS, filtered);
  },

  // --- Audit Logs ---
  getAuditLogs: async (): Promise<AuditLog[]> => {
    return getStorage<AuditLog[]>(STORAGE_KEYS.LOGS) || [];
  },

  addAuditLog: async (log: AuditLog): Promise<void> => {
    const logs = getStorage<AuditLog[]>(STORAGE_KEYS.LOGS) || [];
    logs.unshift(log);
    setStorage(STORAGE_KEYS.LOGS, logs);
  },

  // --- Users ---
  getUsers: async (): Promise<UserProfile[]> => {
    const users = getStorage<UserProfile[]>(STORAGE_KEYS.USERS) || [];
    // Ensure admin is always in the list view
    if (!users.find(u => u.id === 'u-admin')) {
      return [DEFAULT_ADMIN, ...users];
    }
    return users;
  },

  addUser: async (user: UserProfile): Promise<void> => {
    const users = getStorage<UserProfile[]>(STORAGE_KEYS.USERS) || [];
    users.push(user);
    setStorage(STORAGE_KEYS.USERS, users);
  },

  deleteUser: async (id: string): Promise<void> => {
    if (id === 'u-admin') {
      throw new Error("Cannot delete the root admin.");
    }
    const users = getStorage<UserProfile[]>(STORAGE_KEYS.USERS) || [];
    const filtered = users.filter(u => u.id !== id);
    setStorage(STORAGE_KEYS.USERS, filtered);
  },

  updatePassword: async (userId: string, newPass: string): Promise<void> => {
    if (userId === 'u-admin') {
      // We cannot update the hardcoded admin password in this Mock architecture
      console.warn("Cannot update hardcoded admin password in Mock Mode.");
      return;
    }
    const users = getStorage<UserProfile[]>(STORAGE_KEYS.USERS) || [];
    const index = users.findIndex(u => u.id === userId);

    if (index !== -1) {
      users[index].password = newPass;
      setStorage(STORAGE_KEYS.USERS, users);
    }
  },

  updateApiKey: async (userId: string, apiKey: string): Promise<UserProfile | null> => {
    // For admin, we save to local storage even if it's hardcoded logic
    const users = getStorage<UserProfile[]>(STORAGE_KEYS.USERS) || [];
    const index = users.findIndex(u => u.id === userId);

    if (index !== -1) {
      users[index].apiKey = apiKey;
      setStorage(STORAGE_KEYS.USERS, users);
      return users[index];
    } 
    // If admin is missing from local storage (rare), add them back with key
    else if (userId === 'u-admin') {
      const newAdmin = { ...DEFAULT_ADMIN, apiKey };
      users.unshift(newAdmin);
      setStorage(STORAGE_KEYS.USERS, users);
      return newAdmin;
    }
    return null;
  }
};

