                {/* Points of Discussion */}
                <div className="space-y-4 pt-6 border-t dark:border-gray-700">
                   <h4 className="font-bold text-gray-800 dark:text-white flex items-center gap-2"><MessageSquare size={18} /> {t('pointsDiscussion')}</h4>
