  fullName: 'System Administrator',
  email: 'admin',
  role: 'admin',
  password: 'admin',
  avatarUrl: 'https://ui-avatars.com/api/?name=Admin&background=0D8ABC&color=fff',
  apiKey: ''
};

function initializeDatabase() {
  db.serialize(() => {
    // 1. Users Table
    db.run(`CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      email TEXT,
      fullName TEXT,
      role TEXT,
      password TEXT,
      avatarUrl TEXT,
      apiKey TEXT
    )`);

    // 2. Reports Table (Data stored as JSON string)
    db.run(`CREATE TABLE IF NOT EXISTS reports (
      id TEXT PRIMARY KEY,
      userId TEXT,
      title TEXT,
      status TEXT,
      updatedAt TEXT,
      data TEXT
    )`);

    // 3. Logs Table
    db.run(`CREATE TABLE IF NOT EXISTS logs (
      id TEXT PRIMARY KEY,
      action TEXT,
      user TEXT,
      timestamp TEXT,
      details TEXT
    )`);

    // --- FORCE ADMIN SEED ---
    // This ensures the admin user always exists with the known password, 
    // fixing login issues if the DB was in a partial state.
    const adminStmt = db.prepare("INSERT OR REPLACE INTO users (id, email, fullName, role, password, avatarUrl, apiKey) VALUES (?, ?, ?, ?, ?, ?, ?)");
    adminStmt.run(DEFAULT_ADMIN.id, DEFAULT_ADMIN.email, DEFAULT_ADMIN.fullName, DEFAULT_ADMIN.role, DEFAULT_ADMIN.password, DEFAULT_ADMIN.avatarUrl, DEFAULT_ADMIN.apiKey);
    adminStmt.finalize();
    console.log("Admin account ensured: admin / admin");

    db.get("SELECT count(*) as count FROM reports", (err, row) => {
      if (row && row.count === 0) {
        console.log("Seeding default report...");
        const stmt = db.prepare("INSERT INTO reports VALUES (?, ?, ?, ?, ?, ?)");
        stmt.run(DEFAULT_REPORT.id, DEFAULT_REPORT.userId, DEFAULT_REPORT.title, DEFAULT_REPORT.status, DEFAULT_REPORT.updatedAt, JSON.stringify(DEFAULT_REPORT.data));
        stmt.finalize();
      }
    });
  });
}

