@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 99%;
    --foreground: 217 32% 17%;

    --primary: 217 91% 26%;
    --primary-light: 217 91% 35%;
    --primary-dark: 217 91% 18%;
    --primary-foreground: 210 40% 98%;

    --secondary: 217 19% 95%;
    --secondary-foreground: 222 47% 11%;

    --accent: 37 92% 50%;
    --accent-light: 37 92% 65%;
    --accent-foreground: 210 40% 98%;

    --muted: 217 19% 96%;
    --muted-foreground: 215 16% 47%;

    --border: 214 32% 91%;
    --input: 214 32% 91%;
    --ring: 217 91% 26%;
  }

  .dark {
    --background: 222 47% 11%;
    --foreground: 210 40% 98%;

    --primary: 217 91% 36%;
    --primary-light: 217 91% 45%;
    --primary-dark: 217 91% 26%;
    --primary-foreground: 222 47% 11%;

    --secondary: 217 32% 17%;
    --secondary-foreground: 210 40% 98%;

    --accent: 37 92% 50%;
    --accent-light: 37 92% 60%;
    --accent-foreground: 222 47% 11%;

    --muted: 217 32% 17%;
    --muted-foreground: 215 20% 65%;

    --border: 217 32% 20%;
    --input: 217 32% 20%;
    --ring: 217 91% 36%;
  }

  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
    font-family: 'Sakkal Majalla', 'Inter', 'Noto Naskh Arabic', sans-serif;
    font-size: 18px; /* Increased base size */
  }
}

/* Specific Font Rules for Sakkal Majalla Support */
[lang="ar"], [dir="rtl"], .report-font {
  font-family: 'Sakkal Majalla', 'Amiri', 'Noto Naskh Arabic', serif !important;
}

/* ===============================
   MINISTERIAL TYPOGRAPHY
================================ */
.report-font {
  font-family: 'Sakkal Majalla', 'Amiri', 'Noto Naskh Arabic', serif !important;
}

.report-h1 {
  @apply text-5xl font-bold tracking-tight text-primary-dark mb-8 border-b-4 border-accent pb-6;
  font-family: 'Sakkal Majalla', 'Amiri', 'Noto Naskh Arabic', serif !important;
}

.report-h2 {
  @apply text-3xl font-bold text-primary mb-6 flex items-center gap-4;
  font-family: 'Sakkal Majalla', 'Amiri', 'Noto Naskh Arabic', serif !important;
}

.report-h3 {
  @apply text-2xl font-bold text-gray-800 mb-4 border-s-8 border-accent ps-4;
  font-family: 'Sakkal Majalla', 'Amiri', 'Noto Naskh Arabic', serif !important;
}

/* KPI / INDICATOR SYSTEM REFINED */
@layer components {
  .kpi-card {
    @apply bg-white border-2 border-gray-100 rounded-2xl p-4 shadow-sm hover:shadow-md transition-shadow flex items-center gap-4;
  }
  .kpi-icon-box {
