@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 99%;
    --foreground: 217 32% 17%;
    --primary: 217 91% 26%;
    --primary-light: 217 91% 35%;
    --primary-dark: 217 91% 18%;
    --accent: 37 92% 50%;
    --border: 214 32% 91%;
  }

  .dark {
    --background: 222 47% 11%;
    --foreground: 210 40% 98%;
    --primary: 217 91% 36%;
    --border: 217 32% 20%;
  }

  body {
    @apply bg-background text-foreground;
    font-family: 'Sakkal Majalla', 'Noto Naskh Arabic', 'Inter', sans-serif;
  }
}

/* Force Sakkal Majalla for report elements */
.report-font, [lang="ar"], [dir="rtl"] {
  font-family: 'Sakkal Majalla', 'Noto Naskh Arabic', 'Amiri', serif !important;
}

/* Ministerial Heading System (+2pt & Bold) */
.report-title-main {
  @apply text-6xl font-bold text-gray-900 mb-2; /* +2pt larger than before */
}

.report-h1 {
  @apply text-5xl font-bold text-primary-dark mb-6 border-b-4 border-accent pb-4;
}

.report-h2 {
  @apply text-3xl font-bold text-primary-dark mb-4 flex items-center gap-4;
}

.report-h3 {
  @apply text-2xl font-bold text-gray-800 mb-3 border-s-8 border-accent ps-4;
}

/* Refined KPI Grid: Horizontal Layout (Icon next to Text) */
@layer components {
  .kpi-card {
    @apply bg-white border-2 border-gray-100 rounded-2xl p-5 shadow-sm flex items-center gap-5 transition-all;
  }
  .kpi-icon-container {
    @apply w-14 h-14 bg-primary/5 rounded-2xl flex items-center justify-center border border-primary/10 shrink-0;
  }
  .kpi-label {
    @apply text-sm font-bold uppercase tracking-widest text-gray-500 mb-1 block;
  }
  .kpi-value {
    @apply text-2xl font-bold text-gray-900 leading-tight;
  }
}

/* Print Specifics */
@media print {
  @page { size: A4; margin: 0; }
  body { background: white !important; }
  .no-print { display: none !important; }
  .page-break {
    break-after: page;
    width: 210mm;
    height: 297mm;
    overflow: hidden;
    position: relative;
    padding: 15mm 20mm;
  }
  .avoid-break { break-inside: avoid; }
}

import React from "react";
import { ShieldAlert } from "lucide-react";

export const PageContainer: React.FC<{
  children?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
}> = ({ children, footer, className = "" }) => (
  <div className={`w-[210mm] h-[297mm] bg-white mx-auto flex flex-col page-break relative overflow-hidden report-font ${className}`}>
    <div className="flex-1 overflow-visible">{children}</div>
    {footer && (
      <div className="mt-auto pt-6 border-t border-gray-100 pb-2">
        {footer}
      </div>
    )}
  </div>
);

export const HeaderBand = ({ country, reportId, title, flagUrl }: any) => {
  const getFlagCode = (c: string) => {
    const lower = (c || '').toLowerCase();
    if (lower.includes('india')) return 'in';
    if (lower.includes('philippines')) return 'ph';
    return 'ae'; 
  };
  const flagSrc = flagUrl || `https://flagcdn.com/w320/${getFlagCode(country)}.png`;

  return (
    <div className="flex items-center justify-between border-b-4 border-primary pb-4 mb-8">
      <div className="flex items-center gap-5">
        <img src={flagSrc} className="h-10 w-auto shadow-md rounded-sm" alt={country} />
