                <span className="text-sm">Two-Factor Auth</span>
                <div className="w-10 h-5 bg-white/20 rounded-full relative"><div className="absolute left-1 top-1 w-3 h-3 bg-white/40 rounded-full"></div></div>
              </div>
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
