@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 99%;
    --foreground: 217 32% 17%;
    --primary: 217 91% 26%;
    --primary-light: 217 91% 35%;
    --primary-dark: 217 91% 18%;
    --accent: 37 92% 50%;
    --border: 214 32% 91%;
  }

  .dark {
    --background: 222 47% 11%;
    --foreground: 210 40% 98%;
    --primary: 217 91% 36%;
    --border: 217 32% 20%;
  }

  body {
    @apply bg-background text-foreground;
    font-family: 'Inter', sans-serif;
    font-size: 14px; /* Dashboard standard scale */
  }
}

/* Sakkal Majalla for Reports only - No side effects on Dashboard */
.report-font, [lang="ar"] .report-font, .report-view {
  font-family: 'Sakkal Majalla', 'Noto Naskh Arabic', 'Amiri', serif !important;
}

/* Report Specific KPI layout: Horizontal, Compact */
@layer components {
  .report-kpi-card {
    @apply bg-white border border-gray-100 rounded-lg p-2.5 shadow-sm flex items-center gap-3 avoid-break;
  }
  .report-kpi-icon {
    @apply w-9 h-9 bg-primary/5 rounded flex items-center justify-center border border-primary/10 shrink-0;
  }
  .report-kpi-text {
    @apply flex flex-col justify-center min-w-0;
  }
  .report-kpi-label {
    @apply text-[11px] font-bold uppercase tracking-wider text-gray-400 mb-0.5; /* 10px -> 11px (+10%) */
  }
  .report-kpi-value {
    @apply text-base font-bold text-gray-900 leading-tight;
  }
}

/* Print Configuration - Locked Margins */
@media print {
  @page { size: A4; margin: 0; }
  body { background: white !important; }
  .no-print { display: none !important; }
  .page-break {
    break-after: page;
    width: 210mm;
    height: 297mm;
    overflow: hidden;
    position: relative;
    padding: 10mm 15mm; /* Original ministerial margins */
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
  }
  .avoid-break { break-inside: avoid; }
}

