                </div>
                <div className="flex gap-2">
                   <Button size="sm" onClick={handleSaveAnnouncement} className="flex-1">
                      <Save size={16} /> {t('save')}
                   </Button>
                   <Button size="sm" variant="outline" onClick={() => setIsEditingAnnouncement(false)} className="flex-1">
