            ) : (
              <div className="flex-1 flex flex-col">
                 <div className="flex-1 text-gray-700 dark:text-gray-300 leading-relaxed text-sm italic mb-4">
                    {language === 'ar' ? announcement?.message_ar : announcement?.message_en}
