              <h4 className="text-xs font-bold text-primary uppercase tracking-widest mb-4 border-b pb-2">{t('workersBySector')}</h4>
              <div className="space-y-3">
                 {data.uaeWorkforceStats.mohre.bySector.slice(0, 8).map((sec, i) => (
