                      ))}
                      {data.delegations[type as 'uae'|'partner'].length === 0 && <div className="text-center text-gray-400 italic text-sm">No members recorded for this delegation.</div>}
                   </div>
                </div>
             ))}
          </div>
        </PageContainer>
      </div>
    </div>
  );
