/* Custom Scrollbar */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #888; border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: #555; }

/* ===============================
   PRINT CONFIGURATION
================================ */
@media print {
  @page {
    size: A4;
    margin: 0;
  }

  html, body {
    background: #ffffff !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
    width: 210mm;
    height: auto;
    overflow: visible;
  }

  .no-print {
    display: none !important;
  }

  /* Strict A4 Height to prevent footer displacement */
  .page-break {
    break-after: page;
    page-break-after: always;
    width: 210mm;
    min-height: 297mm; 
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    padding-bottom: 15mm; /* Buffer for footer */
  }

  .avoid-break {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  /* Rich Text Rendering Styles for Print */
  .rich-text-content strong { font-weight: 700; color: #111; }
  .rich-text-content em { font-style: italic; }
  .rich-text-content ul { list-style-type: disc; margin-left: 1.5rem; margin-top: 0.5rem; margin-bottom: 0.5rem; }
  .rich-text-content li { margin-bottom: 0.25rem; }

  [dir="rtl"] .rich-text-content ul { margin-left: 0; margin-right: 1.5rem; }
}

/* Web-view support for rich text rendering */
.rich-text-content strong { font-weight: 700; }
.rich-text-content em { font-style: italic; }
.rich-text-content ul { list-style-type: disc; margin-left: 1.5rem; }
[dir="rtl"] .rich-text-content ul { margin-left: 0; margin-right: 1.5rem; }

/* ===============================
   KPI / INDICATOR SYSTEM
================================ */
@layer components {
  .kpi-card {
    @apply bg-white border border-gray-200 rounded-xl p-3 shadow-sm;
  }

  .kpi-row {
    @apply flex items-start gap-3;
  }

  .kpi-icon {
    @apply w-8 h-8 rounded-lg flex items-center justify-center
           border border-gray-200 bg-gray-50;
  }

  .kpi-label {
    @apply text-[10px] font-black uppercase tracking-widest text-gray-500 mb-0.5 block;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .kpi-value {
    @apply text-lg font-serif font-bold text-gray-900 leading-tight;
  }

  .kpi-sub {
    @apply text-[9px] text-gray-500 italic;
  }

  .kpi-chip {
    @apply text-[9px] font-bold uppercase tracking-wider
           px-2 py-0.5 rounded-full border;
  }

  .chip-ok {
    @apply bg-green-50 text-green-800 border-green-200;
  }

  .chip-warn {
    @apply bg-amber-50 text-amber-800 border-amber-200;
  }

  .chip-info {
    @apply bg-blue-50 text-blue-800 border-blue-200;
  }

  .chip-restrict {
    @apply bg-red-50 text-red-800 border-red-200;
  }

  /* ===============================
     SECTION RAIL
  ================================ */
  .section-rail {
    @apply relative ps-4;
  }

  .section-rail:before {
    content: "";
    position: absolute;
    inset-inline-start: 0;
    top: 4px;
    bottom: 4px;
    width: 3px;
    border-radius: 999px;
    background: hsl(var(--primary));
    opacity: 0.18;
  }
}

