        </PageContainer>

        {/* --- PAGE 5+: RELATIONSHIP SUMMARY --- */}
        {interactionChunks.length > 0 ? interactionChunks.map((chunk, cIdx) => (
          <PageContainer key={`int-${cIdx}`} footer={<DefaultFooter />} className="shadow-xl print:shadow-none mb-8 print:mb-0">
