import express from 'express';
import path from 'path';
import cors from 'cors';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

// SQLite requires CommonJS import style in some environments
const require = createRequire(import.meta.url);
const sqlite3 = require('sqlite3').verbose();

// Setup paths
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = 4173;
const DB_FILE = path.join(__dirname, 'database.sqlite');

// Middleware
app.use(cors());
app.use(express.json({ limit: '50mb' }));

// --- DATABASE SETUP ---
const db = new sqlite3.Database(DB_FILE, (err) => {
  if (err) {
    console.error('Error opening database', err.message);
  } else {
    console.log('Connected to SQLite database.');
    initializeDatabase();
  }
});

const DEFAULT_ADMIN = {
  id: 'u-admin',
  fullName: 'System Administrator',
  email: 'admin',
  role: 'admin',
  password: 'admin',
  avatarUrl: 'https://ui-avatars.com/api/?name=Admin&background=0D8ABC&color=fff',
  apiKey: ''
};

function initializeDatabase() {
  db.serialize(() => {
    // 1. Users Table
    db.run(`CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      email TEXT,
      fullName TEXT,
      role TEXT,
      password TEXT,
      avatarUrl TEXT,
      apiKey TEXT
    )`);

    // 2. Reports Table (Data stored as JSON string)
    db.run(`CREATE TABLE IF NOT EXISTS reports (
      id TEXT PRIMARY KEY,
      userId TEXT,
      title TEXT,
      status TEXT,
      updatedAt TEXT,
      data TEXT
    )`);

    // 3. Logs Table
    db.run(`CREATE TABLE IF NOT EXISTS logs (
      id TEXT PRIMARY KEY,
      action TEXT,
      user TEXT,
      timestamp TEXT,
      details TEXT
    )`);

    // 4. Announcements Table
    db.run(`CREATE TABLE IF NOT EXISTS app_announcements (
      id TEXT PRIMARY KEY,
      message_en TEXT,
      message_ar TEXT,
      updatedAt TEXT,
      updatedBy TEXT
    )`);

    // 5. Letter Logs Table
    db.run(`CREATE TABLE IF NOT EXISTS letter_logs (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      internal_ref TEXT,
      topic TEXT,
      external_ref TEXT,
      status TEXT DEFAULT 'open',
      label TEXT,
      label_color TEXT,
      notes TEXT,
      attachment_url TEXT,
      created_by TEXT,
      created_by_id TEXT,
      created_at TEXT,
      updated_at TEXT
    )`);

    // 6. Letter Log Notes Table
    db.run(`CREATE TABLE IF NOT EXISTS letter_log_notes (
      id TEXT PRIMARY KEY,
      letter_id TEXT,
      note TEXT,
      created_by TEXT,
      created_by_id TEXT,
      created_at TEXT,
      FOREIGN KEY(letter_id) REFERENCES letter_logs(id)
    )`);

    // --- SEEDING ---
    db.get("SELECT * FROM users WHERE id = ?", [DEFAULT_ADMIN.id], (err, row) => {
      if (!row) {
        const adminStmt = db.prepare("INSERT INTO users (id, email, fullName, role, password, avatarUrl, apiKey) VALUES (?, ?, ?, ?, ?, ?, ?)");
        adminStmt.run(DEFAULT_ADMIN.id, DEFAULT_ADMIN.email, DEFAULT_ADMIN.fullName, DEFAULT_ADMIN.role, DEFAULT_ADMIN.password, DEFAULT_ADMIN.avatarUrl, DEFAULT_ADMIN.apiKey);
        adminStmt.finalize();
      }
    });
  });
}

