    if (window.confirm('Are you sure you want to delete this user? This action is permanent.')) {
      try {
        await MockService.deleteUser(id);
        await fetchUsers(); // Refresh immediately
      } catch (e: any) {
        alert(e.message || "Failed to remove user");
