/* ===============================
   KPI / INDICATOR SYSTEM
================================ */
@layer components {
  .kpi-card {
    @apply bg-white border border-gray-200 rounded-xl p-3 shadow-sm;
  }

  .kpi-row {
    @apply flex items-start gap-3;
  }

  .kpi-icon {
    @apply w-8 h-8 rounded-lg flex items-center justify-center
           border border-gray-200 bg-gray-50;
  }

  .kpi-label {
    @apply text-[9px] font-extrabold uppercase tracking-widest text-gray-500 mb-0.5 block;
  }

  /* Scoped report readability improvements */
  .report-root .kpi-label {
    font-weight: 600 !important;
    display: inline-block !important;
    transform: scale(1.03);
    transform-origin: right center;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
  }

  .kpi-value {
    @apply text-lg font-serif font-bold text-gray-900 leading-tight;
