      setIsFetchingAI(false);
    }
  };

  const handleFetchNews = async () => {
     if (!data.country) {
       alert("Please enter a country name first.");
       return;
     }

     setIsFetchingNews(true);
     console.log(`[AI News] Initiating fetch for: ${data.country}, language: ${language}`);

     const apiKey = user?.apiKey || process.env.API_KEY;
     if (!apiKey) { 
       console.error("[AI News] No API key available.");
       alert("No API Key found. Please add a Personal API Key in Settings.");
       setIsFetchingNews(false); 
       return; 
     }

     try {
       const ai = new GoogleGenAI({ apiKey });
       const targetLanguage = language === 'ar' ? 'Arabic' : 'English';
       const prompt = `Identify 3 recent official news items or press releases (from 2023-2025) specifically regarding bilateral workforce cooperation, diplomatic labor visits, or new labor market agreements between the UAE (Ministry of Human Resources) and ${data.country}. 

       MANDATORY: Return the results strictly as a JSON array. 
       Format: [{"title": "...", "source": "...", "date": "...", "summary": "..."}]
       All text values must be in ${targetLanguage}. 
       Only provide the JSON array, no other conversational text.`;

       console.log("[AI News] Sending request to Gemini with prompt:", prompt);

       const response: GenerateContentResponse = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
          config: { 
            tools: [{ googleSearch: {} }],
            responseMimeType: 'application/json'
          },
       });

       console.log("[AI News] Response received. Raw response:", response);

       if (response.text) {
         // Clean JSON string in case the model wrapped it in markdown code blocks
         const jsonStr = response.text.replace(/```json/g, '').replace(/```/g, '').trim();
         console.log("[AI News] Cleaned JSON string:", jsonStr);

         const newsItems = JSON.parse(jsonStr);

         if (Array.isArray(newsItems)) {
           const formattedNews: NewsItem[] = newsItems.map((n: any) => ({
              id: uuidv4(),
              title: n.title || 'Untitled News',
              source: n.source || 'Official Source',
              date: n.date || new Date().toISOString().split('T')[0],
              summary: n.summary || 'Summary not available.'
           }));

           console.log(`[AI News] Successfully parsed ${formattedNews.length} items.`);
           setData(prev => ({ 
             ...prev, 
             relatedNews: [...prev.relatedNews, ...formattedNews] 
           }));
         } else {
           console.error("[AI News] Response was not an array.", newsItems);
           throw new Error("Invalid format received from AI.");
         }
       } else {
         console.warn("[AI News] Empty response text from model.");
         throw new Error("No news content returned from AI.");
       }
     } catch (error: any) { 
       console.error("[AI News] Error during AI news fetch:", error);
       alert(`News Fetch Failed: ${error.message || "Unknown error"}. Please check your API key settings.`);
     } finally { 
       setIsFetchingNews(false); 
     }
  };

