        <div className="space-y-3">
          {STEPS.map((step, idx) => (
            <button key={step.id} onClick={() => setCurrentStep(idx)} className={`w-full flex items-center gap-4 p-4 rounded-xl transition-all text-left ${idx === currentStep ? 'bg-primary text-white shadow-xl translate-x-2' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
              <step.icon size={20} /><span className="text-sm font-bold uppercase tracking-wider">{step.label}</span>
            </button>
          ))}
        </div>
        <div className="lg:col-span-3 space-y-8">
          <Card className="min-h-[500px] p-8 shadow-2xl">{renderStep()}</Card>
          <div className="flex justify-between items-center pt-6">
            <Button variant="ghost" onClick={() => setCurrentStep(Math.max(0, currentStep - 1))} disabled={currentStep === 0}><ArrowLeft size={18} /> {t('back')}</Button>
            <div className="flex gap-4">
              <Button variant="outline" onClick={() => handleSave('draft')}><Save size={18} /> {t('save')}</Button>
              {currentStep < STEPS.length - 1 ? (
                <Button onClick={() => setCurrentStep(currentStep + 1)} className="px-10">{t('next')} <ArrowRight size={18} /></Button>
              ) : (
                <Button onClick={() => handleSave('completed')} className="bg-green-600 hover:bg-green-700 px-10">{t('finish')} <CheckCircle size={18} /></Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useLanguage } from '../context/LanguageContext';
import { MockService } from '../services/mockService';
import { Report, UserProfile } from '../types';
import { Card, Button, Badge } from '../components/ui/LayoutComponents';
import { Search, Plus, Edit3, Trash2, Printer, FileText, Lock, RefreshCw } from 'lucide-react';
import { format } from 'date-fns';

export default function ReportsList() {
  const { user } = useAuth();
  const { t } = useLanguage();
  // Manual hash navigation
  const navigate = (path: string) => {
    window.location.hash = path.startsWith('/') ? path : `/${path}`;
  };
  const [reports, setReports] = useState<Report[]>([]);
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [reportsData, usersData] = await Promise.all([
        MockService.getReports(),
        MockService.getUsers()
      ]);
      setReports(reportsData);
      setUsers(usersData);
    } catch (error) {
      console.error("Fetch failed", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleDelete = async (id: string) => {
    if (user?.role !== 'admin') {
       alert("Unauthorized: Only administrators can delete reports.");
       return;
    }
    if (window.confirm('Are you sure you want to delete this report? This action cannot be undone.')) {
      setDeletingId(id);
      try {
        await MockService.deleteReport(id, user.role);
        await fetchData();
      } catch (error) {
        console.error("Delete failed", error);
        alert("Failed to delete report.");
      } finally {
        setDeletingId(null);
      }
    }
  };

  const handlePrint = (id: string) => {
    const href = window.location.href;
    const hashIndex = href.indexOf('#');
    let baseUrl = hashIndex !== -1 ? href.substring(0, hashIndex) : href;
    if (baseUrl.endsWith('/')) baseUrl = baseUrl.slice(0, -1);
    const printUrl = `${baseUrl}/#/print/${id}`;
    window.open(printUrl, '_blank');
  };

  const getUserName = (userId: string) => {
    const found = users.find(u => u.id === userId);
    return found ? found.fullName : 'Unknown User';
  };

  const filteredReports = reports.filter(r => 
    r.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.data.country.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-serif font-bold text-primary-dark dark:text-white">
            {t('reports')}
          </h1>
          <p className="text-muted-foreground mt-1 dark:text-gray-400">
            {t('reportsDescription') || 'Access and manage all generated labour market intelligence reports.'}
          </p>
        </div>
        <Button onClick={() => navigate('/wizard')}>
          <Plus size={20} />
          {t('createNew')}
        </Button>
      </div>

      <div className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <Search className="text-gray-400" size={20} />
        <input 
          placeholder="Search reports by title or country..." 
          className="flex-1 outline-none text-sm bg-transparent dark:text-white"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <button onClick={fetchData} className="text-gray-400 hover:text-primary transition-colors" title="Refresh">
          <RefreshCw size={18} />
        </button>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-card overflow-hidden border border-gray-100 dark:border-gray-700">
        {loading ? (
          <div className="p-12 text-center text-gray-500 flex flex-col items-center">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mb-2"></div>
             Loading reports...
          </div>
        ) : filteredReports.length === 0 ? (
          <div className="p-12 text-center text-gray-500 dark:text-gray-400">
            <FileText size={48} className="mx-auto text-gray-300 dark:text-gray-600 mb-4" />
            <p>No reports found.</p>
          </div>
        ) : (
          <table className="w-full text-left">
            <thead className="bg-secondary/50 dark:bg-gray-700/50 border-b dark:border-gray-700">
              <tr>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">{t('country')}</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Report Title</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Created By</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Last Modified</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300">Status</th>
                <th className="p-4 font-semibold text-sm text-gray-600 dark:text-gray-300 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-gray-700">
              {filteredReports.map((report) => {
                const isOwner = user?.id === report.userId;
                const isAdmin = user?.role === 'admin';
                const canDelete = isAdmin;
                const isDeleting = deletingId === report.id;

                const flagSrc = report.data.flagUrl || `https://flagcdn.com/w40/${report.data.country.toLowerCase().includes('philippines') ? 'ph' : report.data.country.toLowerCase().includes('india') ? 'in' : 'ae'}.png`;

                return (
                  <tr key={report.id} className={`hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors group ${isDeleting ? 'opacity-50 pointer-events-none' : ''}`}>
                    <td className="p-4 font-medium text-primary dark:text-primary-light flex items-center gap-3">
                       <img 
                        src={flagSrc} 
                        className="w-6 h-auto shadow-sm rounded-sm object-cover"
                        alt="flag"
                        onError={(e) => e.currentTarget.style.display = 'none'}
                       />
                       {report.data.country}
                    </td>
                    <td className="p-4 text-sm font-medium dark:text-gray-200">{report.title}</td>
                    <td className="p-4 text-sm text-gray-500 dark:text-gray-400 whitespace-nowrap">
                      {getUserName(report.userId)}
                      {isOwner && <span className="ml-2 text-[10px] bg-blue-100 dark:bg-blue-900 text-blue-700 dark:text-blue-200 px-1.5 py-0.5 rounded font-bold uppercase tracking-wider">You</span>}
                    </td>
                    <td className="p-4 text-sm text-gray-500 dark:text-gray-400">
                      {format(new Date(report.updatedAt), 'MMM dd, yyyy')}
                    </td>
                    <td className="p-4">
                      <Badge color={report.status === 'completed' ? 'green' : 'yellow'}>
                        {t(report.status)}
                      </Badge>
                    </td>
                    <td className="p-4 text-right">
                      <div className="flex items-center justify-end gap-2">
                         <button 
                           onClick={() => navigate(`/wizard/${report.id}`)}
                           className="p-2 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400 transition-colors"
                           title="Edit Report"
                         >
                           <Edit3 size={16} />
                         </button>

                         {canDelete && (
                            <button 
                              onClick={() => handleDelete(report.id)}
                              className="p-2 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg text-red-500 transition-colors"
                              title="Delete Report"
                            >
                              {isDeleting ? <div className="w-4 h-4 border-2 border-red-500 border-t-transparent rounded-full animate-spin"></div> : <Trash2 size={16} />}
                            </button>
                         )}

                        <button 
                          onClick={() => handlePrint(report.id)}
                          className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg text-gray-600 dark:text-gray-300 transition-colors"
                          title="Export PDF"
                        >
                          <Printer size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import express from 'express';
import path from 'path';
import cors from 'cors';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

// SQLite requires CommonJS import style in some environments
const require = createRequire(import.meta.url);
const sqlite3 = require('sqlite3').verbose();

// Setup paths
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = 4173;
const DB_FILE = path.join(__dirname, 'database.sqlite');

// Middleware
app.use(cors());
app.use(express.json({ limit: '50mb' }));

// --- DATABASE SETUP ---
const db = new sqlite3.Database(DB_FILE, (err) => {
  if (err) {
    console.error('Error opening database', err.message);
  } else {
    console.log('Connected to SQLite database.');
    initializeDatabase();
  }
});

const DEFAULT_ADMIN = {
  id: 'u-admin',
  fullName: 'System Administrator',
  email: 'admin',
  role: 'admin',
  password: 'admin',
  avatarUrl: 'https://ui-avatars.com/api/?name=Admin&background=0D8ABC&color=fff',
  apiKey: ''
};

function initializeDatabase() {
  db.serialize(() => {
    // 1. Users Table
    db.run(`CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      email TEXT,
      fullName TEXT,
      role TEXT,
      password TEXT,
      avatarUrl TEXT,
      apiKey TEXT
    )`);

    // 2. Reports Table (Data stored as JSON string)
    db.run(`CREATE TABLE IF NOT EXISTS reports (
      id TEXT PRIMARY KEY,
      userId TEXT,
      title TEXT,
      status TEXT,
      updatedAt TEXT,
      data TEXT
    )`);

    // 3. Logs Table
    db.run(`CREATE TABLE IF NOT EXISTS logs (
      id TEXT PRIMARY KEY,
      action TEXT,
      user TEXT,
      timestamp TEXT,
      details TEXT
    )`);

    // 4. Announcements Table
    db.run(`CREATE TABLE IF NOT EXISTS app_announcements (
      id TEXT PRIMARY KEY,
      message_en TEXT,
      message_ar TEXT,
      updatedAt TEXT,
      updatedBy TEXT
    )`);

    // 5. Letter Logs Table
    db.run(`CREATE TABLE IF NOT EXISTS letter_logs (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      internal_ref TEXT,
      topic TEXT,
      external_ref TEXT,
      status TEXT DEFAULT 'open',
      label TEXT,
      label_color TEXT,
      notes TEXT,
      attachment_url TEXT,
      created_by TEXT,
      created_by_id TEXT,
      created_at TEXT,
      updated_at TEXT
    )`);

    // 6. Letter Log Notes Table
    db.run(`CREATE TABLE IF NOT EXISTS letter_log_notes (
      id TEXT PRIMARY KEY,
      letter_id TEXT,
      note TEXT,
      created_by TEXT,
      created_by_id TEXT,
      created_at TEXT,
      FOREIGN KEY(letter_id) REFERENCES letter_logs(id)
    )`);

    // --- SEEDING ---
    db.get("SELECT * FROM users WHERE id = ?", [DEFAULT_ADMIN.id], (err, row) => {
      if (!row) {
        const adminStmt = db.prepare("INSERT INTO users (id, email, fullName, role, password, avatarUrl, apiKey) VALUES (?, ?, ?, ?, ?, ?, ?)");
        adminStmt.run(DEFAULT_ADMIN.id, DEFAULT_ADMIN.email, DEFAULT_ADMIN.fullName, DEFAULT_ADMIN.role, DEFAULT_ADMIN.password, DEFAULT_ADMIN.avatarUrl, DEFAULT_ADMIN.apiKey);
        adminStmt.finalize();
      }
    });
  });
}

// --- API ENDPOINTS ---

// Announcement
app.get('/api/announcement', (req, res) => {
  db.get("SELECT * FROM app_announcements WHERE id = 'current'", [], (err, row) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(row || {});
  });
});

app.post('/api/announcement', (req, res) => {
