  if (userRole !== 'admin') {
    return res.status(403).json({ error: 'Permission denied. Only administrators can delete reports.' });
  }
  db.run("DELETE FROM reports WHERE id = ?", [req.params.id], (err) => {
    if (err) return res.status(500).json({ error: err.message });
