                <div className="grid grid-cols-1 gap-4">
                  {data.delegations.partner.slice(0, 1).map((d) => (
                      <div key={d.id} className="flex gap-8 items-start p-6 bg-gray-50 rounded-[1.5rem] border border-gray-100 shadow-sm">
