  children?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
}> = ({
  children,
  footer,
  className = ""
}) => (
  <div className={`w-[210mm] h-[297mm] bg-white mx-auto flex flex-col page-break relative overflow-hidden ${className}`}>
