  chip,
  tone = "info",
  labelClassName,
}: {
  icon: any;
  label: string;
  value: string | number;
  sub?: React.ReactNode; // Fix: Updated to React.ReactNode to allow JSX elements
  chip?: string;
  tone?: "ok" | "warn" | "info" | "restrict";
  labelClassName?: string;
}) => (
  <div className="kpi-card avoid-break h-full flex flex-col">
    <div className="kpi-row items-start">
      <div className="kpi-icon shrink-0 mt-0.5">
        <Icon size={16} className="text-primary" />
      </div>

      <div className="flex-1 min-w-0">
        <div className="flex justify-between items-start mb-1">
          <p className={`kpi-label pr-1 leading-tight ${labelClassName || ''}`}>{label}</p>
          {chip && (
            <span
              className={`kpi-chip shrink-0 ml-1 ${
                tone === "ok"
                  ? "chip-ok"
                  : tone === "warn"
                  ? "chip-warn"
                  : tone === "restrict"
                  ? "chip-restrict"
                  : "chip-info"
              }`}
            >
              {chip}
            </span>
          )}
        </div>

        <p className="kpi-value truncate block leading-tight text-sm font-sans text-gray-900" title={String(value)}>
           {value || 'N/A'}
        </p>

        {sub && <div className="kpi-sub mt-1 leading-tight">{sub}</div>}
      </div>
    </div>
  </div>
);

