  note: string;
  created_by: string;
  created_by_id: string;
  created_at: string;
}

export interface Delegate {
  id: string;
  name: string;
  title: string;
  imageUrl: string;
  bio: string;
}

export interface DateValue {
  value: string;
  date: string; // "As of..."
}

export interface LabelValue {
  name: string;
  value: number;
}

export interface RecentInteraction {
  id: string;
  title: string;
  date: string;
  type: string; // e.g., "Visit", "Phone Call", "Meeting"
  details: string; // Summary of the interaction
}

export interface PointOfDiscussion {
  id: string;
  title: string;
  content: string;
}

export interface NewsItem {
  id: string;
  title: string;
  source: string;
  date: string;
  summary: string;
}

export interface UaeWorkforceData {
  mohre: {
    totalPrivate: DateValue;
    totalDomestic: DateValue;
    byEmirate: LabelValue[]; // Abu Dhabi, Dubai, etc.
    bySector: LabelValue[];
  };
